window.__D("text/torat-shmuel/c012",{"p":[[2000510370,"שזהו ג\"כ ע\"י כח נה\"ב ג\"כ שהרי בכח נפשו הניזונת מאכילה ושתי' גשמי' הוא יכול לספר בשבחו של מקום והשראת נה\"ב הוא בחלל השמאלי שבלב שמלא דם כו'. וגם י\"ל שז\"ע קבלת מצות ואהבת לרעך כמוך קודם התפלה כמ\"ש בסדור שנכון לקבל קודם התפלה מצות ואהבת לרעך כמוך, שלכאו' מה\"ע ושייכות מצוה זו לתפלה, אלא שתהו ותיקון נק' ריעים זל\"ז, וענין ואהבת לרעך כמוך היינו לברר בחי' התהו שיהי' כמו בחי' התיקון כו'. ובכלליות השנה זהו\"ע בחי' ספה\"ע, ובדרך פרט בכל יום זהו ברכת ק\"ש כמשנת\"ל, ובכלל כמו סולם מוצב ארצה הנה אמרו סולם דא כבש המזבח, מוצב ארצה וראשו מגיע השמימה שריחם עולה לשמים, כ\"ה בענין התפלה שאמרו סולם דא צלותא מוצב ארצה שמתחילין התפלה מדברים קטנים שלא עשני עבד, ואח\"כ עולים בסולם היינו שכמו בסולם יש ד' שליבות, כן בתפלה ג\"כ חלקוה נגד ד' שליבות עד שעולה בבחי' וראשו מגיע השמימה הוא בחי' שמע ישראל, ישראל לי ראש כו', עד שבשמו\"ע אומרים ברוך אתה ה' הוא בחי' ברכה והמשכה בשם הוי' ע\"ד כמו בקרבנות שע\"י העלאת הקרבנות נעשה ריח ניחוח להוי' היינו ריח העלאה, עד שנעשה ניחוח הוא בחי' המשכה בשם הוי', וכ\"ה בתפילה שכנגד קרבנות ע\"י ההעלאה בסולם עי\"ז נמשך בשמו\"ע המשכה בשם הוי' כמו ע\"י קרבנות.\n<b></b>[כא)] והנה כמו המקריב קרבן הרי עבודתו בהעלאת והקרבת הקרבן הי' רק בעת הביאו את הקרבן להקריב, אבל אחרי אשר הקריב את קרבנו שוב הי' עבודתו לקיים כמו שקיבל עליו בעת הקרבת הקרבן בבחי' הסכם חזק, כ\"ה בעבודה שבלב זו תפלה אחרי ההתבוננות בתפלה והקרבת חלב ודם מנפשו הבהמי' צ\"ל נשאר בבחי' הסכם על כל היום, שהרי א\"א להיות בהתבוננו' כל היום כולו, ובפרט בעלי עסקים שאחרי התפלה ה\"ה עוסק בצרכי פרנסתו לפרנס בניו וב\"ב ורבות מח' טורדות מעבודה שא\"א לו להתבונן אז באריכות ההתבוננו' כ\"א בדרך קצרה, וגם זה לא כל אדם ולא בכל עת, וגם העוסקי' בתורה א\"א להם להיות בבחי' התבוננות בעת עסקם בתורה, לזאת צריך כל אדם אחר ההתבוננות בתפלה לעשות הסכם חזק להיות בבחי' סומ\"ר וע\"ט בניצוח והסכם חזק בל תמוט כלל וכלל, ועי\"ז נחשב לו ג\"כ לצדקה, כי מה לי בעת התפלה או כל זמן שנמשך אח\"כ פעולת התפלה עד תפלה השני' שמתבונן שנית, וכ\"ש להיות בבחי' אתכפי' להזהר מרצונות זרות המבלבלים, וע\"י שכובש את יצרו בלי לחשוב ולהיות סומ\"ר וע\"ט הרי ג\"ז כקרבן יחשב כי מה לי קטלא כולא או קטלא פלגא כו'.\n<b>ובכ\"ז</b> יובן שרש ענין קרי\"ס<sup data-n=\"1198\">25</sup> בענין הים ראה וינוס מה ראה ארונו של יוסף ראה, והיינו כי יוסף שלט ביצרו וכבשו במעשה דפוטיפרע ועמד בנסיון וסבל",[["1198","25","<b>ובכ\"ז יובן שרש ענין קרי\"ס</b>: בהבא לקמן (בפיסקא זו ושלאחרי') ראה רשימות הצ\"צ לתהלים יהל אור שם ע' תמא ואילך. אוה\"ת ויקהל שם ע' ב'רכ."]]],[2000510371,"יסורים קשים ומרים ושמו אותו בסוהר, ונמצא כי בירר חלקו בתהו, והרי לחלקו בירר כל בחי' התהו, ונמצא כי הקדמת התהו נגד חלקו אינו קדימה בעצם כ\"א כמו הקדמה לעצם הדבר, ולכן כשראה הים את ארונו נס מפניו, שהרי בירר כל חלקו בבחי' התהו, ולכן לגבי יוסף אינה טענה כלל מה שקדם ונברא בשלישי, [כי] הלא כ\"ז הוא בבחי' התיקון ויוסף בירר חלקו בתהו שקדם לתיקון ונעשה לו הקדמה לבד לבחי' התיקון והעיקר הוא התיקון שאחר התהו כו'. ובאמת גם לפני משה אין זה טענה נכונה כלל, שהרי משה הי' משמיטה ראשונה<sup data-n=\"1199\">26</sup>. אמנם מה שנס הים לפני ארונו של יוסף אין זה ענין קרי\"ס כלל, שמשמע מלשון נס שריחק א\"ע מן שפת הים ולא נבקע כלל, שאין לשון בקיעה בכלל ניסה ולא זה הי' המכוון, כי אם הי' המכוון שיוכלו ישראל לעבור ביבשה במקום אשר הי' ים תחלה וכאשר הם לא עברו את הים לרחבו כ\"א באותו צד שירדו בו עלו הי' די גם במה שנס הים מפני ארונו של יוסף, אבל באמת עיקר המכוון הי' בשביל שילכו ישראל תוך הים דוקא ביבשה שזה לא די בניסה כ\"א בבקיעה דוקא.\n<b></b>[כב)] וזהו ענין בוקע ים לפני משה דוקא, כי הנה כתי' אלה תולדות יעקב יוסף, ונת' פי' בכ\"ד<sup data-n=\"1200\">27</sup> שתולדות יעקב היינו הגילוי מבחי' יעקב, כי הולדה הוא ענין גילוי מהמוליד, והיינו כי יעקב הי' בחי' בריח התיכון המבריח מן הקצה אל הקצה, פי' מקצה השמים דלעילא עד קצה השמים דלתתא, ובכדי להיות גילוי ממנו לארץ זהו ע\"י יוסף בחי' יסוד ז\"א, כי יעקב ויוסף הם עץ ארז ואזוב ו\"ו והמילוי<sup data-n=\"1201\">28</sup> הוא ג\"כ וא\"ו, אבל משה ויעקב הנה אמרו שמשה מלגאו ויעקב מלבר<sup data-n=\"1202\">29</sup>, וא\"כ בכ\"מ שנאמר שיעקב הוא שם הנה שם עצמו משה מלגאו, וקרי\"ס הי' עוד לפני משה היינו למעלה מבחי' משה כו'. והענין הוא דהנה ים הוא בחי' מל' ים סוף סופא דכל דרגין, ולכן כשראה הים ארון יוסף הוא בחי' יסוד, ע\"ד הנה ארון הברית אדון כל הארץ, נס מפניו ע\"ד שארז\"ל הכלה הופכת פני' ואוכלת, אבל מ\"מ אין זה בקיעה שזה רומז על בחי' הביטול לגמרי כ\"א רק ע\"ד הכלה הופכת פניה, אבל מ\"מ היא אוכלת שלא נתבטלה לגמרי, אבל ענין בוקע ים לפני משה שנתבטל הים לגמרי ונקרע לקרעים, זה הי' מלפני משה היינו מבחי' גבוה אפי' ממדרגת משה שמשה מלגאו. וזהו ויולך ה' ברוח קדים הוא בחי' המשכה מאוא\"ס קדמונו",[["1199","26","<b>משה הי' משמיטה ראשונה</b>: ראה תו\"א שמות נא, ד."],["1200","27","<b>אלה תולדות יעקב יוסף ונת' פי' [ פירושו] בכ\"ד</b>: ראה בארוכה מאמרי אדה\"ז תקס\"ח ח\"ב ע' תרעז ואילך. ס\"ע תרפד ואילך. אוה\"ת ויחי שפה, ב ואילך. שפח, א ואילך. שצה, א ואילך. תד, ב ואילך. שם (כרך ו) תתשמז, ב ואילך. סה\"מ תרנ\"ג ע' רנח ואילך. עזר\"ת ע' קיז ואילך. סה\"מ מלוקט ח\"ג ע' רכא ואילך."],["1201","28","<b>יעקב ויוסף הם עץ ארץ ואזוב. . והמילוי</b>: ראה תו\"א ויגש מד, א. אוה\"ת בא ס\"ע שכא. שם (כרך ז) ע' ב'תרלב. סה\"מ תרכ\"ז ע' ריט. תרכ\"ט ע' כז. וע' שפו. וראה גם לקו\"ת חוקת ס, ד."],["1202","29","<b>שמשה מלגאו ויעקב מלבר</b>: ראה בארוכה אוה\"ת וארא ע' רח. ואתחנן ע' קעב ואילך. ועוד."]]],[2000510372,"של עולם בחי' קדמון לכל הקדומים ומשם יכול להפך סדרי השתלשלו' שמים יעשה יבשה כו'.\n<b>אך</b> בכדי שיומשך מבחי' רוח קדים לזה א\"ל ואתה הרם את מטך, ונודע כי א\"א להגביה את המטה אם לא ע\"י הרמת היד, ושרש ענין הרמת היד, הנה הידים הם בחי' מדות עליונות, ואם כי לידת המדות הוא מהבינה, אמנם שרש שרשם הוא מבחי' גבוה יותר שזהו שאמרו ז\"א בעתיקא אחיד ותליא<sup data-n=\"1203\">30</sup> וכענין שנת' במ\"א בענין ההפרש בין כבש לכשב<sup data-n=\"1204\">31</sup> שכבש הוא כמו שהוא בסדרי השתלשלו' כ\"ף רומז לבחי' כתר, בית חכ' או חו\"ב, שי\"ן חג\"ת, אבל כשב השי\"ן קודם לבי\"ת היינו כמו שרש המדות שקודמים לחו\"ב, ועד\"ז ציוה לו בכאן הרם את מטך, פי' מטך הוא ל' ממשלה<sup data-n=\"e62\">ה</sup> וציוה שיגביה בחי' הממשלה לשלוט על הים, ונטה את ידך הוא ג\"כ כענין גודל מלשון יד ושם, על הים ובקעהו, ועי\"ז ויולך ה' ברוח קדים עזה כל הלילה וישם את הים לחרבה. ויבקעו המים, פי' הת\"י לי\"ב גזרים, והיינו בכדי שכל שבט יעלה במסילה בפ\"ע, והיינו בהיות נודע כי י\"ב שבטים הם כנגד י\"ב בקר דבריאה והים מכסה עליהם מלמעלה, אמנם שורש ענין קרי\"ס שיבאו בנ\"י בתוך הים בחי' עלמא דאתכסיא ביבשה, ויתגלה בחי' האצי' איך שיהי' אם כפי' הזהר או כפי' האריז\"ל יהי' איך שיהי' הרי נתחבר האצי' עם הבריאה, ולהיות נודע כי גם באצי' יש י\"ב גבולי אלכסונין דז\"א, וז\"ע ששם עלו שבטים שבטי י\"ה, שעלו מבחי' י\"ב בקר דבריאה להיות בבחי' שבטי י\"ה הוא בחי' י\"ב גבולי אלכסוני' דז\"א דאצי', ובכדי שכל שבט יעלה במסילתו הראוי' לו בפ\"ע לזה נקרע הים לי\"ב קרעים, וזהו ויבקעו המים. ונמצא כי שניהם אמת שנקרע הים תחלה מחמת בחי' הרוח קדים מבחי' קדמונו של עולם ונעשה הים חרבה, ואח\"כ אמר ויבקעו המים היינו שמספר לנו שנבקע הים לי\"ב גזרים בכדי שכל שבט יעלה במסילה בפ\"ע כו'.",[["1203","30","<b>המדות. . שורש שרשם. . גבוה יותר. . ז\"א בעתיקא אחיד ותליא</b>: ראה תו\"א יתרו עב, סע\"ב-ג. עג, א. לקו\"ת שמיני יט, ב. במדבר יט, ב. חוקת נח, ב. מאמרי אדה\"ז תקס\"ז ע' שסד. תקס\"ח ח\"א ע' א. וע' ד ואילך. ענינים ע' תיח ואילך. ועוד."],["1204","31","<b>שנת' במ\"א בענין ההפרש בין כבש לכשב</b>: לקו\"ת אמור לז, ב. לח, סע\"ד ואילך.\n\n<b>ה</b>  <b>פי' איש ל' ממשלה</b>: בשולי הגליון נרשם בגוכי\"ק: צ\"ע ממ\"ש להיות כל איש שורר."]]],[2000510373,"<h3>[ואתה הרם את מטך]</h3>\n<b></b><b>[ד\"ה ואתה הרם את מטך]\nבס\"ד. פ' תזומ\"צ.</b>\nועדיין כו' ואתה הרם את מטך\nתזו\"מ\n<b></b>[כג)] ועדיין צ\"ל בענין ואתה הרם את מטך<sup data-n=\"1205\">1</sup>, כי הנה יש ג' מטות<sup data-n=\"1206\">2</sup>, מטה דיעקב שנא' ויקח לו יעקב מקל לבנה וגו', ומטה משה, ומטה דלע\"ל, וצ\"ל מהו ההפרש ביניהם. וגם צ\"ל הלא איתא במד\"ר שקרי\"ס הי' בזכות יעקב, ע' מד\"ר וישלח פע\"ו, ר' יהודה ב\"ר סימון בשם ר' יוחנן בתורה ובנביאים ובכתובים מצינו שלא עברו ישראל את הירדן אלא בזכות יעקב, בתורה כי במקלי עברתי את הירדן, בנביאים והודעתם את בניכם לאמר ביבשה עבר ישראל את הירדן, ישראל סבא, בכתובים מה לך הים כי תנוס הירדן וגו' מלפני אלקה יעקב, והלא נת' לעיל שקרי\"ס הי' מלפני משה, ומשה מלגאו ויעקב מלבר, ואיך א' שקרי\"ס הי' בזכות יעקב. גם צ\"ל בענין המטה משה שנמצא בו חילוקים בדרז\"ל, דהנה בי\"ח משה<sup data-n=\"1207\">3</sup> סי' ע\"ג הביא, והוא מרע\"מ פ' משפטים דקט\"ו א', שהמטה הי' מעה\"ד טו\"ר<sup data-n=\"1208\">4</sup>, ומצד הרע גרם שחטא בסלע, וכשחזר בתשובה נפק ממדריגה זו שהי' תחלה נער ועבד דכתי' והנה נער בוכה וכתי' עבדי משה, ונק' בן להקב\"ה ונמסר לו מטה אחר מעץ חיים והיינו וא\"ו, והוא כי שמע ישראל ובשכמל\"ו הם מ\"ט אותיות, ז\"ע מ\"ט בחי' צדיק מט לפני רשע<sup data-n=\"1209\">5</sup> ס\"מ, וע\"י היחוד דק\"ש בשית תיבין נעשה מוט בוא\"ו, ועי\"ז לא יתן לעולם מוט לצדיק כו', ומה שהי' תחלה מט לפני כו' זהו לפי שרק מ\"ט שע\"ב נמסרו למשה, ואם הי' נמסר לו שער החמשים לא הי' בא לזה, ולא הי' חוטא בסלע. ובערך יעקב סי' קפ\"ד הביא והוא מהילקוט פ' חוקת רמז תשס\"ג דרל\"ח ד' ודרל\"ט א', שמביא בשם מדרש ילמדנו ע\"פ מטה עוזך ישלח ה' מציון מטה שהי' ביד יעקב שנא' כי במקלי עברתי וגו', הוא הי' ביד יהודה שנא' ומטך אשר בידך וגו', והוא הי' מטה משה, והוא הי' ביד אהרן דכתי' וישלך אהרן את מטהו, והוא הי' ביד דוד דכתי'",[["1205","1","<b>ועדיין צ\"ל. . ואתה הרם את מטך</b>: מאמר זה הוא מאמר הרביעי שבהמשך והחרים תרל\"א\". ונמצא בשינויים בהמשך וככה תרל\"ז פרקים קטז-קיט (ע' קפא ואילך). והוא מיוסד על ד\"ה כי במקלי עברתי את הירדן בגוכי\"ק 1077 קלו, א [הכולל הנחות בגוכי\"ק אדמו\"ר מהר\"ש ממאמרי הצ\"צ]. ובשינויים בסה\"מ תרל\"ג ח\"א ע' רלב ואילך.\nלכללות המאמר ראה ד\"ה אשירה לה' בתו\"א בשלח סב, סע\"ד ואילך. ד\"ה כי במקלי באוה\"ת וישלח רלב, סע\"ב. אוה\"ת וארא ע' רלד ואילך.\nחלק מהמאמר (פרקים כד-כו) הוא תוכן ד\"ה מי כמוכה הידוע מכ\"ק אדמו\"ר מהר\"ש בסה\"מ תרכ\"ט ע' קנה ואילך. וש\"נ. סה\"מ תרל\"ב ח\"א ע' שלג. וש\"נ. להתחלת וסיום המאמר ראה ד\"ה ואתה הרם את מטך באוה\"ת בשלח ע' תטו ואילך.\nעניני המאמר נמצאים בשינויים והוספות בד\"ה ויולך ה' את הים בסה\"מ עטר\"ת ע' שע ואילך. ד\"ה ויולך בסה\"מ תרפ\"א ע' רלה ואילך. ד\"ה בסוכות תשבו תרפ\"ט ע' 37 ואילך. שם ע' 47 ואילך. ד\"ה טוב לי תורת פיך בסה\"מ תרצ\"ז ע' 190 ואילך. ד\"ה בסוכות תשבו וד\"ה בראשית ברא בסה\"מ תש\"ו ע' 31 ואילך וס\"ע 47 ואילך. וראה גם ד\"ה ואני תפלתי בסה\"מ תש\"ג ע' 109 ואילך."],["1206","2","<b>יש ג' מטות</b>: ראה גם אוה\"ת חוקת ע' תתנט. סה\"מ תרכ\"ו ס\"ע קנד-ה. קפו."],["1207","3","<b>בי\"ח משה</b>: בס' ילקוט חדש ערך משה."],["1208","4","<b>שהמטה הי' מעה\"ד טו\"ר</b>: ראה בכ\"ז אוה\"ת וארא ע' רלב. מטות ס\"ע א'רצה. ועוד."],["1209","5","<b>בחי' צדיק מט לפני רשע</b>: ל' הכתוב (משלי כה, כו), וראה פירש\"י ומצו\"ד עה\"פ."]]],[2000510374,"ויקח מקלו בידו, והוא הי' ביד כל מלך ומלך עד שחרב בהמ\"ק, וכן עתיד אותו המטה לימסר ביד מלך המשיח. ולהבין כ\"ז צ\"ל למה היו צריכין את המטה לאותות ומופתים שנעשו במצרים בפרעה ובכל עבדיו, כמ\"ש ואת המטה הזה תקח בידיך אשר תעשה בו את האותות, וגם בקרי\"ס נא' ואתה הרם את מטך, מה\"ע המטה שהי' צריך לעשיית האותות והמופתים וקרי\"ס, ומדוע בהכאת הנהר דלע\"ל לא נא' מטה כלל, כמ\"ש והניף ידו על הנהר, ואם כי גם בקרי\"ס נא' ונטה את ידך וכתי' ויט משה את ידו על הים, מ\"מ נא' לו תחלה ואתה הרם את מטך.\n<b>אך</b> הענין יובן ע\"פ המד\"ר וארא פ\"ט ע\"פ ואמרת אל אהרן קח את מטך הה\"ד מטה עוזך ישלח ה' מציון, אין הקב\"ה רודה את הרשעים אלא במטה, ולמה לפי שנמשלו לכלבים שנא' ישובו לערב יהמו ככלב, וכתי' והכלבים עזי נפש (ישעי' סי' נ\"ו י\"א), כשם שדרכו של כלב לרדות במקל כך הם לוקי' במקל, לכך נא' מטה עוזך וגו'.\n<b></b>[כד)] והענין יובן בהקדם מה שבקרי\"ס נאמר אשירה להוי'. והענין הוא דהנה אנו רואים בנבראים שכל מה שנברא הרי כל א' הוא רק משל לחבירו<sup data-n=\"1210\">6</sup>, וכמו הארי' שלמטה אם כי הוא חי' טמאה וטורף ודורס, מ\"מ הרי הוא משל לגבי הארי' שלמעלה, שהרי עכ\"פ אותיות ארי' מחיים אותו, והגם שזהו בדרך נפילה ושבירה<sup data-n=\"1211\">7</sup> מ\"מ יהי' איך שיהי' הרי אותיות אלו דארי' הם מחיים אותו, וכן יש בחי' ארי' הגבוה מארי' דמרכבה בחי' פני ארי' אל הימין שהוא במרכבה דבריא', ויש דוגמתו באצי' והיינו בחי' חסד דאצי' שאברהם איש החסד הי' מרכבה לבחי' חסד זה ה\"ה ג\"כ בחי' ארי' אל הימין, רק שזהו מבחי' מרכבתא עילאה שהאבות הן הן המרכבה<sup data-n=\"1212\">8</sup>, אשר בחי' הארי' שבמרכבה דבריאה הוא רק משל לבחי' ארי' זה דאצי', ומ\"מ הרי שרש התהוות הארי' שבמרכבה נלקח מבחי' ארי' זה דאצי', שהרי בנין המל' דאצי' הוא מבחי' המל' דע\"ס, ולכן מבחי' המל' דחסד דאצי' שהחסד הוא בחי' ארי' דאצי', הנה מבחי' המל' של החסד הזה נעשה במל' דאצי' חסד שבמל', ובחי' המל' הוא מהוה כל הנבראים דבי\"ע, נמצא כי חסד בחי' ארי' דאצי' הוא מקור למקור לבחי' הארי' שבמרכבה דבריאה, רק שזהו בדרך בריאה יש מאין כמו שנת' ענין זה באריכות בד\"ה מי כמוכה באלים ה'<sup data-n=\"1213\">9</sup>.",[["1210","6","<b>והענין יובן. . אנו רואים בנבראים. . כל א' הוא רק משל לחבירו</b>: בהבא לקמן (עד פיסקא: ומעתה צ\"ל ענין אשירה) ראה אוה\"ת וארא ע' ריז. משפטים (כרך ח) ע' ג'מ. סה\"מ תרכ\"ז ע' צח. תרכ\"ח ע' קמז ואילך. תרכ\"ט ע' צד ואילך. קנז ואילך. תרל\"ב ח\"א ע' ערב ואילך. לעיל ד\"ה זאת חוקת."],["1211","7","<b>הארי' שלמטה. . לגבי הארי' שלמעלה. . בדרך נפילה ושבירה</b>: ראה תו\"א וישלח כה, ג. מאמרי אדה\"ז תקס\"ה ח\"א ע' סא ואילך. ביאוה\"ז לאדהאמ\"צ נ, ד. ובארוכה אוה\"ת וארא ע' קסד."],["1212","8","<b>במרכבה דבריאה. . באצי'. . מרכבתא עילאה שהאבות הן הן המרכבה</b>: ראה תו\"א יתרו עא, סע\"א ואילך. עב, ב ואילך. עב, ד. ואילך."],["1213","9","<b>בד\"ה מי כמוכה באלים ה'</b>: סה\"מ תרכ\"ט שם ע' קס."]]],[2000510375,"<b>וכן</b> עד\"ז יש עד רום המעלות וכמו שחכ' דאצי' נק' ג\"כ בשם ארי', כמ\"ש וירא ראשית לו, ראשית הוא בחי' חכ', כמ\"ש ראשית חכ', וירא אותיות ארי', והיינו ראי' אותיות ארי'<sup data-n=\"1214\">10</sup>, וכמו\"כ ענין וירא, אשר בחי' ארי' דחסד הוא רק משל לבחי' ארי' דחכ', וכנודע ממ\"ש במ\"א בהפרש שבין המוחין למדות כו', שלכן אלפים שנה קדמה תורה לעולם<sup data-n=\"1215\">11</sup>, פי' קדמה אינה בזמן שהרי זה הי' קודם שנברא העולם בחי' מקום לא הי' הזמן ג\"כ<sup data-n=\"1216\">12</sup>, שהרי זמן ומקום שניהם מחודשי' ובריאתן שוה כא'<sup data-n=\"1217\">13</sup>, אלא ענין אלפים שנה הכוונה הוא על בחי' אאלפך חכ' אאלפך בינה, ונק' אלפי' שנה ע\"ש הזמן הנברא אח\"כ הוא אלפים, כי מספר האלפים בחכ', שיחידות במל' ועשירות בז\"א ומאות בבינה ואלפים בחכ' (ומ\"ש גם נגד הבינה אלף שנה, היינו בחי' וחכם בבינה שזהו ג\"כ חכ' כמ\"ש ביאור ד\"ז במ\"א<sup data-n=\"1218\">14</sup>). ונמצא כי פי' קדמה הוא במעלה ומדריגה, שבחי' המוחין הם במעלה ומדרגה גבוה ביתר שאת ויתר עז על בחי' המדות, ולהיות כי הם משונים במעלתם ה\"ה משונים ג\"כ בפעולתם, שהרי טבע המדות שיומשך השפעה לזולתו ובלא השפעה לזולתו מתבטל המדה לגמרי, משא\"כ המוחין הם הפכי' לגמרי וכנודע ממארז\"ל במשנה פ\"ד דסנהדרין שהיו מזדווגי' זוגות זוגות והיו נושאין ונותנים כל הלילה, ופי' המפרשים בינן לבין עצמן, ולא כולם יחד, והיינו כי בכדי שיונח אצלו הנחת השכל שהוא כך ולא כך זהו דוקא כשהוא נושא ונותן בינו לבין עצמו ושופט בשכלו משפט דבר ההוא, ונמצא כי המוחין ומדות הם הפכי' בטבעם ובפעולתם. ולכן הארי' דמדות לגבי הארי' דחכ' ה\"ה רק כמשל זל\"ז, ומ\"מ מבחי' החכ' נתהוו המדות, כמו בגשמיות הנה הולד נוצר מטיפת מוח האב, כן או\"א מולידי' זו\"נ כו', ונמצא כי הארי' דחכ' הוא מקור לבחי' הארי' דחסד כו'. ועד\"ז יובן עוד למעלה יותר והוא כי הכתר נק' ג\"כ ארי' כמ\"ש ארי' שאג מי לא יירא ה' אלקי' דיבר וגו', ואיתא שזהו דבור אנכי<sup data-n=\"1219\">15</sup>, נמצא שגם הכתר נמשל לארי', והיינו כי ארי' גימ' רי\"ו שהוא גימ' גבורה, והוא בחי' גבו' דע\"י שמלובש במו\"ס כו', ונמצא כי פרט התהוות הארי' יש עד רום המעלות.",[["1214","10","<b>ראי' אותיות ארי'</b>: ראה תו\"א ויחי מה, א. יתרו עא, ד. ובכ\"מ."],["1215","11","<b>וכנודע ממ\"ש במ\"א בהפרש שבין המוחין למדות. . אלפים שנה קדמה תורה לעולם</b>: ראה לקו\"ת מסעי צג, רע\"א. סה\"מ תרכ\"ח ע' ד ואילך. תרכ\"ט ע' ט. תרל\"ג ח\"ב ע' תקמ-מא. תרל\"ד ע' נד ואילך. עזר\"ת ס\"ע קסח ואילך. תש\"ח ע' 272 ואילך. ובכ\"מ."],["1216","12","<b>קודם שנברא העולם. . לא הי' הזמן ג\"כ</b>: ראה סידור עם דא\"ח עה, סע\"ד ואילך. לקו\"ת בלק ע, ג. דרושים לר\"ה סא, א. אמ\"ב שער הק\"ש פל\"ז ואילך. דרמ\"צ נז, א ואילך. המשך תרס\"ו ע' מא ואילך. וראה אג\"ק כ\"ק אדמו\"ר זי\"ע ח\"א ס\"ע רצג ואילך. ח\"ב ע' רכד."],["1217","13","<b>זמן ומקום שניהם מחודשי' ובריאתן שוה כא'</b>: ראה לקו\"ת ברכה צח, א."],["1218","14","<b>וחכם בבינה שזהו ג\"כ חכ' כמ\"ש ביאור ד\"ז במ\"א</b>: ראה ביאוה\"ז לאדהאמ\"צ לט, ב ואילך. שער היחוד לאדהאמ\"צ ב, ב. אמרי בינה שער הק\"ש פנ\"ט (נו, א ואילך). מאמרי אדהאמ\"צ במדבר ח\"ה ע' א'תשנ. אוה\"ת ויקרא (כרך ג) ע' תשפח ואילך. שה\"ש (כרך א) ע' רכ ואילך. סה\"מ תרמ\"ו ע' כב. תרנ\"ט ס\"ע עג ואילך. וש\"נ. תרע\"ח ע' יד."],["1219","15","<b>ארי' שאג. . ואיתא שזהו דבור אנכי</b>: ראה שמו\"ר פכ\"ט, ט: אנכי ה\"א הה\"ד ארי' שאג מי לא יירא. הובא ונת' באוה\"ת דרושים לחה\"ש ע' רכא. דרושים לר\"ה ע' א'תכח. נ\"ך ע' תמז. וראה גם אוה\"ת יתרו ע' תתקלא."]]],[2000510376,"<b></b>[כה)] ועד\"ז בכל פרטי הנבראי', עד\"מ שמים וארץ שלמטה, ועד\"ז יש למעלה שהם בחי' זו\"נ שבכל עולם, שזו\"נ דעשי' הם מקור לבחי' השמים והארץ הגשמי', והמקור למקור הוא בחי' חו\"ב דעשי' שהם ג\"כ שמים וארץ כמ\"ש במ\"א<sup data-n=\"1220\">16</sup>, וזו\"נ דיצי' הם מקור לחו\"ב דעשי', וחו\"ב דיצי' מקור למקור, ועד\"ז בבריאה זו\"נ דבריאה הם מקור לחו\"ב דיצי', וחו\"ב דבריאה מקור למקור כו', וכמו\"כ באצי' זו\"נ דאצי' הם מקורי' לחו\"ב דבריאה רק שזהו ע\"י בחי' התהוות יש מאין דמל' דאצי' כמשנ\"ל, ומ\"מ התהוות המל' הוא ממל' דע\"ס, וחו\"ב דאצי' הם שמים וארץ עילאין, וכנודע מענין ההפרש בין משה לישעי' שמשה אמר האזינו השמים ותשמע הארץ, וישעי' אמר שמעו שמים והאזיני ארץ, השמים דאינון ידיעין, שמים דלא ידיעין, והיינו בחי' זו\"נ שנק' שמים וארץ, וחו\"ב הם השמים והארץ, וגם בחי' כתר נק' שמים רק שהוא בחי' שמי השמים, ע' בד\"ה בעצם היום הזה הגהות על מאמר הנ\"ל שבת\"א<sup data-n=\"1221\">17</sup> יעו\"ש. ועד\"ז בכל הנבראים, וכמו יום ולילה הם ג\"כ בחי' זו\"נ שבכל סדרי ההשתל', והמקור הוא בחי' זו\"נ דאצי', והמקור למקור ז' ימי קדם, ושם באצי' בחי' יום ולילה הוא ברוחניות בדקות מאד, וגם בכל סדרי השתלשלו' דבי\"ע, וכנודע ממשה כשהי' בהר מאין ידע אם זהו יום או לילה, כשמלאכים אומרים קדוש ידע שזהו יום וכשאומרים ברוך ה\"ה לילה, שקדוש וברוך אינו בערך יום ולילה הגשמי' שלנו אלא שעכ\"פ ה\"ה מקור ליום ולילה שהרי משה ידע מזה, ועוד איתא שכשלמדו אותו תושב\"כ ידע שזהו יום ותושבע\"פ ידע שזהו לילה (כמ\"ש כ\"ז בילקוט ס\"פ תשא רמז ת\"ו), שאינו בערך כלל וכלל תושב\"כ ותושבע\"פ ליום ולילה הגשמי', ומ\"מ ידע מזה על יום ולילה הגשמי' כו'. ועד\"ז תמצא בכל פרט ופרט מהנבראי' שיש דוגמתם ברוחני' עד רום המעלות כו', אשר כל בחי' נגד זולתה היא רק משל לבד.\n<b></b>[כו)] והנה כל המשלי' האלה שרש שרשם הוא רק מבחי' שם אלקים, כי בכדי שיוכל להתהוות שבחי' א' יהי' משל לגבי זולתו זהו ע\"י בחי' המגן ונרתק דש' אלקי' (וגם בכתר יש בחי' שם אלקים וכנ\"ל בענין ה' אלקי' דיבר, שא' גם שם אלקי', וע' בסה\"מ<sup data-n=\"1222\">18</sup> שפי' בחי' ק\"ך צירופי אלקי' דיתבא על כורסי' דשבבין לאכפי' להון), ומאחר שכל המשלים האלו הוא מבחי' שם אלקי' ממילא כל התהוות הנבראי' הוא ע\"י שם אלקי' גם בנבראי' שנא' בהם ה' אלקי' שם מלא ג\"כ, פי' שנתהוה ע\"י שם אלקים, דבלא בחי' שם אלקי' לא הי' יכול להיות מציאות הגשמי כלל וכלל, ונמצא כמו בכל הנבראי' נא' בראשית ברא אלקי' כ\"ה בכל הנבראי' אפי' בג\"ע, שהרי הוא השגה בהגבלה לכאו\"א לפי ערכו ומעלתו כו', רק שבזה הוא יתרון הנבראי' שנא' בהם שם מלא כמו ויטע ה' אלקי' גן בעדן<sup data-n=\"1223\">19</sup> היינו ששם מאיר גילוי שם",[["1220","16","<b>חו\"ב דעשי' שהם ג\"כ שמים וארץ כמ\"ש במ\"א</b>: ראה גם מאמרי אדה\"ז תקס\"ג ח\"א ע' יג ואילך. אוה\"ת לך לך (כרך ד) תשכה, ב ואילך. סה\"מ תרכ\"ו ע' כו. תר\"ם ח\"ב ע' תריז. וש\"נ. לעיל ד\"ה גדולה מילה."],["1221","17","<b>בד\"ה בעצם היום הזה הגהות על מאמר הנ\"ל שבת\"א</b>: אוה\"ת לך לך (כרך ד) תשכה, א ואילך. וראה גם מאמרי אדה\"ז תקס\"ג ח\"א ע' יב ואילך."],["1222","18","<b>בסה\"מ</b>: בס' הדרת מלך."],["1223","19","<b>בג\"ע. . שם מלא כמו ויטע ה' אלקי' גן בעדן</b>: ראה בארוכה סה\"מ תרל\"ג ח\"א ע' קד [ובהנסמן שם בתחילת המאמר]."]]],[2000510377,"הוי' ע\"י המסך ונרתק דשם אלקי', משא\"כ בשאר הנבראי', אם כי מפלא הבריאה יכולים להבין גדלות הבורא, מ\"מ ה\"ז בדרך העלם והסתר להיות כי כח הפועל בנפעל הוא בדרך העלם והסתר הבורא הוא כח המהוה מן הדבר המתהוה הוא הנברא מאין ליש, דאל\"כ לא הי' אפשר כלל להיות מציאת נברא גשמי' כמ\"ש ביאור ד\"ז במ\"א, ע' בד\"ה מי כמוכה באלים, וד\"ה מהיכן זכו<sup data-n=\"1224\">20</sup> ישראל לק\"ש. אבל (כמו) הג\"ע שנא' בו שם מלא היינו ששם מאיר גילוי אלקות צדיקי' יושבין ונהנין מזיו השכינה, ה\"ז גילוי מתוך ההעלם, וה\"ז כמו שאומרים איזה דבר שכל גבוה מאד ע\"י איזהו משל, שהמכוון שע\"י המשל יבינו את הנמשל גם כמו קודם התלבשותו בנמשל כ\"ה גילוי שם הוי' ע\"י בחי' שם אלקי' כו'.\n<b></b>[כז)] ומעתה צ\"ל ענין אשירה להוי'<sup data-n=\"1225\">21</sup> שנא' בקרי\"ס, ויובן בהקדם ענין ירידת הנשמה בגוף, שלכאו' ה\"ז ירידה גדולה ועצומה מאד, שהרי הנשמה קודם התלבשותה בגוף היתה עומדת באהוי\"ר כמ\"ש חי ה' אשר עמדתי לפניו, ומובן אשר עמידתה לפני ה' לא הי' בלתי אהוי\"ר הראוי' לפי ערך ומקום עמידתה, ולמה ירדה פלאים להתלבש בגוף ונה\"ב גשמי מאד אשר צריכה ליגיעת נפש ויגיעת בשר בכדי לבוא לאיזה התפעלות אהוי\"ר, אשר אינה בערך האהוי\"ר שהיתה עומדת קודם התלבשותה בגוף, והלואי תהי' השבתה למעליותא.\n<b>אך</b> הענין הוא דכתי' נורא תהילות עושה פלא, ואנו אומרים אדון הנפלאות המחדש בטובו בכל יום תמיד מעשה בראשית, פי' המחדש שענין הבריאה היא אשר נתחדשה יש מאין ממש וא\"א לומר שהעולם וכל אשר בה הם הם אשר היו בהעלם תחלה ויצאו אח\"כ מהעלם אל הגילוי, וכמו שכל ומדות שהמדות היו תחלה בהעלם בשכל, שהרי גם בשכל יש מדות כנודע מענין מדות שבשכל, ונמצא כי יציאת המדה מהשכל איננה דבר חדש ממש, אבל הבריאה היא יש מאין ממש, וכנ\"ל עד\"מ מענין הארי' שיש דוגמתו עד רום המעלות, האם נאמר שהארי' שלמטה הוא הוא הי' כלול תחלה במקורו, אלא התהוותו הוא יש מאין ממש, רק ששרש שרשו הוא ג\"כ ארי', והיינו בחי' הגבורות ורשפי אש התשוקה שיש בבחי' פני ארי' שבמרכבה לאלקות שנושא את הכסא ומנושא מן הכסא עצמו, וכ\"ש בבחי' הארי' היותר גבוהים, וכנודע ההפרש בין אצי' לבריאה<sup data-n=\"1226\">22</sup> שאצי' הוא גילוי ההעלם מאלקות ובי\"ע הם יש מאין שנתהוו דבר מלא דבר, ומקור המהוה אותם הוא רק בחי' דמות, וזהו שנא' בבריאת",[["1224","20","<b>כמ\"ש ביאור ד\"ז במ\"א ע' בד\"ה מי כמוכה. . וד\"ה מהיכן זכו</b>: ד\"ה מי כמוכה בסה\"מ תרכ\"ט ע' קסא. וד\"ה מהיכן זכו בסה\"מ תרכ\"ז ע' שפז."],["1225","21","<b>ומעתה צ\"ל ענין אשירה להוי'</b>: הבא לקמן (עד פיסקא: ולהיות קרי\"ס הי' ע\"י מטה משה) מיוסד על ד\"ה אשירה להוי' בתו\"א בשלח שם סב, סע\"ד ואילך. (וביאור ע\"ז במאמרי אדה\"ז פרשיות ח\"ב ע' תתקיא ואילך). מאמרי אדהאמ\"צ שמות ח\"א ע' קח ואילך. וע' קכב ואילך. ובארוכה בתורת חיים שמות (כת\"י הר\"ש סופר) רל, ב ואילך [בהוצאת תשס\"ד הוא בח\"א קסד, ב ואילך]. והגהות ע\"ז באוה\"ת בשלח ע' תקט ואילך. וע' תקטו ואילך."],["1226","22","<b>וכנודע ההפרש בין אצי' לבריאה</b>: ראה בארוכה סה\"מ תרכ\"ח ע' קעג ואילך. תרל\"ג ח\"ב ע' תקב ואילך. וש\"נ."]]],[2000510378,"האדם בצלמנו כדמותנו, שיש בחי' צלם ודמות, הנה נודע כי הדמות אינו עצם הדבר כ\"א מה שנדמה שזה הוא, וכמו המביט בזכוכית הנק' מראה (שפיגעל בל\"א) הגם שרואה שם כל תבנית האדם בכל פרטיו ופרטי פרטיות מ\"מ ה\"ה רק דמות לבד<sup data-n=\"1227\">23</sup> ואינו עצם הדבר, ואיך נאמר שהנבראי' שלמטה שנבראו מבחי' מל' הנק' בעצמו רק בשם דמות הם ממש אותם הדברים שבאצי', שא\"א כלל וכלל לומר כן, אלא שנבראו יש מאין ממש.\n<b></b>[כח)] והנה מאחר שהם בחי' בריאה יש מאין הנה החיות המחי' אותם הוא ג\"כ מוסתר ונעלם, וכמו שאנו רואים חיות האדם שהנשמה מחי' את הגוף, הנה אנו רואים פעולתה שהאברים חיים וקיימים שהרי מנענע באבריו והולך ברגלו ומחשב במוחו ומדבר ועושה כל דבר, ורואה בעין ושומע באוזן, וכן בכל יתר כחותיו והרגשותיו עד שמזה נבין שיש נפש רוחני המחי' אותנו, דאל\"כ מאין ימצא בשכל שהוא גשמי והוה ונפסד ונרקב והי' לעפר להשכיל דבר רוחני כו', אלא שיש בו הארה רוחניות מכח נפשו הרוחניות אשר היא תבין ותשיג השגות רוחניות וגשמיות והשכלות כו'. אבל מהות הנפש אין אנו יודעים כלל וכלל מה היא שהרי אינו שייך כלל לאמר בעצם הנשמה שיש בה כחות פרטי'<sup data-n=\"1228\">24</sup> כמו ראי' ושמיעה מובדלים, והרי במ\"ת שעל כל דבור ודבור פרחה נשמתן ראו את הנשמע ושמעו את הנראה ה\"ז הוראה שבעצם הנפש בלתי מחולקי'<sup data-n=\"1229\">25</sup> הם, שהרי ראו את הנשמע נמצא שכח הראי' פעל את הפעולה של כח השמיעה, ושמיעת הנראה הרי כח השמיעה פעל פעולת כח הראי', אלא ששם בלתי מוגבלים הם עדיין כלל וכלל, ולכן היו יכולים לראות את הנשמע ולשמוע את הנראה מצד עצם נפשם הפשוט בתכלית, ועכ\"ז צריך לומר שגם בעצם הנפש יש מקור שאם יתפשטו בכחות הגוף יהי' זה ראי' וזה שמיעה, דאל\"כ האיך נאמר שראו את הנשמע ושמעו את הנראה מאין ידוע מהו כח הראי' ומהו כח השמיעה כו', אעכצ\"ל שהרגישו בעצם נפשם וראו את הקול ושמעו מה שדרך לראות, וגם אם לא יש מקור על כח הראי' בפ\"ע וכח השמיעה בפ\"ע מאין ידעו שהחליפו לראות את הנשמע ולשמוע את הנראה, הלא עכדו\"ד פרחה נשמתן ולא האירו בפרטי מקומות המיוחדים להם, אלא צריך לומר שגם שהנפש היא עצם פשוט מ\"מ יש בה כל הכחות שעתידים להתגלות בכח בהתכללו' יחד. אמנם מ\"מ כל ענין הנפש המחי' את הגוף הרי ידיעתינו שאנו יודעים את הנפש הוא רק בדרך ידיעת המציאות ולא השגת המהות כלל<sup data-n=\"1230\">26</sup>, שהרי אין אנו יודעים מהות",[["1227","23","<b>המביט בזכוכית הנק' מראה. . ה\"ה רק דמות לבד</b>: ראה גם תו\"א מקץ לג, א. סה\"מ תרל\"ב ח\"א ע' פא. צט. ובכ\"מ."],["1228","24","<b>אינו שייך כלל לאמר בעצם הנשמה שיש בה כוחות פרטי'</b>: ראה בארוכה תניא פנ\"א ובהמובא ע\"ז בס' ליקוט פירושים ומ\"מ לתניא (להר\"א שי' חיטריק) ע' א'פ ואילך."],["1229","25","<b>במ\"ת. . ראו את הנשמע ושמעו את הנראה. . שבעצם הנפש בלתי מחולקים</b>: בהבא לקמן ראה בארוכה סה\"מ תרכ\"ט ע' ריח ואילך. וש\"נ. לעיל ע' רסד. ועוד."],["1230","26","<b>ידיעתינו. . רק. . ידיעת המציאות ולא השגת המהות כלל</b>: ראה לקו\"ת ואתחנן ו, א ואילך. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשסז ואילך. ועוד."]]],[2000510379,"הנפש מה היא כלל, אלא שמחמת שאנו רואים שהגוף חי הרי אנו יודעי' שיש נפש המחי' את הגוף, אבל זהו רק בדרך ידיעת המציאות לבד ולא השגת המהות כלל.\n<b>ועד\"ז</b> יובן בכלליות העולם הנה מה שמחי' ומהוה את העולם אינו מושג לנו כלל, רק ממה שאנו רואים שהעולם חי, כי האדם הוא עולם קטן וכמ\"ש באדר\"נ שכל מה שיש בעולם יש באדם, ולכן כמו באדם אנו מכירים שיש בו נפש המחי' אותו, כן בעולם שהוא גוף גדול עכצ\"ל שיש בחי' חיות רוחני המחי' ומהוה את העולם, אמנם כמו הנפש המחי' את הגוף אין אנו יודעים מהו מהות הנשמה כ\"א בדרך ידיעת המציאות ולא השגת המהות כלל, כן בחיות המחי' את העולם אנו יודעים רק בבחי' ידיעת המציאות לבד ולא השגת המהות כלל. וגם המלאכים שעומדים ברום עולם ג\"כ אינם יודעים כלל בבחי' השגת המהות את חיותם וחיות כל העולמות כ\"א בדרך ידיעת המציאות, שלכן נאמר וצדקתך ירננו, הנה הרינה שלהם הוא רק בבחי' צדק מלכותא קדישא<sup data-n=\"1231\">27</sup> שהוא בחי' הארת מדת המל', וכמו מלך שרק שמו נק' עליהם אבל עצמותו אינו מתפשט כלל, כן בחי' מל' למעלה הוא בחי' שם לבד, וג\"ז יודעים רק בדרך ידיעת המציאות ולא השגת המהות כלל. וא\"כ הנשמה כמו שהיתה למעלה קודם התלבשותה בגוף שנא' בה חי ה' אשר עמדתי לפניו, ג\"כ האהוי\"ר שהי' לה אם כי נשמות גבוהי' ממלאכי' ששרשן הוא מפנימיות הכלים, מ\"מ מה שהשיגו זהו רק בדרך ידיעת המציאות ולא השגת המהות. אך ע\"י ירידת הנשמה בגוף הנה ע\"י העסק והעבודה בתומ\"צ הנה היא באה בג\"ע לבחי' השגת המהות, שהרי צדיקי' יושבים ונהנים שם מזיו השכינה, וז\"ע מה שבג\"ע נא' שם מלא ה' אלקי' היינו ששם מאיר שם הוי' ע\"י בחי' שם אלקי' כו'.\n<b></b>[כט)] אמנם בכדי שיהי' מ\"ת הוצרכו תחלה לילך בים ביבשה, היינו שישיגו גם בבחי' המל' הנק' בשם ים בחי' עלמא דאתכסיא, ואז יוכלו לקבל התורה, ולכן הי' הגילוי בקרי\"ס שגם שפחה ראתה על הים ואמרו זה אלי שהי' גילוי בבחי' זה כו'. וזהו שנא' בשירת הים אשירה להוי', להיות כי ע\"י עברם בים היא בחי' המל' כמו שהיא באצי' בחי' ים סוף סופא דכל דרגין דאצי', אז התחילו לומר שירה על בחי' ש' הוי' שראו כמ\"ש זה אלי ואמרו אשירה להוי' כו'. וזהו מ\"ש ושמרו דרך ה' לעשות צדקה ומשפט, פי' דרך הוי' שיהי' גילוי שם הוי', אמנם הנה בקרי\"ס שכ\"א אמר זה אלי צריך לומר פי' דרך הוי' היינו בחי' הדרך ומבוא<sup data-n=\"1232\">28</sup> להיות שם הוי', כענין מ\"ש חנון ורחום הוי' היינו מה שהוא ית' חנון ורחום בכדי להיות הוי'<sup data-n=\"1233\">29</sup> כי שם",[["1231","27","<b>המלאכים. . וצדקתך ירננו. . צדק מלכותא קדישא</b>: ראה בארוכה תו\"א מקץ לז, א ואילך."],["1232","28","<b>פי' דרך הוי' שיהי' גילוי. . בקרי\"ס. . צריך לומר פי' דרך. . הדרך ומבוא</b>: ראה ד\"ה כי במקלי בכת\"י 1077 שם ובסה\"מ תרל\"ג שם ע' רלד: וזהו מ\"ש ושמרו דרך הוי', פי' דרך הוי' יש בו ב' פירושים, הא' שיהי' גילוי שם הוי' למטה, גם פי' דרך הוי' שהוא דרך והמשכה להיות הוי'."],["1233","29","<b>מ\"ש חנון ורחום הוי'. . חנון ורחום בכדי להיות הוי'</b>: ראה לקו\"ת ואתחנן ג, א. דרושים לשבת שובה סה, ב. מאמרי אדה\"ז תקס\"ד ע' רב. מאמרי אדהאמ\"צ נ\"ך ע' תקפא. אוה\"ת ויגש (כרך ה) תתקפד, ב. תשא ע' ב'מו. ואתחנן ע' נד. וע' ס. רשימות הצ\"צ לתהלים יהל אור ע' תרעז. סה\"מ תרל\"ג ח\"ב ע' תכו."]]],[2000510380,"הוי' הוא ג\"כ יו\"ד צמצום כו', וע\"י הצדקה שעושים למטה והמשפט ששופט בנפשו שדי לו בכך ולא ימשיך לבו אחר תאוות היתר עי\"ז ממשיך מלמעלה להיות חנון ורחום ה'. ובקרי\"ס שהי' גילוי בחי' זה לכן נא' אשירה, הנה ענין השירה הוא השמחה, כי מרה שחורה ועצבות הוא קמיטות וכוויצות החיות, והשמחה הוא מצד ההיפך, וזהו אשירה להוי' מחמת כי גאה גאה למעלה מהשתלשלו', כי גאה הוא היותו נפלא היינו בחי' פלא, וגאה גאה היינו בחי' אדון הנפלאות כו', ומבחי' זו הי' קרי\"ס היפך סדרי ההשתל' להיות מים יבשה כו' היפך כל סדרי ההשתלשלו'.\n<b>ולהיות</b> קרי\"ס הי' ע\"י מטה משה שהי' בחי' מקל דיעקב, כי הנה במקל דיעקב נא' ויקח לו יעקב מקל לבנה<sup data-n=\"1234\">30</sup> לח ולוז וערמון וגו', לבנה הוא בחי' חסד, לח הוא בחי' התפשטו' החסדים, לוז וערמון מראיהן אדום הוא בחי' גבורות והתגברות מבחי' הגבורות, והמקל כוללם יחד ומחבר אותם ה\"ז בחי' הת\"ת מדתו של יעקב, פצלות לבנות מחשוף הלבן ז\"ע מה שמטה כלפי חסד כו', וע\"י בחי' מקל זה שהוא בחי' הת\"ת שעולה עד הכתר עי\"ז נמשך בחי' הרוח קדים מבחי' קדמונו ש\"ע להיות בחי' הפך ים ליבשה.\n<b>אך</b> ע\"י מה זכה יעקב לבחי' מקל זה, הנה באמת יוכל כל אדם לבוא לבחי' זו, דהנה בכאו\"א מישראל יש ב' נפשות נה\"א ונה\"ב, והן שרש ב' יצרין יצ\"ט ויצה\"ר, וע\"י שמסגף את היצה\"ר שגם היצה\"ר יסכים לבחי' הביטול דנה\"א בהתבוננו' דק\"ש שז\"ע ואהבת וגו' בכל לבבך וארז\"ל בשני יצריך, שגם היצה\"ר ישוב לאהבת ה', הנה עי\"ז שמחבר היצ\"ט עם היצה\"ר ששרשם מחו\"ג<sup data-n=\"1235\">31</sup> עי\"ז הוא עולה למעלה מעלה, וכענין הת\"ת שהוא מחבר חו\"ג הנה הוא בחי' בריח התיכון המבריח מן הקצה אל הקצה, ועולה לבחי' קצה העליון שבכתר כו', כן ע\"י כבישת ונציחת היצה\"ר דבחי' גבורה ויגביר היצה\"ט שמבחי' החסדים על בחי' הרע דיצה\"ר ומסגף אותו עד שגם הוא יהי' בבחי' הביטול הנה הוא במדריגת בריח התיכון כו'. וגם ע\"י דאתכפי' סט\"א אסתלק יקרא דקוב\"ה בכולהו עלמין, ועי\"ז נמשך גילוי אלקות להיות זה אלי כמו בעבור ישראל בים כו'. וז\"ע מטה משה שהי' כלול מטו\"ר, ולכן ע\"י בחי' הרע שהי' נמצא בו מחלק הס\"מ, עי\"ז נכשל משה בציווי ודברתם אל הסלע, וזהו בחי' מ\"ט שבמטה והי' יכול להיות צדיק מט לפני רשע, אך ע\"י בחי' שית תיבין דיחודא דק\"ש דשמע ובשכמל\"ו ביטול דמ\"ה וב\"ן, עי\"ז נמשך להיות ואהבת וגו' בכל לבבך בשני יצריך חיבור חו\"ג עי\"ז נמשך וא\"ו במ\"ט ואז נעשה מוט הוא בחי' לא יתן לעולם מוט לצדיק כו'.",[["1234","30","<b>במקל דיעקב נא' ויקח לו יעקב מקל לבנה</b>: בהבא לקמן (עד סוף הפיסקא) ראה בארוכה אוה\"ת ויצא רכב, ב. סה\"מ תרל\"ב ח\"א ע' ט ואילך. קפח ואילך."],["1235","31","<b>היצ\"ט עם היצה\"ר ששרשם מחו\"ג</b>: ראה בארוכה אוה\"ת בראשית (כרך ג) תקפ, ב ואילך. וראה גם שם תקכב, ב. תקכה, א. סה\"מ תרל\"ג ח\"ב ע' תלט."]]],[2000510381,"[ל)] <b>ועפי\"ז</b> יובן מאמר המד\"ר הנ\"ל שאין הקב\"ה רודה את הרשעים אלא במקל כו', ומה דרכו של כלב לרדות במקל כך הרשעים שנמשלו לכלבים שנא' ישובו לערב יהמו ככלב, והכלבים עזי נפש, אין הקב\"ה רודה אותם אלא במקל. והענין הוא דהנה כלב הוא בגימ' ב\"ן והיינו הנה\"ב שנק' ב\"ן, והנה בעבודה שבלב הנה אם מברר את הנה\"ב ומעלהו ע\"י שזובח את יצרו ה\"ז בהמה בגימט' ב\"ן שעולה לקרבן ריח ניחוח. אמנם אם הוא נתפתה ליצרו הרע ועשה והנהיג א\"ע ע\"י היצה\"ר שבו בעשותו דברים אשר לא טובים והלך בעצת יצרו הרע, ה\"ה ככלב שהוא ג\"כ בגימט' ב\"ן, והיינו ששם ב\"ן להיותו נפל בשבירה יכול לימשך ח\"ו בקלי' וסט\"א ואז ה\"ה נק' רשע, וכשם שהכלב דרכו לרדותו במקל ומטה, כך הרשעים שהולכים בעצת יצרם הרע צריך לרדותן במקל, והיינו כי בדברים לא יוסר עבד כ\"א צריך להכותו במטה. וענין בחי' זו בעבודה הוא משארז\"ל לעולם ירגיז אדם<sup data-n=\"1236\">32</sup> יצ\"ט על יצה\"ר, שענין ההרגזה הוא בדברים קשים כהכאת המטה והמקל וכמארז\"ל יזכיר לו יום המיתה, ומצינו שדברים קשים הם כהכאה שהרי כתי' ויך את המצרי<sup data-n=\"1237\">33</sup> וארז\"ל שהרגו בשם, הרי בבחי' הדיבור קשה שהוציא עליו הרגו בזה כמו בהכאת המטה ויותר, ועד\"ז יובן שענין דברים קשים שירגיז על היצה\"ר ה\"ז נחשב כהכאה ממש, ובזה יוסר העבד ג\"כ. ולכן ביצ\"מ וקרי\"ס שהי' צריך להכניע קלי' פרעה היו צריכים למטה דוקא, ונמצא כי לא לענין עשיית האותות ומופתים או קריעת הים הוצרך למטה, אלא שזה הי' יכול לעשות גם בלי המטה, אלא מפני שעי\"ז נמשך דין קשה על המצרים, לזאת הי' צריך למטה וכמאמר המד\"ר הנ\"ל. ולכן לע\"ל שלא יהיו צריכים לרדות את הרשעים שהרי יפילם במלחמת גוג לא נאמר בהנפת הנהר רק והניף ידו כו', אבל א\"צ למטה, כי לע\"ל יהי' העלי' מבחי' ההשגה לבא לגילויי' מה שעכשיו הם למעלה מהשגה, ולזה יניף ידו על הנהר שהוא בחי' השגה כו' לבקוע מסך זה דהשגה כו', אבל למטה א\"צ לזה כמו שלבקיעת הים בעצם לא היו צריכים את המטה, אם לא מה שכל חיל פרעה נטבעו בים שזה לרדות את הרשעים כו' וכנ\"ל. ומ\"מ נא' לע\"ל ג\"כ מטה עוזך, שענין מטה זה הוא בחי' ממשלה, וכמו במשה קודם הסתלקותו שהשיג שער החמשים נא' בו וזאת הברכה וגו' איש האלקים, פי' איש ל' ממשלה כמו ואל אישך תשוקתך והוא ימשול בך שאיש לשון ממשלה, ונמצא פי' איש האלקי' שנעשה מושל ושולט על בחי' שם אלקי', שהרי בשליחותו לפרעה נא' בו ראה נתתיך אלקי' לפרעה, היינו כמ\"ש ואם זרוע כאל לך עדה נא כל גאון וגובה, בחי' הפלת הרשעים וכמ\"ש באריכות בד\"ה ראה נתתיך<sup data-n=\"1238\">34</sup> כו' ואז הי' צריך למטה, אבל אח\"כ הי' איש האלקי' מושל כו', אז המטה שלו הי' כדוגמת מטה דלע\"ל",[["1236","32","<b>בחי' זו בעבודה. . לעולם ירגיז אדם</b>: ראה תניא פכ\"ט (לז, א). פל\"א (לט, ב). תו\"א וישב ל, ד. לקו\"ת שלח מא, א. אוה\"ת וארא ע' רלה."],["1237","33","<b>שדברים קשים הם כהכאה. . ויך את המצרי</b>: ראה גם אוה\"ת חוקת ע' תתל."],["1238","34","<b>וכמ\"ש באריכות בד\"ה ראה נתתיך</b>: תרל\"א (לעיל ס\"ע קלט ואילך. וש\"נ)."]]],[2000510382,"שיהי' בחי' ממשלה, וזהו כמ\"ש הילקוט כו' וגם הרע\"מ שנתנו לו מטה אחר, וי\"ל גם להרע\"מ שזהו מטה דלע\"ל.\n<b>ובכ\"ז</b> יובן ג\"כ ענין מה שקרי\"ס הי' בזכות יעקב, והיינו כי הגם שקרי\"ס נמשך מבחי' הגבוה יותר ממדריגתו של יעקב, והיינו מלפני משה הוא בחי' הרוח קדים שנת\"ל בארוכה, ויעקב הוא מלבר כו', מ\"מ זכות יעקב הגיע לשם, שענין הזכות מגיע לבחי' גבוה יותר ממה שהוא בעצם, וכן ענין הבריח התיכון ה\"ה מבריח מן הקצה העליון שגבוה ממנו, וכמו ת\"ת שעולה עד הכתר, ולכן שניהם אמת, שקרי\"ס הוא שבוקע ים לפני משה עדיין ומשה מלגאו, ומ\"מ הי' זה ע\"י בחי' זכותו של יעקב, וכמ\"ש מה לך הים כי תנוס וגו' מלפני אלקה יעקב הוא בחי' הזכות שלו שמבריח מן הקצה אל הקצה מבחי' קצה העליון כו'.",[]],[2000510383,"<h3>[מטה עוזך]</h3>\n<b></b><b>[ד\"ה מטה עוזך ישלח ה' מציון] </b>\nואמנם כו' מטה עוזך ישלח\nאחו\"ק\nבס\"ד. פ' אחו\"ק.\n<b></b>[לא)] ואמנם עדיין צ\"ל מ\"ש מטה עוזך ישלח ה'<sup data-n=\"1239\">1</sup> מציון וגו', שזה קאי על מטה דלע\"ל שלא יצטרך למטה בשביל לרדות בהם את הרשעים, כי כהמס דונג מפני אש יאבדו רשעים מפני אלקים וכנ\"ל שזהו ההפרש בין המטה דקרי\"ס",[["1239","1","<b>ואומנם. . מטה עוזך ישלח ה'</b>: מאמר זה הוא מאמר החמישי שבהמשך והחרים תרל\"א\". ונמצא בשינויים בהמשך וככה תרל\"ז פרקים קכ-קכד (ע' קצ ואילך).\nמאמר זה (מלבד ההתחלה וסיום) מיוסד על ד\"ה תפול עליהם בתורת חיים שמות (כת\"י הר\"ש סופר) רסד, א. רסו, א ואילך. [ובהוצאת תשס\"ד הוא בח\"א קפה, ב. קפו, ד ואילך]. ובשינויים בס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' רג. וע' רה ואילך.\nחלק מהמאמר בתוס' ביאור ראה: ד\"ה נר חנוכה בסה\"מ תרמ\"ד ע' רב ואילך. ד\"ה בכ\"ה בכסלו בסה\"מ תרנ\"ג ע' קסו ואילך. ד\"ה ביום השמע\"צ בסה\"מ תרנ\"ט ע' מה ואילך. ובארוכה ד\"ה זה היום וד\"ה אני לדודי בסה\"מ תרס\"ט ע' ז ואילך. וע' ט ואילך. המשך תער\"ב ח\"ב ע' א'קמא ואילך [ד\"ה זה היום]. א'קמז ואילך [ד\"ה בחדש השביעי]. א'קנח ואילך [ד\"ה אנכי אנכי]. ד\"ה ויאמר גו' אל תיראו בסה\"מ עטר\"ת ע' תנה ואילך. ד\"ה ויאמר גו' מה תצעק בסה\"מ תרפ\"ה ע' קנו ואילך. ד\"ה ביום השמע\"צ בסה\"מ תרפ\"ו ע' נז ואילך. ד\"ה אנכי ה\"א בסה\"מ תרח\"צ ע' רסג ואילך. ד\"ה והאיש משה עניו תרח\"צ (נדפס בקונטרס בפ\"ע ברוקלין תשנ\"ג). ד\"ה ואתה ברחמיך הרבים בסה\"מ תש\"א ע' 64 ואילך. ד\"ה אנכי ה\"א בסה\"מ תש\"ח ע' 219 ואילך. ד\"ה תפול עליהם בסה\"מ תשל\"א ע' 464 ואילך.\nוראה עוד לעניני המאמר: שערי אורה שער הפורים סב, ב ואילך. תורת חיים ויגש צא, ד ואילך. מאמרי אדהאמ\"צ בראשית ס\"ע לז ואילך. וע' שפ ואילך. ויקרא ח\"א ע' קכה-ו. דברים ח\"ד ע' א'שטו ואילך. המשך תרס\"ו ע' רכ ואילך. סה\"מ תרנ\"ז ע' רב ואילך. עזר\"ת ע' קל. המשך ר\"ה תרצ\"ד (סה\"מ תשי\"א ע' 6. 36 ואילך. 51. 83 ואילך. 112 ואילך). סה\"מ תשט\"ו ע' 191-2. 227-8. תשט\"ז ע' 373 ואילך. ועוד."]]],[2000510384,"למטה דלע\"ל, וא\"כ צ\"ל מ\"ש אח\"כ בסוף הפסוק רדה בקרב אויביך מה\"ע הרידוי הזה הלא זה היפך משנ\"ת לעיל.\n<b>אך</b> הענין יובן בהקדם מ\"ש בשירת הים תפול עליהם<sup data-n=\"1240\">2</sup> אימתה ופחד בגדול זרועך ידמו כאבן וגו', כל הפסוק הזה משמע ל' עתיד שעתיד ליפול עליהם אימתה ופחד והיינו כשיתגלה בחי' אימתה בה' הידיעה שהוא בחי' גילוי מל' דא\"ס<sup data-n=\"1241\">3</sup> לע\"ל, אם שעתה הוא ג\"כ מלך אלקי' על גוים, אמנם הנה כ\"ז הוא בהעלם והסתר בהתלבשות בע' שרים דנוגה, אבל לע\"ל כשיתגלה מל' ויקויים מ\"ש ונגלה כבוד ה' וראו כל בשר, שזהו מה שאנו מבקשים גלה כבוד מלכותך, מלכותך דוקא הוא בחי' גילוי מל' דא\"ס אז גם עליהם תפול אימתה ופחד כו' וכמ\"ש ובאו במערות צורים מפני פחד ה' והדר גאונו.\n<b></b>[לב)] ובכדי להבין זה צ\"ל הקדמה אחת כללית<sup data-n=\"1242\">4</sup> לכללות סדר ההשתלשלו' מריש כל דרגין עד סוכ\"ד שא\"א להיות כל בחי' ההשתל' עו\"ע בפרט ובכלל אם לא ע\"י ג' בחי', והם שתים שהן ארבע, והוא יש מאין, ואין מיש, הראשון מלמעלמ\"ט הוא מצד המשפיע הוא בחי' יש האמיתי כו', ובחי' יש השני הוא בחי' המקבל, היינו מה שנברא העולם ליש ודבר בדברים רבים שהם כולם בחי' יש ומציאות כאו\"א בפ\"ע, והממוצע בין בחי' יש הא' שמצד המשפיע שהוא היש האמיתי לבחי' היש הב' דנבראי' שהוא הוה ונפסד, וגם בעת היותו הנה הוא רק נדמה ליש ודבר, אבל באמת הוא רק בחי' העלם והסתר שמעלים על האור האלקי כו', או גם אם נאמר שהוא בחי' מציאות ממש, מ\"מ הרי נת' במ\"א שאינו בבחי' מציאות אמיתי כלל כמ\"ש באורך בד\"ה מי כמוכה ובד\"ה מהיכן זכו<sup data-n=\"1243\">5</sup> ישראל לק\"ש, הנה הממוצע ביניהם הוא בחי' אין, ובלעדי האין א\"א שיומשך כלל התהוות יש הב' דנבראים מבחי' יש האמיתי מצד ריחוק הערך שביניהם, וזהו כציור תמונת אות אל\"ף שיש יו\"ד בראשו ויו\"ד בסופו, והוא\"ו שהוא הקו ההולך באמצע האל\"ף משמאל לימין הוא מחברם יחד, כ\"ה בב' בחי' יש הוא כדמיון ב' יודי\"ן דאל\"ף עליון ותחתון, והאין המחברם הוא כדמיון הקו שבאמצע האל\"ף, או כמו תמונת וציור אות יו\"ד שיש בו קוץ בראש שהוא קוץ העליון וקוץ בסוף הוא בחי' קוץ התחתון, ועצם תמונת היו\"ד הוא מחבר ב' הקוצין. אמנם הנה צ\"ל דהנה במשל האותיות דאל\"ף ויו\"ד הנה המחבר שבין ב' יודי\"ן דאל\"ף או עצם היו\"ד שמחבר ב' הקוצין שלו, הנה יש איזהו",[["1240","2","<b>אך הענין יובן בהקדם מ\"ש. . תפול עליהם</b>: בהבא לקמן בפיסקא זו ראה תו\"ח שמות שם רסד, א. [ובהוצאת תשס\"ד קפה, ב]."],["1241","3","<b>מלכותך. . בחי' גילוי מל' דא\"ס</b>: ראה תו\"א יתרו עג, סע\"ד. אוה\"ת ויצא (כרך ה) תתסג, סע\"א. ובכ\"מ."],["1242","4","<b>ובכדי להבין זה צ\"ל הקדמה אחת כללית</b>: בהבא לקמן (עד פיסקא: ועפ\"י הקדמה זו יובן ענין קרי\"ס) ראה תו\"ח שמות שם רסו, א ואילך. [ובהוצאת תשס\"ד קפו, ד ואילך]."],["1243","5","<b>נת' במ\"א. . בד\"ה מי כמוכה ובד\"ה מהיכן זכו</b>: ד\"ה מי כמוכה בסה\"מ תרכ\"ט ע' קסא ואילך. וד\"ה מהיכן זכו בסה\"מ תרכ\"ז ע' שפו ואילך. [ובהנסמן שם בתחילת המאמר]."]]],[2000510385,"גשם המחבר אותם שהוא קו האמצעי שבאל\"ף ועצם ממשות השחרות דנקודת היו\"ד<sup data-n=\"1244\">6</sup>, אך בחי' האין שמחבר את ב' בחי' היש הנה מצד היותו אין ואפס איך הוא מחבר, הלא פי' אין הוא כי איננו ואיך הוא מחבר כו'.\n<b></b>[לג)] והענין הוא דהנה אמרנו לעיל שהם שתים שהן ארבע<sup data-n=\"1245\">7</sup>, והיינו כי בחי' האין הזה אין פירושו שוה לגבי המשפיע כמו לגבי המקבל שהם ב' בחי' יש הנ\"ל, יש האמיתי הוא המשפיע הכל כמ\"ש כי ממך הכל ויש הנברא הוא המקבל, והיינו כי מלמעלמ\"ט פי' אין הוא שאינו תופס מקום כלל, והיינו כי בכדי שיוכל להיות התהוות הנבראי' או אצילו' הנאצלי' מאתו ית' הבלתי בעל גבול ובעל תכלית כלל וכלל, ואיך יתהוה מאתו אצי' שהם מספר ע\"ס עשר דוקא ולא אחד עשר וכמ\"ש בס\"י ע\"ס כו' עשר ולא תשע עשר ולא אחד עשר, אלא שבכדי להאציל ע\"ס זה הי' ע\"י צמצום שסילק אורו הגדול על הצד עד שנמשך הארה בעלמא שאינה תופס מקום כלל וכלל, שלכן אני הוי' לא שניתי. דלכאורה יפלא האיך נאמר אני הוי' לא שניתי הלא נאצלו הנאצלים ונבראו הנבראי' ונוצרו היצורים ונעשו הנעשים ואיך נאמר שלא יש שום שינוי בין קודם הבריאה והאצי' לאחר הבריאה והאצי', אלא שמפני כי כל התהוות בין הבריאה בין האצי' נתהוו מהארה בעלמא שאינה תופסת מקום כלל וכלל, עד שבאמת אין שינוי כלל שאתה הוא קודם שנבה\"ע ואתה הוא לאחר שנבה\"ע בלי שום שינוי ממש. וא\"כ פי' ענין האין מה שנמשך מאתו ית' בחי' יש האמיתי הוא פי' שהוא אין ואפס ואינו תופס מקום כלל וכלל לגבי יש האמיתי המשפיע, ועש\"ז הונח לו שם אין ע\"ש העדר תפיסתו כלל.\n<b>אך</b> בחי' האין המקור להמקבלים היינו בחי' האין המהוה היש השני דמקבלים, הנה פי' אין שאינו מושג כלל וכלל, ונמצא פי' יש מאין שאנו משיגים מלמטלמ\"ע פי' שנתהוה הבריאה ליש ודבר מבחי' אין היינו בחי' מה שאינו מושג לנו כלל וכלל מה הוא. והיינו כמשנת\"ל בענין הנפש המחי' את הגוף, הנה אין אנו יודעים ומשיגים מהות הנשמה מה היא כלל, ואין לך דבר קרוב יותר מהארת הנפש המחי' את הגוף לגבי הגוף, שהשכל והשגה שבאדם שמלובש במוח החכ' והבינה אינם משיגי' כלל את מהות הנפש המחי' אותם, וכד דייקת בי' שפיר תמצא שהמשיג הוא בחי' הכח הרוחני שמלובש בגשם המוח, דאל\"כ היתכן שגשם המוח עצמו משיג הלא הוא דבר ההוה ונפסד ונרקב והי' לעפר, והרי בצאת הנפש מן הגוף ה\"ה מוטל כאבן דומם ואיננו מרגיש מאומה להשכיל ולהבין איזה דבר, ונמצא כי המשכיל והמבין הוא בחי' כחות הנפש בעת התלבשותם באברי הגוף, ומאחר כי בעת התלבשותם במוח האדם אינם משיגים מהות הנפש מה היא, רק ע\"ד ידיעת המציאות שיודע שיש בו",[["1244","6","<b>ועצם ממשות השחרות דנקודת היו\"ד</b>: בד\"ה בכ\"ה בכסלו תרנ\"ג שם מוסיף: ובפרט כידוע דעיקר היו\"ד הוא הנקודה האמצעית, והקוץ העליון והקוץ התחתון הם קוצין בלבד כו'."],["1245","7","<b>והענין הוא דהנה אמרנו לעיל שהם שתים שהן ארבע</b>: בהבא לקמן ראה בארוכה המשך תער\"ב ח\"ב שם ע' א'קנ ואילך."]]],[2000510386,"נפש המחי' אותו אבל אינו יודע כלל וכלל מהו מהות הנפש שלו עצמו, א\"כ צ\"ל שגם כוחות הנפש אינם משיגים מהות הנפש מה היא, והיינו מפני כי כשם שהנברא הוא יש מאין כן החיות המחי' אותו הוא בבחי' הסתר והעלם ממנו. ונמצא פי' אין מלמטלמ\"ע הוא אין שאינו מושג, ולא כפי' אין שלגבי המשפיע שהוא אין ואפס, דהאיך נאמר על כל מקור החיות וכחות הגוף שהוא אין ואפס ומאין נמשך לו כח השכל להשכיל או כח ההשגה להבין איזה [דבר], וכח הדבור לדבר והמח' לחשוב והמעשה לעשות, אם לא שיש איזה דבר כללי שמאתו נמשך כחות הפרטים<sup data-n=\"1246\">8</sup> האלו. והגם שהשגתינו זה הוא רק בדרך ידיעת המציאות, מ\"מ, הרי אנו יודעים זה על בורי' בלתי שום ספק וספק ספיקא כלל וכלל, ורק מפני שאין אנו יודעים מה הוא לכן אנו קוראי' אותו אין<sup data-n=\"1247\">9</sup>, פי' שאינו מושג.\n<b>וכן</b> יובן ד\"ז בכלליות הנבראים והנוצרים והנעשים, שכל דבר נברא שאנו רואים שהוא נברא יש מאין פי' מאין היינו ממה שאינו מושג כלל. ובאמת לשון נברא לא יתכן כלל אם הי' מושג הדבר המהוה, שאם דבר המהוה זה מושג להדבר המתהוה א\"א לקוראו בשם נברא כ\"א בשם עלול<sup data-n=\"1248\">10</sup> שזהו בחי' השתלשלות, וכמו השלשלת שטבעת א' דבוקה ואחוזה בחברתה, כן הוא בחי' עו\"ע שכאו\"א משיג העליון ממנו, עד\"מ עלול שלמטה הנה הוא מלביש ז\"ת של העילה הקדומה לו ואז הוא נעשה עילה שיומשך ז\"ת שלו להעלול שלמטה הימנו, ועד\"ז הוא מריש כ\"ד עד סוכ\"ד בבחי' ההשתלשלו' שכולם הם בחי' עו\"ע. והנה אם הי' כן בבחי' הנבראי' דבי\"ע, לא היו יכולים להיות בשם מציאות גשם דבר מה כלל, כ\"א הי' הכל רוחניות, וע\"ד עולם האצי' שהוא אלקות<sup data-n=\"1249\">11</sup>, שהרי מה שיתהוה הגשמי' מן הרוחני' אין לך בריאה יש מאין גדול מזה, כמו שהונח דבר זה גם אצל חכמי המחקר. ונמצא כי לשון וענין בריאה אינו יתכן כ\"א שהסיבה הקדום לה המהוה אינו בדרך העילה המשפעת לעלול, כי העלול משיג מקצת העילה, משא\"כ הנברא אינו משיג כלל מהות הרוחני המחי' אותו, כמו שהגוף אינו משיג מהות הנפש מה היא כ\"א בדרך ידיעת המציאות, וכן כל דבר נברא משיג אשר יש כח רוחני המחי' ומהוה אותו, אמנם משיג רק ע\"ד ידיעת המציאות. וזה\"ע בריאה יש מאין, פי' מאין מבחי' שאינו מושג כלל מה הוא.",[["1246","8","<b>שיש איזה דבר כללי שמאתו נמשך כוחות הפרטים</b>: בד\"ה בכ\"ה בכסלו תרנ\"ג שם מוסיף: והרי הוא מרגיש בהכוחות שהן נמשכין ממקורם הוא הארת הנפש הכללי, וכמו כשנופל לו שכל חדש ה\"ה מרגיש שנמשך מלמעלה כו', רק שהוא ידיעת המציאות ולא השגת המהות."],["1247","9","<b>מפני שאין אנו יודעים מהו לכן אנו קוראי' אותו אין</b>: ראה סה\"מ תרנ\"ט שם ס\"ע מה (ועד\"ז בהמשך תער\"ב ח\"ב שם ע' א'קנא): כמו ויקראו אותו מן כי לא ידעו מה הוא."],["1248","10","<b>א\"א לקוראו בשם נברא כ\"א בשם עלול</b>: בד\"ה בכ\"ה בכסלו תרנ\"ג שם מוסיף: וכידוע ההפרש בין בריאה יש מאין להשתלשלות עו\"ע, דהשתלשלות עו\"ע הוא שהעלול משיג את עילתו כו', אמנם התהוות היש הוא שמהווה דבר שאינו בערכו, שהמהווה רוחני והמתהווה גשמי, והיינו ע\"י שהמהווה מסתתר מהמתהווה."],["1249","11","<b>הי' הכל רוחניות וע\"ד עולם האצי' שהוא אלקות</b>: ראה ד\"ה בכ\"ה בכסלו תרנ\"ג שם ע' קסח שעולם האצי' שהוא גילוי ההעלם מאלקות הוא בבחי' עו\"ע. עיי\"ש."]]],[2000510387,"<b></b>[לד)] ונמצא כי בבחי' האין הממוצע בין ב' בחי' היש הנ\"ל הוא ב' בחי' אין, הא' הוא האין שלגבי היש האמיתי המשפיע, שפי' אין מה שהוא אין ואפס לגבי בחי' היש האמיתי, ונק' אין ע\"ש היותו הארה מועטת ומצומצמת מאד לגבי המשפיע, עד שא\"א ולא יתכן כלל לקרותו בשם מציאות נמצא כ\"א בשם אין, הב' הוא בחי' האין שמקור ליש הנברא<sup data-n=\"1250\">12</sup>, פי' אין ע\"ש שאינו מושג כלל מהו, שזהו ג\"כ בכלל אין, כי כשם שא\"א לכנות ההארה שאינה תופסת מקום בשם מציאות כ\"א בשם אין, כן הדבר אשר בלתי מושג ג\"כ א\"א לכנותו אלא בשם אין, כי האיך נניח שם עליו כי הוא זה מאחר שאין אנו יודעים כלל מהו ומהותו ואיכותו. אלא שבזה הוא ההפרש בין ב' בחי' אין האלו, שהאין שלגבי המשפיע נק' אין ע\"ש עצמו, שהוא בעצם הוא אין ואפס לגבי בחי' היש האמיתי ואינו עולה בשם ועש\"ז נק' אין, אמנם בחי' האין הב' שהוא האין המקור להיש הנברא שהוא נק' ג\"כ אין, אמנם לא ע\"ש עצמותו ואיכותו כמו האין הא' שלגבי יש האמיתי, כ\"א ע\"ש העדר השגתו הונח לו שם אין, אבל בחי' מהותו ואיכותו לא נודע לנו כלל, ולכן אין אנו יכולים לכנות לו שם מפני כי אין אנו יודעים כלל מה הוא, והאיך ומה לכנותו ע\"ש עצמותו כו'. ונמצא כי האין הא' נק' אין ע\"ש מהותו ואיכותו, ואין הב' ע\"ש ההעדר מהשגתינו וההעלם שמתעלם מאתנו, עש\"ז הונח לו שם אין. יהי' איך שיהי' שניהם הם נק' בשם אין<sup data-n=\"1251\">13</sup>, לכן בכלל הוא רק ג' בחי', יש האמיתי, ואין, ויש הנברא. ובפרטיות האין הממוצע הוא ב' בחי' האין, שלגבי יש האמיתי שנק' אין ע\"ש שאינו תופס מקום, הונח לו שם אין ע\"ש עצמותו לגבי יש האמיתי, ואין הב' הוא ע\"ש העדר ההשגה בו, ולכן לגבי המקבלים הם הנבראי' והנוצרים והנעשים ממנו נק' אין ע\"ש ההעלם והעדר ההשגה בו כלל וכלל, ולכן אין אנו יכולים לערוך לו שם כ\"א אין. וזהו שתים שהן ארבע, ב' בחי' היש הם שתים שהם העיקר, להיות כי עיקר המכוון מכל בחי' בריאות העולמות הוא שיהי' מציאות העוה\"ז הלזה הגשמי, להיות כי כך עלה ברצונו ית' ונתאוה הקב\"ה להיות לו ית' דירה בתחתונים דוקא, אשר זה מושג לנו, והטעם למה נתאוה זהו אינו מושג לנו כלל<sup data-n=\"1252\">14</sup> כמ\"ש מזה בד\"ה ואהבת את (למ\"ד<sup data-n=\"1253\">15</sup>), ומקור בחי' היש הזה הוא מיש האמיתי כי ממך הכל, והממוצע ביניהם הוא בחי'",[["1250","12","<b>ב' בחי' אין. . שלגבי היש האמיתי. . שמקור ליש הנברא</b>: ראה גם אוה\"ת וישלח רלא, ב. שם (כרך ז) תתתל, א. תבוא ע' תתרלז. תתרמג. קיצורים והערות לתניא ע' מט-נ. סה\"מ תרכ\"ו ע' רלא. תרכ\"ז ע' תיב. תרל\"ג ח\"א ס\"ע שיט-כ. ובארוכה תו\"ח וישלח מד, א ואילך."],["1251","13","<b>יהי' איך שיהי' שניהם הם נק' בשם אין</b>: ראה ד\"ה בכ\"ה בכסלו תרנ\"ג שם: על שניהם אינו נופל כ\"א שם אין, דכמו שעל האין של היש אמיתי אינו שייך לקרותו כ\"א שם אין שה\"ה העדר מציאות דבר מה בעצם כו', כמו\"כ האין של היש הנברא א\"א לקרותו כ\"א בשם אין, שא\"א לנו לקרותו בשום שם מאחר שאין אנו יודעים מה הוא כו' כ\"א בשם אין כו'."],["1252","14","<b>והטעם למה נתאוה זהו אינו מושג לנו כלל</b>: ראה מאמרי אדה\"ז תקס\"ג ח\"א ע' שלח. אוה\"ת בלק ע' תתקצז. סה\"מ תרכ\"ז ע' תנג-ד [ובהמ\"מ שם]. המשך תרס\"ו ס\"ע ז. סה\"מ תש\"ב ע' 34. לקו\"ש ח\"ו ע' 21. ועוד."],["1253","15","<b>כמ\"ש מזה בד\"ה ואהבת את (למ\"ד)</b>: סה\"מ תר\"ל ע' רלה. וראה שם ע' רפט."]]],[2000510388,"האין, ואין זה עצמו נחלק לב'<sup data-n=\"1254\">16</sup>, היינו אין מה שהוא אין ואפס לגבי המשפיע, ומה שהוא אין היינו מה שאינו מושג לנבראי' כלל וע\"ש ההעלם ובחי' העדר ההשגה נק' אין כו'. אך עדיין צ\"ל למה צריכים לבחי' האין שהוא הממוצע בין ב' בחי' היש, למה לא יתהוה מהיש האמיתי בחי' מציאות היש הנברא, ולמה יצטרך להאין להיות ממוצע בין ב' בחי' היש.\n<b></b>[לה)] ויובן ד\"ז מכמה משלים גשמי'<sup data-n=\"1255\">17</sup> שנראה לעין כל שלא ימלט מג' דברים אלו יש ואין ויש, והמשל הפשוט הוא מנביעת המעיינות מן התהום אשר מתחת לארץ, ומהמעיינות נמשכים נהרות רבות, הרי התהום הוא היש המקור להנהרות, שהם ג\"כ הם בבחי' יש ודבר התפשטות דבר מה במהות ואיכות וכמות ושטחי הנראה לעין כל, והממוצע ביניהם הוא המעיין אשר דק ונובע לאט לאט, ונמצא כי התהום הוא היש הא' שהוא המקור לכל הנהרות, והמעיינות המה בבחי' אין<sup data-n=\"1256\">18</sup> שהרי דקותם וערך המים הנמצאים בהם הוא אינו תופס מקום כלל נגד התהום רבה אשר מתחת לארץ, וכן אינו עולה בשם נגד הנהר הנמשך אח\"כ מנביעתו. ונמצא זהו כענין יש ואין ויש הנ\"ל שבכלליות הנבראי', והיינו לפי שא\"א שיומשך יש מיש א\"ל ע\"י ממוצע, והוא בחי' האין אשר הוא ממוצע בין היש המשפיע להיש המקבל כו'. ויובן זה בדקות יותר מענין הצמיחה<sup data-n=\"1257\">19</sup> שצומח אילנות ודשאים ותבואות וזרעוני גינה וכדומה, והרי כח הצומח בכלל על כל בחי' הצמיחה הן פרי העץ והן פרי האדמה בכלל הנה הוא בחי' יש המשפיע, שהרי הוא המשפיע שיוצמח כל דבר כו', אמנם הצמיחה פרטיות בכל דבר פרטי כמו בכל קש פרטי הנה יש בה הארה מכח הצומח הכללי, הרי הוא בחי' אין, והיינו בחי' כח הרוחני של הפרי שאינו נראה ונגלה עדיין בעיני הראות הוא בחי' האין, וכשצומח הפרי הרי היא בחי' היש השני המקבל. ונמצא כי יש בצמיחה זו יש ואין",[["1254","16","<b>ואין זה עצמו נחלק לב'</b>: ראה ד\"ה בכ\"ה בכסלו תרנ\"ג שם: דבחי' האור היינו האין בכלל ה\"ה מתעבה כמו שנמשך ממדרי' למדרי', דהרי כמו שהוא בחי' אין של היש האמיתי ה\"ה בטל במציאות שאינו עולה בשם כלל, משא\"כ כשהוא בבחי' אין של יש הנברא ה\"ה בבחי' מציאות דבר מה והיינו מפני שנתרחק ממקורו, דכשהוא קרוב לגבי מקורו ה\"ה בטל במציאות בעצם, וכשנתרחק ממקורו ה\"ה בבחי' מציאות ואז אפשר להיות מקור למציאות הנבראים כו'."],["1255","17","<b>ויובן ד\"ז מכמה משלים גשמי'</b>: בהבא לקמן בפיסקא זו ראה שערי אורה שם סב, ב ואילך (שם הובאו ע\"ז ד' משלים). סה\"מ תרנ\"ז שם ע' רב ואילך (ושם מוסיף: וענין העלם והסתר המהווה מהמתהווה לא יש במשל כו', דענין התהוות יש מאין לא נמצא בנבראים כו')."],["1256","18","<b>והמעיינות המה בבחי' אין</b>: ראה ד\"ה תפול עליהם בסה\"מ תשל\"א שם."],["1257","19","<b>והמשל. . מנביעת המעיינות מן התהום. . ויובן זה. . מענין הצמיחה</b>: ראה סה\"ש תרצ\"א ע' 150: הא דתמיד מבארים ב' המשלים דתהום וכח הצומח יחד (לענין יש ואין), מפני שכח הצומח העצמי שבארץ והתהום שמתחת לארץ יש להם שייכות זל\"ז, אבל אין מפרסמים טעם זה. וראה גם אג\"ק אדמו\"ר מהוריי\"צ ח\"ב ע' שיב ואילך."]]],[2000510389,"ויש, היינו כח הצומח הכללי הוא יש, וכח הרוחני דפרי זו הוא בחי' אין, וגשם הפרי הנצמחת היא היש השני כו', ולכן כשזורעים תבואה או גרעיני הפירות א\"א להם לצמוח כ\"א כשמרקיבין תחלה<sup data-n=\"1258\">20</sup>, והיינו בכדי שיהי' כלי לקבל בחי' כח הצומח צריכה תחלה להתבטל מבחי' הישות שלה לגמרי, ואז ה\"ה כלי לקבל בחי' הארת כח הצומח הרוחני שהוא מקור לצמיחת פרי הגשמי הלזה כו'. ועוד משל היותר רוחני יובן מחיות הנפש<sup data-n=\"1259\">21</sup> שבאדם שבודאי בחי' יחידה שבנפש שלמעלה מבחי' כחות הנפש הוא בחי' יש המשפיע הכל היינו כל חיות הנפש כו', וחיות פרטי האברים ה\"ה בחי' אין, כי כלליות ההארה מהנפש שמחי' את הגוף לגבי עצמיות הנפש היא הארה בעלמא שאינה תופסת מקום כלל, והגוף החי מהארת הנפש הוא בחי' יש המקבל, שנמצא יש באדם בחי' יש ואין ויש. ובאמת האין הממוצע כלול מב' בחי' אין, הוא בחי' האין לגבי היש המשפיע, והאין שמקור ליש המקבל, רק שאין להאריך בזה יותר<sup data-n=\"1260\">22</sup>.\n<b>ואמנם</b> עדיין אינו מיושב, שכל המשלים שהבאנו זהו רק מהנבראי' הגשמי' שלנו, שמציאות הצמחי' או חיות האדם או נביעת המים א\"א כ\"א ע\"י ג' דברים אלו דוקא שהם יש ואין ויש, אשר מזה נבין שגם מציאות התהוות הנבראי' והנאצלי' מאתו ית' א\"א כ\"א ע\"י ג' בחי' אלו, הלא הוא ית' כל יכול<sup data-n=\"e63\">ו</sup> ובכחו ויכולתו לעשות שיהי' התהוות יש מיש<sup data-n=\"1261\">23</sup> ולא אין מיש ויש מאין. אך הענין הוא שלא רצה לעשות בנבראי' דבר אשר בהם א\"א להיות זה, ובאמת אם הי' עושה בנבראים דבר נפלא כזה שיהי' התהוות יש מיש הי' בהכרח שיהי' בנבראי' דבר עליון וגבוה יותר מאשר הם כעת, וברצונו ית' עלה שיהי' העולם והנבראים אשר בעולם באופן שהם עתה, ולכן אם מצד היותו כל יכול לא ימנע מאתו זה ח\"ו, אמנם מצד מצב הנבראים אשר הוגבלו שיהיו באופן כזה דוקא מעכב שיהי' הדבר כן ע\"י קדימת האין ליש ושיהי' מציאות התהוות יש הנברא ע\"י ממוצע של האין. ואם כי מצד היותו כל יכול הי' יכול להתהוות מציאות הנבראי' בבחי' יש מיש ומ\"מ בהם לא יהי' יתרון מכמו שהם",[["1258","20","<b>כח הצומח. . המשפיע שיוצמח כל דבר. . כשמרקיבין תחלה</b>: ראה בכ\"ז אגה\"ק סי' ח (קיג, א). לקו\"ת בהר מ, ב. נצבים נ, ד ואילך. נב סע\"ג ואילך. סה\"מ תרל\"ג ח\"א ע' רפח ואילך. תרס\"ט שם ע' ז ואילך."],["1259","21","<b>ועוד משל היותר רוחני. . מחיות הנפש</b>: בתו\"ח שמות (ובסה\"מ תרנ\"ג) שם: המשל האמיתי לכל זה."],["1260","22","<b>ובאמת האין הממוצע כלול מב' בחי' אין. . רק שאין להאריך בזה יותר</b>: ראה תו\"ח שמות שם רסו, סע\"ב ואילך. [ובהוצאת תשס\"ד קפז, ב ואילך]. ובסה\"מ תרנ\"ג שם ע' קע. (ובעוד מקומות שנסמנו לעיל בתחילת המאמר)."],["1261","23","<b>הלא הוא ית' כל יכול. . לעשות שיהי' התהוות יש מיש</b>: ראה בכ\"ז סה\"מ תרנ\"ג שם ס\"ע קע-קעא. תרנ\"ח ע' קכ. תרנ\"ט ע' קמד. תש\"ד ע' 69. לקו\"ש חכ\"ט ע' 30. סה\"ש תשמ\"ח ח\"א ע' 135. ועוד.\n\n<b>ו</b>  <b>הלא הוא ית' כל יכול</b>: בשולי הגליון נרשם בגוכי\"ק: הלא הוא כל יכול, הרי הי' יכול להיות היש הנברא גם מיש האמיתי בלי קדימת האין, שהרי אינו דומה להמשלים כלל, שהוא כל יכול. אך הענין שמצ\"ע הוא כל יכול, אמנם לא רצה לעשות בנבראים מה שהוא לגבם בלתי אפשרי, ועשה הנבראים לפ\"ע שלהם."]]],[2000510390,"עתה, אמנם כך עלה ברצונו ית' שיהי' התהוות הנבראי' שוה כמותם והיינו שחיותם יהי' לפ\"ע קבלתם הגם כי ביכולתו הי' בא\"א כו'.\n<b></b>[לו)] ועפ\"י הקדמה זו יובן ענין קרי\"ס, דהנה ים ויבשה הוא בחי' העלם וגילוי שהיבשה היא בחי' ארץ הוא בחי' גילוי, משא\"כ ים הוא בחי' עלמא דאתכסיא שנק' עלמא דאתכסי' ע\"ש היותו מכוסה ונעלם מגילוי, והנבראי' שבים ה\"ה מכוסים במי הים שזהו מורה ג\"כ על בחי' היחוד שלהם בשרש ומקור המהוה אותם, שהרי קבלת החיות שלהם הוא באופן שיהיו מובלעים במי הים והים מובלע בתוכם ונק' ברואי' הנבראים ממים כלשון רז\"ל כל שהוא מבריאות המים, משא\"כ בברואי' שבארץ אם כי הכל הי' מן העפר אפי' גלגל חמה האם נאמר על החמה לשון מבריאות הארץ, וגם הנה היא מארת ומברקת שלא נמצא כן בארץ כלל שנדמה שהיא מהות אחרת לגמרי הגם שבאמת היא ג\"כ מן העפר. ונמצא ענין הפך ים ליבשה הוא שנהפך ההעלם לגילוי ונעשה בעלמא דאתגליא<sup data-n=\"1262\">24</sup> הגילוי מה שהי' בעלמא דאתכסיא, ולכן ראתה שפחה שהיא ממדרגות התחתונות דעשי' מה שלא ראו הנביאים, שהרי הנביאים ראו בבחי' דמות כו', ובקרי\"ס כאו\"א אמר זה אלי שהי' הגילוי בבחי' זה כו'.\n<b>וענין</b> בחי' קרי\"ס בעבודה שבנפש ומה השיגו אז בנפשותם, י\"ל כי בהיות הנפש מלובש בגוף הנה הגוף ונה\"ב מעלימים ומסתירי' לגמרי על אור הנפש, שמצד העלם הגוף ותאוות הנה\"ב יוכל האדם לעשות היפך רצונו ית', שלכאו' יפלא הלא נפש האדם היא חלק אלק' ממעל והיתכן שהחלק יפרד כ\"כ עד שתוכל לעשות היפך רצון הכללי, אלא שזהו ע\"י העלם הגוף שמעלים ומסתיר על אור ה' וקדושתו, בראותו שהעולם מעלים ומסתיר על החיות המלובש בו וכל יום דומה לחבירו שעולם כמנהגו נוהג, אשר מחמת ריבוי ההעלמים נדמה לו היש לעיקר, ומחמת כח המתאוה אשר בנפשו הבהמית הנה הוא מתאוה תאוה למלאות רצון נפשו הבהמית המגושמת מאד, ועי\"ז יוכל לבוא לידי חטא ועון ומחטיא את נה\"א ג\"כ. אך כ\"ז הוא מפני כי חיות נפשו אשר בו איננו מושג כלל ורק יודע בדרך ידיעת המציאות ולא השגת המהות כלל וכלל וכנ\"ל, אבל אם הי' רואה בראי' חושיית נפשו המחי' וחיותה מאלקות לא הי' מתאוה כלל לדבר אחר זולת אלקותו ית' בחי' חיי החיים. ולזאת כשהלכו ישראל בים ביבשה והעלם הים נתגלה להם בבחי' הגילוי, אז האיר בגופות שלהם העלם ואין הנפש, היינו מה שבכל עת הוא אין ע\"ש העלמו נתגלה זאת בגופות שלהם, לכן כאו\"א אמר זה אלי בבחי' גילוי, כי להיות הנפש היא חלק אלק' וע\"י החלק הזה השיגו בחי' הכלליות, ולכן אמרו אשירה לה' וגו' זה אלי לשון כחי מלשון ואת אילי הארץ לקח, להיות כי השיגו נפשם לפי שעה בבחי' גילוי כו'.",[["1262","24","<b>ים ויבשה. . העלם וגילוי. . עלמא דאתכסיא. . בעלמא דאתגליא</b>: ראה בכ\"ז תו\"א בשלח סב, א. לקו\"ת צו יד, ב ואילך. שער האמונה לאדהאמ\"צ צד, א ואילך. לקמן ד\"ה כל הנחלים. וש\"נ."]]],[2000510391,"<b></b>[לז)] והנה קרי\"ס שמעו כל מלכי מזרח כו' ותמהו מאד ע\"ז להיות כי נפלא בעיניהם מאד, כי באמת זהו דבר פלא מאד לשנות הטבע, שטבע המים להיות נמשכים וכאן עמדו כמו נד וביניהם נעשה יבשה והעביר ישראל בתוכו שזהו פלאי פלאים. אמנם על הגילוי דלע\"ל נא' כימי צאתך מאמ\"צ אראנו נפלאות, שהפלאים שיהי' לע\"ל יהי' יותר הרבה מהנפלאות דיצ\"מ<sup data-n=\"1263\">25</sup> וקרי\"ס, והיינו כי בקרי\"ס נתגלה העלם דים שי\"ל שזהו בחי' האין המהוה היש, אבל לע\"ל כשיתגלה בחי' האין שלגבי יש האמיתי (או מבחי' יש האמיתי), וזהו אימתה בה' הידיעה, אז תפול גם עליהם האימה ופחד, ונהרו אליו כל הגוים שזה נא' במלך המשיח שמחמת עוצם הגילוי שיאיר עליו ונהרו אליו כל הגוים שזהו מחמת ההרגש האימה והפחד.\n<b>ועז\"נ</b> רדה בקרב אויביך פי' ענין רדה הוא השליטה והממשלה, ולא ענין הרידוי במקל ומטה כמו שהי' בקרי\"ס שהי' צריך להכות הרשעים כנ\"ל, כ\"א ענין הרידוי הוא בחי' השליטה והממשלה וכמ\"ש ורדו בדגת הים שפי' ענין ממשלה ושליטה. וזהו ההפרש בין מטה דקרי\"ס למטה דלע\"ל, שמטה דקרי\"ס הי' ענין הנקימה מפרעה וחילו שהי' צריך למטה בשביל לרדות בו את הרשעים וכנ\"ל מה דרכו של כלב כו', אבל המטה דלע\"ל הוא ל' ממשלה ושליטה ולכן נא' מטה עוזך ולא סתם מטה, והיינו שהמטה רומז על עוזך שיש בך לשלוט על הכל ולכן רדה בקרב אויביך<sup data-n=\"e64\">ז</sup> שהו\"ע הממשלה והשליטה על כולם כו'.",[["1263","25","<b>כימי צאתך מאמ\"צ אראנו נפלאות. . יותר הרבה מהנפלאות דיצ\"מ</b>: ראה אוה\"ת נ\"ך (כרך א) ע' תפו-ז. סה\"מ מלוקט ח\"ב ע' לז ואילך.\n\n<b>ז</b>  <b>ולכן רדה בקרב אויביך</b>: בשולי הגליון נרשם בגוכי\"ק: ועדיין אינו מיושב ל' אויבך, מאין ימצא אויבים, מאחר שגם עליהם תפול אימתה, אך ענין יראת האימה הוא כענין גירי אריות שמחמת אימה קיבלו עליהם ד\"י<sup data-n=\"1638\">161</sup>, א\"כ צ\"ל פי' אז אהפוך כו' לקרוא כולם כו' שכם אחד, שכם אחוריים."],["1638","161","<b>ד\"י</b>: דת ישראל (או: דת יהודית)."]]],[2000510392,"<h3>[כל הנחלים הולכים]</h3>\n<b></b><b>[ד\"ה כל הנחלים הולכים אל הים]\nבס\"ד. פ' אמור.</b>\n<b></b>ולהבין כו' שרש ענין ים וארץ כו' כל הנחלים\nאמור\n<b></b>[לח)] ולהבין בתוס' ביאור ענין הגילוי דקרי\"ס ומאיזה בחי' הגיע הגילוי, צ\"ל שרש ענין ים וארץ למעלה מה הוא. הנה כתיב<sup data-n=\"1264\">1</sup> כל הנחלים הולכים אל הים<sup data-n=\"1265\">2</sup> והים איננו מלא אל מקום שהנחלים הולכים שם הם שבים ללכת, ופי' רש\"י לפי שחוזרים והולכים תחת ההרים במחילות מאוקיינוס, וכ\"פ הת\"י בשינוי לשון קצת, ולכן צ\"ל מהו ענין הים שלפי מה שא' ברישא דקרא הנה הוא מקבל מהנחלים כאומרו כל הנחלים הולכי' אל הים, שנמצא הים מקבל מים מהנחלים, ומסיפא דקרא שא' שם הם שבים ללכת משמע שהים משפיע בנחלים. וגם מה שא' והים איננו מלא משמע מזה שגם לפי רישא דקרא שהים מקבל מהנחלים, מ\"מ איננו מקבל גמור שהרי אומר והים איננו מלא שלא כדרך כל המקבלים שמתמלאים מקבלת איזה דבר. וא\"ת שזהו ע\"ד אין הבור מתמלא מחולייתה או ע\"ד לא יחדל אביון הגם כי נותנים לו צדקה, אינו כן שהרי פי' איננו מלא שאינו נעשה בו שום תוס' כלל, וכמארז\"ל במד\"ר במקומו שהמי אוקיינוס בולעים מים, משמע שאינו מיתוסף כלל מהילוך הנחלים לשם. וגם צ\"ל מה שאומר לשון נחלים הלא נהר היא גדולה יותר מנחל כמ\"ש הג\"פ<sup data-n=\"1266\">3</sup> בה' גיטין סי' קך\"ח ס\"ק נ\"ב דבלשון בני אדם נהר קטן אינו נק' נהר אלא נחל, ולפ\"ז מאי דכתי' שהנחלים הולכים יש לדייק נחל ולא נהר, ובאמת גם הנהרות הגדולי' שנמשכי' כמה מאות מילין נופלים ונמשכים לים ובהם נופלים הנחלים הקטנים, אשר גם לפי סיפא דקרא שהים משפיע להם ג\"כ הי' שבח יותר לים שהוא משפיע לנהר הגדול מכמו שהוא משפיע לנחל הקטן, וכ\"ש לרישא דקרא שהים מקבל כו'.\n<b>ובכדי</b> להבין ענין ראשון<sup data-n=\"1267\">4</sup> מהו הים אם משפיע כסיפא דקרא או מקבל כרישא דקרא, הנה אמרו בזהר ויחי דרל\"ה ע\"א תא חזי נקיט מהאי גיסא ויהיב",[["1264","1","<b>הנה כתי' כל הנחלים הולכים אל הים</b>: בהבא לקמן (עד פיסקא: והענין הוא דהנה ים וארץ) ראה אוה\"ת נ\"ך שם ע' א'קב-ג."],["1265","2","<b>ולהבין בתוס' ביאור. . כל הנחלים הולכים אל הים</b>: מאמר זה הוא מאמר השישי שבהמשך והחרים תרל\"א\".\nחלק הא' מהמאמר (עד פיסקא: והענין הוא דהנה ים וארץ) וסיום המאמר (פיסקא: ולפ\"ז יתורץ, ואילך) מיוסד על ד\"ה כל הנחלים הולכים אל הים באוה\"ת נ\"ך (כרך ב) ע' א'קב ואילך.\nחלק הב' מהמאמר (מפיסקא: והענין הוא דהנה ים וארץ, עד פיסקא: ולפ\"ז יתורץ) מיוסד על ד\"ה ענין קי\"ס באוה\"ת בשלח ע' תקסח ואילך. מאמר האוה\"ת הוא הגהות על ביאור לד\"ה ששת ימים בס' מאמרי אדה\"ז תק\"ע ע' עו ואילך. ובשינויים בסה\"מ תרכ\"ח ע' קלז ואילך [ד\"ה בוקע ים]. תרל\"ב ח\"א ע' קלג ואילך [ד\"ה ויט משה]. המשך מים רבים תרל\"ו פרקים קמ-קמה (ע' קנב ואילך). סה\"מ תרל\"ו ח\"ב ע' תעה ואילך. תרע\"ח ע' רנד ואילך. תרח\"צ ע' קפח ואילך. תש\"ה ע' 151 ואילך. תש\"ו ע' 86 ואילך."],["1266","3","<b>כמ\"ש הג\"פ</b>: ס' גט פשוט על הל' גיטין ממהר\"ם בן חביב. (הובא באוה\"ת נ\"ך שם ע' א'קד)."],["1267","4","<b>ובכדי להבין ענין ראשון</b>: בהבא לקמן בפיסקא זו ראה אוה\"ת בשלח שם ע' תקסט."]]],[2000510393,"בהאי גיסא<sup data-n=\"1268\">5</sup>, ועל דא כל הנחלים הולכים אל הים וגו' אמאי איננו מלא בגין דנקיט ויהיב אעיל ואפיק. והיינו כי ים הוא בחי' מל' כמ\"ש בזהר בראשית דל\"ג א', וזהו יקוו המים מתחת השמים אל מקום אחד, פי' מקום אחד קאי על בחי' מל' שהיא משלמת לאחד, ופי' במק\"מ בדל\"ג הנ\"ל שזעיר נק' אח והמל' דלי\"ת לכן המל' משלמת להיות אחד כו', וא\"כ פי' כל הנחלים הולכים אל הים היינו מה שהמל' מקבלת מכל הע\"ס<sup data-n=\"1269\">6</sup> וכמשנת\"ל שמבחי' מל' שבחסד נעשה חסד שבמל', ומבחי' מל' שבגבורה נעשה גבו' שבמל', ועד\"ז כל הע\"ס שבמל' שז\"ע מ\"ש כל הנחלים הולכים אל הים. אך לפ\"ז אינו מובן מ\"ש והים איננו מלא הלא היא מתמלאת להיות נבנה בבחי' פרצוף שלם, וי\"ל שמ\"מ גם אח\"כ היא צריכה לקבל היחוד מבחי' ז\"א בחי' שמש, וכמו יחוד שמשא וסיהרא בכל ר\"ח הגם כי כבר נעשה בנין המל' בכלל בר\"ה ע\"י ט' ברכות וט' תקיעות דר\"ה כמ\"ש מזה במ\"א<sup data-n=\"1270\">7</sup>, ואין כאן מקומו להאריך בזה. אך מ\"מ אינו מובן שהרי אמר הכתוב אל וגו' שבים ללכת, נמצא כי הטעם שאיננו מלא זהו מחמת שהולך שנית להנחלים ולא מפני שאמרנו שהרי המל' גם כשנבנית בבחי' פרצוף מ\"מ צריכה לקבל מהשמש, לכן צ\"ל שהעיקר כמ\"ש בזח\"א ויחי דרל\"ה הנ\"ל אמאי איננו מלא בגין דנקיט ויהיב, והיינו שמקבל מע\"ס דאצי' ומשפיע לבחי' בי\"ע, ולכן איננו מלא<sup data-n=\"1271\">8</sup>.\nלט)<b>]</b> והענין הוא דהנה ים וארץ למעלה<sup data-n=\"1272\">9</sup> הוא בחי' עלמא דאתכסיא ועלמא דאתגליא, והוא עד\"מ ים וארץ למטה דכל מה שיש ביבשה יש בים, אלא שביבשה הוא באתגליא שכל הנבראים נראים ונגלים, משא\"כ בים הם באתכסי' להיותם מובלעים ומכוסים במי הים המכסה עליהם<sup data-n=\"1273\">10</sup>. וכמו\"כ בבחי' מל' דאצי' נק' ארץ ונק' ג\"כ ים, והיינו כי בחי' הארת והמשכת המל' דאצי' שנמשכת ומתלבשת בבי\"ע להחיות העולמות מאין ליש שהם בחי' עלמין דאתגליין שנראין ליש ודבר נפרד בפ\"ע הנה בחי' זו נק' בשם ארץ, ועז\"נ תדשא הארץ דשא כמ\"ש בזהר בכ\"ד, וכמ\"ש באגה\"ק ד\"ה איהו וחיוהי<sup data-n=\"1274\">11</sup> שעיקר התהוות היש ודבר נפרד לגמרי הוא ממל' דאצי' שנעשה עתיק דבריאה כי אין מלך בלא עם, משא\"כ מבחי' המדות עצמם דאצי' יעו\"ש. והנה המל' מקבלת האור והשפע מאוא\"ס ב\"ה ע\"י המדות דאצי'",[["1268","5","<b>אמרו בזהר ויחי. . ויהיב בהאי גיסא</b>: בדפוסי הזהר שלפנינו: ויהיב בגיסא אחרא."],["1269","6","<b>וא\"כ פי' כל הנחלים. . שהמל' מקבלת מכל הע\"ס</b>: באוה\"ת נ\"ך שם מביא זה בשם ביאור ע\"פ ששת ימים תאכל מצות דתק\"ע\" (מאמרי אדה\"ז תק\"ע שם)."],["1270","7","<b>יחוד שמשא וסיהרא בכל ר\"ח הגם כי כבר נעשה. . בר\"ה. . כמ\"ש מזה במ\"א</b>: ראה לקמן ד\"ה ויאמר גו' מחר חודש, וש\"נ. וראה גם סה\"מ תרל\"ג ח\"א ע' רמ. רמח. ד\"ה ויאמר גו' מחר חודש (דש\"פ שמיני) תשמ\"ה."],["1271","8","<b>שמקבל מע\"ס דאצי' ומשפיע לבחי' בי\"ע ולכן איננו מלא</b>: ראה אוה\"ת נ\"ך שם ע' א'קה (בשם הרמ\"ז)."],["1272","9","<b>והענין הוא דהנה ים וארץ למעלה</b>: בהבא לקמן בפיסקא זו ראה ד\"ה ששת ימים בלקו\"ת צו יד, ב [והוא לשון הלקו\"ת בשינויים הובא לקמן ובאוה\"ת בשלח שם]. וראה בכל הבא לקמן (עד פיסקא: ולפ\"ז יתורץ) אוה\"ת בשלח שם ע' תקסח ואילך."],["1273","10","<b>ומכוסים במי הים המכסה עליהם</b>: בלקו\"ת צו שם נוסף כאן: וע' בפ' בשלח בד\"ה אז ישיר [תו\"א בשלח סב, ב]."],["1274","11","<b>וכמ\"ש באגה\"ק ד\"ה איהו וחיוהי</b>: סי' כ (קל, ב)."]]],[2000510394,"וממנה דוקא נמשך אח\"כ בבי\"ע, כי בחי' אוא\"ס שמאיר בבחי' המדות עליונות דאצי' א\"א שיבואו בבחי' הגילוי תחלה בבי\"ע אם לא ע\"י המל' כנ\"ל, כי באצי' איהו וחיוהי חד ואיהו וגרמוהי חד, שהחסד דאצי' הוא בבחי' א\"ס ממש, ואין ערך כלל בחי' חסד דבריאה שהוא בחי' גבול מחנה מיכאל באהבה לקבל ההשפעה בהשתלשלו' מבחי' חסד דאצי' שבלי גבול, וכמ\"ש באגה\"ק בענין ואנכי עפר ואפר וכמשי\"ת<sup data-n=\"1275\">12</sup> אי\"ה, אם לא ע\"י שמתעלם תחלה אור החסד זה בבחי' מל' וממנה יורד אח\"כ השפע בבי\"ע, כי מדת מל' הוא רוממות והתנשאות, וכמ\"ש המתנשא מימות עולם, ודרך כלל ההתנשאות הוא בחי' הסתלקות<sup data-n=\"e65\">ח</sup> שלא ירד החיות עליהם כ\"כ, ולכן נק' בחי' מל' ים להיות כמו שהים מעלים ומכסה על הנבראים שבתוכו כן בחי' המל' מעלמת ומכסה על בחי' המדות דאצי' שמאירים בתוכה<sup data-n=\"1276\">13</sup>.\n[מ)] <b>ויובן</b> דבר זה מהארת האור שמאיר מהלבנה<sup data-n=\"1277\">14</sup> שידוע שסיהרא לית לה מגרמה כלום, והיא בעצם חשוך, רק מה שמקבלת מהשמש, והנה אנו רואים שהארתה שהיא מארת אח\"כ אינו דומה כלל וכלל להארת השמש שמבהיק ומאיר, עד שלא יתכן כלל וכלל לאמר שזהו הפרשת הארה מאור השמש, אלא שע\"י קבלתה היא משנית את האור לגמרי להיות מהות אור אחר ממש, דאם הי' מאיר הארה זו עצמה שמקבלת מהשמש הי' עצם האור שוה לאור השמש רק שהי' במיעוט, וכמו במים עד\"מ טפה נגד הים ה\"ה הפרשת חלק קטן מאד ועכ\"ז ה\"ה מהות המים כמו המים שבים ונהר, ואם יבלע בספוג עד\"מ או בלבד המים היוצאי' מהם אח\"כ ע\"י שסופגי' אותו הנה הוא מהות המים שנבלעו בתוכו, והיינו מפני שהספוג או הלבד אינו משנה מהות המים כלל, להיות כי המים מכונסים בהם כמו בכלי ממש ולא בדרך הלבשה והתעלמות כלל, פי' שההעלם בהם הוא ע\"ד כיסוי הכלי המכסה על המים, אבל לא כן העלם בחי' אור הלבנה על אור החמה שמפני שמעלמת ע\"ד התלבשות שאור החמה מתלבשת בלבנה ע\"ד משפיע ומקבל ה\"ה משנה את האור לגמרי עד שנעשה או\"ח ממש.",[["1275","12","<b>וכמ\"ש באגה\"ק בענין ואנכי עפר ואפר וכמשי\"ת</b>: סי' טו (קכא, סע\"א ואילך). נעתק לקמן בפנים בהמשך המאמר."],["1276","13","<b>המל' מעלמת ומכסה על בחי' המדות דאצי' שמאירים בתוכה</b>: בלקו\"ת צו שם נוסף כאן: ועמ\"ש מענין והים עליהם מלמעלה בפ' בלק ע\"פ מי מנה עפר יעקב [לקו\"ת בלק סח, רע\"א. סח, ג]."],["1277","14","<b>ויובן דבר זה מהארת האור שמאיר מהלבנה</b>: בהבא לקמן בפיסקא זו (בענין מעבר והתלבשות) ראה בארוכה מאמרי אדהאמ\"צ קונטרסים ע' תקלג ואילך. אוה\"ת שמיני (כרך ב) ע' תסב ואילך. סה\"מ תר\"ל ע' סג. תרל\"ב ח\"א ע' קמח ואילך. וש\"נ. ח\"ב ע' שעד-ה. [ובהנסמן שם בתחילת המאמר].\n\n<b>ח</b>  <b>מדת מל'. . הוא בחי' הסתלקות</b>: בשולי הגליון נרשם בגוכי\"ק: כמו ביחוד זו\"נ כן בבנין המל', דאל\"כ מהו ענין בנינה, יומשך ממל' דחסד, וכן בכל ענין השפעה המל' בחי' הסתלקות ועי\"ז יומשך."]]],[2000510395,"<b>וכן</b> יובן בענין בחי' המל' שמעלמת על אור המדות שבתוכה עד שהיא משנית את האור המאיר ממנה אח\"כ, עד שהיא יכולה להעשות מקור לנבראי' דבי\"ע, שבחי' זו במל' נק' בשם ארץ, והרי הונח שם אחר על בחי' זו להיות כי אור זה משונה מאור קבלתה כו', וכ\"ז הוא ע\"י שמעלמת האור שמקבלת מהמדות בעצמה ומכסה אותו, ולא ע\"ד הכיסוי בכלים שאינו מכוסה רק בעת היות הדבר בהכלי, אבל אח\"כ הרי נמשך ממנה מהות הראשון ממש בלי שום שינוי כו', לא כן המל' משנית אור המדות מפני שמתעלם בה אור המדות, ובד\"כ זהו ההפרש בין מעבר להתלבשות כו'. ועש\"ז נק' ים להיותה מכסה כו'. ונמצא כי ים גורם שיהי' מציאות ארץ, ואם לא הים לא הי' יכול להיות מציאות הארץ, היינו אם לא העלם המל' הנק' עש\"ז ים ע\"ש שמעלמת, הנה עי\"ז יכולה לשנות אור המדות להשפיע אח\"כ בנבראים שבחי' זו נק' בשם ארץ כו'. וגם מעצם הענין מובן שלכן בי\"ע מקבלים ע\"י בחי' המל' דוקא, להיות כי המל' מכסה על אור המדות ומשנית אותו, דאל\"כ מדוע לא יתהוה מהמדות עצמם בי\"ע, ונת' לעיל הטעם שחסד דבריאה אינו בערך לחסד דאצי' כו', ואם בחי' המל' אינה משנה האור מה יועיל זה שנמשך ע\"י בחי' המל', כמו שלא יועיל לשנות המים בהיותם נשפכים דרך כמה כלים והיינו להיותו דרך מעבר, לא כן דרך המל' שמתעלמת בתוכה בחי' ים הרי עי\"ז אח\"כ יכולה להיות בחי' ארץ מקור לבי\"ע כו'.\n<b></b>[מא)] אך עדיין צ\"ל מאחר שבחי' המל' משנה וכנ\"ל, מדוע לא יומשך התהוות העולם מבחי' המל' של המדות עצמם, כמו שנת' בספי' מדת המל' עצמה בחי' העליונה שבה הוא הנק' ים ע\"ש ההעלם, כן צ\"ל בבחי' המל' של כל מדה שזהו ג\"כ בחי' העלם כענין ההעלם דים ממש, וכידוע דכל משפיע מוכרח להתצמצם ולהתעלם עדי יוכל להשפיע לזולתו, שלכן צריכים לנו\"ה שהם כליות יועצות<sup data-n=\"e66\">ט</sup> איך להשפיע, כי הלא א\"א שישפיע הרב לתלמידו עצם ההשפעה כמו שהיא אצלו ממש כ\"א ע\"י צמצום והעלם כנ\"ל, שלזה צריך לייעץ בעצמו איך להשפיע, ולפ\"ז הי' יכול להיות התהוות הנבראים מבחי' המל' של המדות עצמם, ולמה הי' צריך להתעלם בבחי' מל' דוקא. ואם מפני שלא די בבחי' המל' של המדות עצמם כ\"א לאחר שיתעלמו עוד שנית במדת המל', הלא גם במדות עצמם יש התכללות יו\"ד מיו\"ד, ונמצא כי עד\"מ ממל' שבמל' דחסד הי' יכול להיות בריאת עולמות בי\"ע. אלא שצ\"ל שאינו דומה בחי' ההתכללות במדות שגם בחי' המל' שבהם הוא בחי' ההעלם על בחי' ההשתלשלו' עו\"ע, לא כן העלם דמל' שנק' ים שהיא סופא דכל דרגין דהשתלשלו' האצי', ולכן ההעלם הוא בכדי להיות ארץ שהוא מקור דהתהוות בי\"ע",[["e66","ט","<b>דכל משפיע. . צריכים לנו\"ה שהם כליות יועצות</b>: בשולי הגליון נרשם בגוכי\"ק: העלם וכמו כל השפעה לזולתו, עד שצ\"ל כליות יועצות, ואם צ\"ל מהעלם עוד העלם די בהתכללות יו\"ד מיו\"ד שבז\"א. אך י\"ל שמאחר שכל מדת המל' היא העלם אינו דומה למל' שבז\"א."]]],[2000510396,"יש מאין, ואם הי' מבחי' המל' [דמדות] דאצי' הי' הכל ע\"ד השתלשלו' ולא הי' מציאות הגשמי, וכנ\"ל שהתהוות הגשמי' מן הרוחניות אין לך בריאה יש מאין גדול מזה, וכדי להיות בריאה יש מאין זהו ע\"י העלם בחי' ים שבמל' דוקא, ומה גם כי כל מדת המל' היא מדת ההתנשאות בעצם כו', ונבנה מהתנשאות שבמדות כו'.\n<b>היוצא</b> מזה שים וארץ שניהם במל', רק שהים הוא בחי' עליונה שבמל' המעלמת אור המדות דאצי', והוא הסיבה שיוכל להיות בחי' ארץ שהוא בחי' המל' שנעשה מקור ושרש לבחי' התהוות בי\"ע כו'.\n<b>ובמ\"א</b> ביאר אאמו\"ר זצ\"ל שים ויבשה הוא בחי' חיות המלאכים<sup data-n=\"1278\">15</sup> שנק' בשם נוני דימא רבה, וחיות הנבראים דבי\"ע, ע' בבה\"ז בשלח בד\"ה עוי\"ל<sup data-n=\"1279\">16</sup> מאמר הנ\"ל באו\"א, אך לפמשנת\"ל בחי' ים הוא בחי' התחתונה שבאצי' שזהו\"ע ים בחי' סופא דכל דרגין, וקרובין הדברים כמשנת\"ל שהרי בלק\"ת בד\"ה שה\"ש<sup data-n=\"1280\">17</sup> פי' שים הוא בחי' שכינתא עילאה כמו הבינה והוא בחי' כלת משה שנת' במ\"א<sup data-n=\"1281\">18</sup>, וע' בלק\"ת בד\"ה ששת ימים הראשון פ\"ה<sup data-n=\"1282\">19</sup>.\n<b></b>[מב)] אמנם הנה כ\"ז הוא כשנמשך כסדר ההשתלשלו', אז הוא ההמשכה כסדר ההשתל' ים ויבשה עלמא דאתכסיא ועלמא דאתגליא, וכמשנ\"ת שבכדי להיות בחי' ארץ שהיא מקור לנבראים בע\"ג דבי\"ע זהו ע\"י שמתעלם תחלה בבחי' מל' הנק' ים סופא דכל דרגין, ולולא ההעלם לא הי' יכול להיות גילוי, וכמו כאשר כבר נתהוה נא' ג\"כ ויהי ערב ויהי בקר, ערב תחלה, שארז\"ל כברייתו של עולם ברישא חשוכא והדר נהורא, כ\"ש במקור שיוכל להיות התהוות בחי' ארץ צ\"ל העלם תחלה, וי\"ל שמפני שבמקור בחי' התהוות הארץ הי' ע\"י העלם הים תחלה כמשנת\"ל, לכן גם אח\"כ כשנתהוה מבחי' הנק' ארץ סדר ההשתל' נעשה ג\"כ בחי' חשוכא ברישא והדר נהורא. אך בשש\"פ בעת קרי\"ס האיר בחי' אוא\"ס שלמעלה מהשתל' לגמרי שלגבי' אצי' ועשי' שוים ממש, וכחשיכה כאורה בשני כפי\"ן<sup data-n=\"1283\">20</sup> שגם האור שוה לחושך ולילה כיום יאיר, אז נתגלה העלם הים להיות יבשה, ולא די בהגילוי לבד כ\"א עד שבנ\"י הלכו ביבשה בתוך הים שנתגלה להם כנ\"ל בבחי' הרגשה וגילוי בנפשותם עד שברגלם הלכו ביבשה בתוך הים כו', והיינו ג\"כ כנ\"ל",[["1278","15","<b>ובמ\"א ביאר אאמו\"ר זצ\"ל שים ויבשה הוא בחי' חיות המלאכים</b>: ביאוה\"ז להצ\"צ (כרך א) ע' רח."],["1279","16","<b>ע' בבה\"ז בשלח בד\"ה עוי\"ל</b>: ביאוה\"ז לאדהאמ\"צ מב, ג."],["1280","17","<b>בלק\"ת בד\"ה שה\"ש</b>: כ\"ה גם באוה\"ת בשלח שם ע' תקסט: המל' כמו שהיא באצי' נק' שכינתא עילאה כמו הבינה כמ\"ש בד\"ה שה\"ש ספ\"א. וראה לקו\"ת שה\"ש א, ב. [וראה סה\"מ תרל\"ב ח\"ב ע' תקא. ס\"ע תקיג-ד]."],["1281","18","<b>בחי' כלת משה שנת' במ\"א</b>: ראה לקו\"ת שה\"ש לט, רע\"ד. ובכ\"מ."],["1282","19","<b>וע' בלק\"ת בד\"ה ששת ימים הראשון פ\"ה</b>: לקו\"ת צו יד, ב [הובא לעיל בפנים]."],["1283","20","<b>וכחשיכה כאורה בשני כפי\"ן</b>: ראה לקו\"ת צו יב, א [ובהמ\"מ שם בהוצאת תשנ\"ו ואילך]. אוה\"ת ויקרא (כרך ג) ע' תשלג."]]],[2000510397,"שלפי שהאיר מאוא\"ס שלמעלה מהשתלשלו' לכן גם למטה הי' גילוי כלליות בחי' ההעלם. וזה הי' ע\"י שהוליך ה' ברוח קדים עזה, פי' רוח קדים היינו מבחי' קדמונו של עולם שלמעלה מגדר עלמין כלל<sup data-n=\"e67\">י</sup> שעש\"ז אנו מכנים לקרוא בחי' זו בשם קדמונו ש\"ע, שבכ\"מ שנא' עולם בחי' זו הוא קדמונו, ועי\"ז נעשה קרי\"ס, פי' ים סוף הוא מה שהוא סוף כל דרגין דאצי' היינו בחי' מל' שמקבלת מבחי' ים החכ' דאצי', שהחכ' היא ראשית הגילוי, ובכלל אצי' היא בחי' חכ' כי אבא מקננא באצי' (וע' במ\"א בהפרש המדריגות אצי' עצמו, ואבא מקננא באצי', ואצי' חכ'<sup data-n=\"1284\">21</sup>, ואכמ\"ל בזה. וע' ג\"כ בביאור לד\"ה וכל העם רואים בענין קול שופר ובענין ב' שמות דמ\"ץ פ\"ץ<sup data-n=\"1285\">22</sup>), וים סוף הוא סוף מדרגות האצי', שאצי' הוא מעולמות הא\"ס, וע\"י בחי' רוח קדים הנ\"ל נתגלה העלם הכללי לידי גילוי גמור בסוף כל המדריגות, שהרי גם שפחה שהיא בחי' ומדריגת העשי'<sup data-n=\"1286\">23</sup> כמ\"ש במ\"א (וע' ג\"כ בד\"ה וכי ימכור איש את בתו לאמה) ראתה ג\"כ על הים מה שלא ראה יחזקאל, ע' במכילתא פ' בשלח ע\"פ זה אלי.\n<b></b>[מג)] ובכ\"ז יובן ענין מ\"ש כל הנחלים הולכים אל הים, שפי' ים הוא בחי' המל' סודכ\"ד דאצי', והנחלים הוא בחי' המל' של כל המדות שהם הולכי' אל הים, שבנין המל' הוא מהמל' שבע\"ס, ומ\"מ הים איננו מלא להיותו משפיע בבי\"ע אח\"כ ע\"י בחי' המל' שנק' בשם ארץ. וז\"ש בזהר נקיט מהאי גיסא ויהיב בהאי גיסא, ר\"ל שמקבל מאצי' ומשפיע לבי\"ע, והיינו שהמל' הוא בחי' ממוצע והוא משפיע וגם מקבל. וזהו הוי זנב לאריות ואל תהי ראש לשועלים, פי' זנב לאריות הוא בחי' המל' שנק' בשם ים, ה\"ה זנב לאריות ע\"ס דאצי' שנק' אריות החכ' שמאיר באצי', שהחכ'",[["1284","21","<b>(וע' במ\"א בהפרש המדריגות אצי' עצמו ואבא מקננא באצי' ואצי' חכ'</b>: ראה אוה\"ת וארא ע' קנ ואילך. ויקרא (כרך ג) ע' תשלא ואילך. בלק ע' תתקפ. ביאוה\"ז להצ\"צ (כרך א) ע' סד. שם (כרך ב) ע' תתקסג-ד."],["1285","22","<b>בביאור לד\"ה וכל העם. . ב' שמות דמ\"ץ פ\"ץ</b>: אוה\"ת יתרו ע' א'ב ואילך. וראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרלח ואילך. אוה\"ת יתרו שם ע' תתקצז ואילך."],["1286","23","<b>שפחה שהיא בחי' ומדריגת העשי' כמ\"ש במ\"א. ֿ. בד\"ה וכי ימכור איש את בתו</b>: ראה תו\"ח שמות (כת\"י הר\"ש סופר) עא, ב ואילך. [ובהוצאת תשס\"ד בח\"ב רצג, א ואילך]. אוה\"ת משפטים ע' א'קכז ואילך. [ושם ע' א'קמ: עבד כנעני בעשי', ועבד עברי ביצירה, ואמה העברי' בבריאה. וראה תו\"א יתרו עב, ד: עבדים הם מט\"ט וסנד\"ל שביצי' ועשי', ושפחה היא בחי' בריאה].\n\n<b>י</b>  <b>קדמונו של עולם שלמעלה מגדר עלמין כלל</b>: בשולי הגליון נרשם בגוכי\"ק: לפמש\"נ בפי' קדמונו של עולם, צ\"ע לשון ים הקדמוני חכ', אך י\"ל קודם לבחי' ים סוף, וזהו בהכרח שהרי ממל' דחכ' נעשה חכ' שבמל' וכנ\"ל באורך. גם י\"ל ים הקדמוני ה\"ה שם המושאל. גם י\"ל מילה מורכבת דמיון לבחי' קדמוני, כמו שהקדמוני קדי' כן זה קדי', כי אצי' הפרשת הארה והוא וחכמתו אחד כמ\"ש הרמב\"ם, וע\"ד אדם אדמה לעליון, ע' בהוספות לת\"א במג\"א<sup data-n=\"1639\">187</sup>."],["1639","187","<b>ע' בהוספות לת\"א במג\"א</b>: ראה גם תו\"א מג\"א צח, ב (אודות משל הקדמוני)."]]],[2000510398,"הוא בחי' ארי' כמשנת\"ל בענין המשלים וירא ראשית לו<sup data-n=\"1287\">24</sup>, ראשית חכ', וירא הוא ראי' אותיות ארי', ופי' ראש לשועלים היינו בחי' המל' שנק' בשם ארץ שהיא ראש לבי\"ע, ואמרו הוי זנב לאריות ואל תהי ראש לשועלים, הוא כי הבחי' עליונה שבמל' היא יותר גבוה ונעלה מבחי' המל' שנק' ארץ שנעשה ראש לשועלים, וע' בבה\"ז בלק במאמר שחורה אני<sup data-n=\"1288\">25</sup> שזהו ההפרש בין אחור באחור לפנים בפנים ושם ביאר שאין ערוך ביניהם, והיינו כי כדי שיומשך השפע מאצי' לבי\"ע א\"א כ\"א ע\"י ממוצע דוקא, להיות כי אצי' הוא גילוי ההעלם מאלקות, ובי\"ע הם בריאה יש מאין שאין ערוך לך כתי' שהריחוק גדול ביניהם כ\"כ עד שאין ערוך לך, לכן בכדי שיומשך ההשפעה מאצי' לבי\"ע זהו ע\"י ממוצע דוקא, וזהו בחי' המל' שהיא ממוצע בין אצי' לבי\"ע כו'. והנה נודע כי הממוצע צ\"ל כלול מב' הבחי' דוקא, דאל\"כ האיך יחבר שניהם, ע\"כ צ\"ל שיש בו מבחי' התחתונה שבעליון ומבחי' העליונה שבתחתון, וזהו ב' בחי' שבמל', בחי' ים הוא מה שהוא דומה קצת לבחי' אצי' שהרי זהו מה שהוא סוף כל דרגין דאצי' כו', ובחי' ארץ הוא דומה קצת להנבראים דבי\"ע שהרי זהו בחי' המהוה אותם, וזהו ב' הבחי' שבממוצע כו'.\n<b></b>[מד)] וביאור הענין הוא כמשנת\"ל שבכדי שיתהוה בחי' בריאה יש מאין, עד\"מ מחנה מיכאל דבריאה באהבה מבחי' החסד דאצי', א\"א כ\"א ע\"י ממוצע ביניהם מחמת ריחוק הערך שביניהם, וכמ\"ש באברהם ואנכי עפר ואפר ונת' מזה באגה\"ק סי' ט\"ו מה ששמע ממורו<sup data-n=\"1289\">26</sup> ע\"פ ואנכי עפר ואפר שאמר אברהם אבינו ע\"ה על הארת נשמתו המאירה בגופו מאור חסד עליון, והיא מדתו מדת אהבה רבה של אאע\"ה שהי' אוהב להקב\"ה<sup data-n=\"1290\">27</sup> אהבה גדולה ועליונה כ\"כ עד שנעשה מרכבה להקב\"ה, וסד\"א שבחי' חסד ואהבה שלמעלה בספירות<sup data-n=\"1291\">28</sup> היא מעין וסוג מדת אהבה רבה של אאע\"ה רק שהיא גדולה ונפלאה ממנה למעלה מעלה עד אין קץ ותכלית, כנודע ממדות עליונות שאין להם סוף ותכלית מצד עצמן כי אוא\"ס ב\"ה מאיר ומתלבש בתוכן ממש ואיהו וגרמוהי חד, משא\"כ בנשמת האדם המלובש בחומר<sup data-n=\"1292\">29</sup> שיש למדותיה קץ וגבול, אבל מ\"מ סד\"א שמדותיה הם מעין וסוג מדות עליונות, ולזה אמר ואנכי עפר ואפר דכמו שהאפר הוא מהות עצמותו של העץ הנשרף שהוא מורכב מד\"י ארמ\"ע, וג\"י אמ\"ר חלפו וכלו בעשן המתהוה מהרכבתן כנודע, ויסוד הד' שהי' בעץ שהוא העפר שבו היורד למטה ואין האש שולטת בו הוא הנשאר קיים והוא האפר, והנה כל מהות העץ וממשו וחומרו וצורתו באורך ורוחב ועובי שהי'",[["1287","24","<b>כמשנת\"ל בענין המשלים וירא ראשית לו</b>: לעיל ד\"ה ואתה הרם את מטך."],["1288","25","<b>בבה\"ז בלק במאמר שחורה אני</b>: ביאוה\"ז לאדהאמ\"צ ק, ד."],["1289","26","<b>באגה\"ק סי' ט\"ו מה ששמע ממורו</b>: דף קכא, סע\"א ואילך. והבא לקמן (עד התיבות: במשל ומליצה) הוא לשון האגה\"ק שם בשינויים. וראה בכ\"ז סה\"מ תר\"ל ע' נו-ז. וראה גם ליקוט פירושים ומ\"מ (להר\"א שי' חיטריק) לאגה\"ק שם."],["1290","27","<b>אוהב להקב\"ה</b>: באגה\"ק דפוס וילנא תר\"ס ואילך: אוהב את הקב\"ה."],["1291","28","<b>בספירות</b>: באגה\"ק שם: בספירות העליונות."],["1292","29","<b>המלובש בחומר</b>: באגה\"ק שם: המלובשת בחומר."]]],[2000510399,"נראה לעין קודם שנשרף, עיקרו הי' מיסוד העפר שבו רק שאמ\"ר כלולים בו, כי העפר הוא חומרי יותר מכולם ויש לו אורך ורוחב ועובי, משא\"כ באש ורוח ומים הם מעט מזעיר בעץ, וכל ארכו ורחבו ועוביו הכל הי' מן העפר והכל שב אל העפר שהוא האפר הנשאר אחרי שנפרדו ממנו אמ\"ר ועובי. והנה כמו שהאפר אין לו דמיון וערך אל מהות העץ הגדול באורך ורוחב ועובי קודם שנשרף לא בכמותו ולא באיכותו אף שהוא מהותו ועצמותו וממנו נתהוה, כך אמר אברהם אע\"ה על מדתו מדת החסד והאהבה המאירה בו ומלובשת בגופו דאף שהיא היא מדת אהבה וחסד עליון שבאצי' המאיר בנשמתו שהיתה מרכבה עליונה, אעפ\"כ בירידתה למטה להתלבש בגופו ע\"י השתלשלו' העולמות ממדריגה למדרגה ע\"י צמצומי' רבים אין דמיון וערך מהות אור האהבה המאיר בו אל מהות אור אהבה וחסד עליון שבאצי' אלא כערך ודמיון מהות העפר הנעשה אפר אל מהותו ואיכותו כשהי' עץ נחמד למראה וטוב למאכל עד\"מ, ויותר מזה להבדיל באלפים הבדלות רק שדיברה תורה כלשון בני אדם במשל ומליצה. והנה נודע שהנשמות גבוהים מהמלאכי' (וכ\"ש האבות שהיו נשמות דאצי'), שהנשמות הם מבחי' פנימיות הכלים והמלאכים מחיצוניות הכלים, ומה לנשמת אברהם אמר על עצמו שהוא בחי' עפר ואפר כ\"ש על מיכאל דבריאה שהוא נברא ובע\"ג מבחי' חיצוני' הכלים. ולכן כדי שיהי' התהוות המלאכי' ואפי' נשמות זהו ע\"י בחי' ממוצע והוא בחי' מל' דאצי'.\n<b>וענין</b> הממוצע הוא שההשפעה מתעלמת בו תחלה ואח\"כ בא להמקבל, וכענין המתורגמן<sup data-n=\"1293\">30</sup> שהי' שומע הדרשה מפי הרב שמתעלם בו ואח\"כ משמיע קולו לרבים, או משה קיבל תורה מסיני, וב' בחי' שבממוצע הי' משה ואהרן<sup data-n=\"1294\">31</sup> ביציאת מצרים. וכמו בדצח\"מ יש ממוצע בין כל מין<sup data-n=\"1295\">32</sup>, שהממוצע בין דומם לצומח הוא עצי אלמוגים שהם בעצם אבן ועכ\"ז הם צומחין, וכן בין צומח לחי ממוצע שיש עוף שצומח מן האילן כמבואר בש\"ע<sup data-n=\"1296\">33</sup>, וכן בין חי למדבר יש ממוצע והוא הקוף, או י\"ל אדני השדה, שהרי ר' יוסי סובר שמטמא כאדם בפ\"ח דכלאים מ\"ה. ובין כלליות דצח\"מ שבעשי' ליצי' הממוצע הוא בחי' כתר דעשי', ולכן נק' הג\"ע תחלת מעשיך כמ\"ש בלק\"ת בד\"ה ביום השמע\"צ<sup data-n=\"1297\">34</sup>, והמל' דאצי' היא ממוצע בין בי\"ע לאצי'. וכמו\"כ אצי' הוא ממוצע בין אוא\"ס המאציל לבי\"ע<sup data-n=\"1298\">35</sup> שכדי להיות התהוות בי\"ע בחי' בע\"ג מאוא\"ס הבלתי בע\"ג צ\"ל ממוצע, והממוצע הוא אצי' בכלל, וב' בחי' שבממוצע זהו בחי' י\"ה ובחי' ו\"ה, שזהו מ\"ש הנסתרות להוי' אלקינו שזהו בחי' העליונה",[["1293","30","<b>וענין הממוצע. . וכענין המתורגמן</b>: בהבא לקמן ראה בארוכה סה\"מ תרנ\"ט ע' קצ ואילך."],["1294","31","<b>וב' בחי' שבממוצע הי' משה ואהרן</b>: ראה ביאוה\"ז לאדהאמ\"צ קמב, ג. ולהצ\"צ (כרך א) ע' תמא."],["1295","32","<b>בדצח\"מ יש ממוצע בין כל מין</b>: ראה גם סה\"מ תרנ\"ט שם."],["1296","33","<b>כמבואר בש\"ע</b>: בסה\"מ תרל\"ב (ובעוד מקומות שנסמנו לעיל בתחילת המאמר) מציין ע\"ז: כמבואר ביו\"ד סי' פ\"ד סט\"ו."],["1297","34","<b>בלק\"ת בד\"ה ביום השמע\"צ</b>: דרושים לשמע\"צ פד, ד."],["1298","35","<b>אצי'. . ממוצע בין אוא\"ס המאציל לבי\"ע</b>: ראה תו\"א מג\"א צג, א. ועוד."]]],[2000510400,"שבממוצע, כי השראת אוא\"ס ב\"ה הוא בחכ' ונק' ים החכמה והוא בחי' ים הקדמוני<sup data-n=\"e68\">יא</sup>, והיינו שבו שורה ומתלבש בחי' קדמוני כו', והנגלות לנו ולבנינו זהו בחי' ו\"ה שרש ומקור לבי\"ע כי אמרתי עולם חסד יבנה, וכתי' זכור רחמיך וחסדיך כי מעולם המה כו' וכמש\"נ לעיל בענין ההפרש בין מוחין למדות<sup data-n=\"1299\">36</sup> בענין המשלי' דארי' הנ\"ל.\n<b></b>[מה)] ולפ\"ז יתורץ למה נאמר נחלים<sup data-n=\"1300\">37</sup> ולא נהרות, הגם שהנחלים הם קטנים מנהרות כמ\"ש הג\"פ שהובא לעיל, מ\"מ באשר תיבת הים קאי על הים הקדמוני, שלגבי' הנהרות דמדות דז\"א הם קטנים וכמובן מענין המשלים הנ\"ל שהם רק כמו משל לגבי הנמשל לגבי בחי' ים החכמה, ולכן נא' לשון נחלים. והענין דהנה ים הקדמוני רומז על בחי' החכמה ע\"ש שבו שורה בחי' קדמוני כו', להיות כי השראת אוא\"ס הוא בחכ' כו' כנ\"ל, וים סוף הוא בחי' המל' סופא דכל דרגין כנ\"ל, וים סתם כולל שניהם כי איננו דבוק לתיבה שלאחריו כמו ים הקדמוני שתיבת ים דבוק לתיבת קדמוני ואז מורה על ים פרטי, אמנם תיבת ים סתם כולל כל הבחי' ים, ולכן באשר שבל' הפסוק נא' סתם אל הים ולא פרט איזהו, לכן אמר ל' נחלים שמורה על נהר קטן, מהיות כי נגד החכמה המדות הם קטנים כנ\"ל. וגם לפי פי' המכלול שעושה כעין פשר שמקום אשר המים נגרים בו יקרא נחל גם כשאין שם מים, מ\"מ ניחא שגם כשעוברים שם מים נקרא ג\"כ נחל, וכמ\"ש הג\"פ שבלשון בני אדם נהר קטן יקרא נחל, מ\"מ גם בנהר קטן יש שם מים, וכ\"ש לפי מ\"ש שבאמת אין אנו צריכים כלל לפי' בישוב דברי הת\"י ורש\"י<sup data-n=\"1301\">38</sup>, וכ' זה רק ליישב פי' בעצמו, וע\"ד העבודה יובן ענין הנ\"ל שכל הנחלים הולכים אל הים. ובזה יתורץ ג\"כ מהו שייך ענין כל הנחלים הולכים אל הים לפי מה שפי' שי\"ה נק' ים, וע' בת\"א בד\"ה וה' הולך לפניהם<sup data-n=\"1302\">39</sup>, שלכאו' יפלא מהו שייך ענין הנחלים שפי' על מדות שילכו אל הים היא החכמה, דאילו לפי' ים שקאי על בחי' מל' ניחא כנ\"ל, אבל לפי' ים שקאי על החכ' לכאו' אינו מובן כלל ענין מה שהולכים הנחלים אל הים.\n<b></b>[מו)] אך הענין הוא דהנה כתי' וצדקה כנחל איתן, פי' איתן הוא מל' והאיתנים מוסדי ארץ<sup data-n=\"1303\">40</sup>, איתנים אותיות תנאים שהם מוסדי ארץ בחי' תושבע\"פ, שנק'",[["1299","36","<b>וכמש\"נ לעיל בענין ההפרש בין מוחין למדות</b>: ד\"ה ואתה הרם את מטך. וש\"נ."],["1300","37","<b>ולפ\"ז יתורץ למה נאמר נחלים</b>: בהבא לקמן עד סוף המאמר ראה אוה\"ת נ\"ך שם ע' א'קג-ד."],["1301","38","<b>לפי פי' המכלול שעושה כעין פשר. . דברי הת\"י ורש\"י</b>: הובא לעיל רד\"ה והחרים."],["1302","39","<b>בת\"א בד\"ה וה' הולך לפניהם</b>: פ' בשלח סה, סע\"א."],["1303","40","<b>אך הענין הוא. . וצדקה כנחל איתן. . והאיתנים מוסדי ארץ</b>: בהבא לקמן בפיסקא זו ראה תו\"א שמות מט, סע\"ב [הובא באוה\"ת נ\"ך שם].\n\n<b>יא</b>  <b>]]*ים הקדמוני. . בחי' החכ'. . וים סוף. . בחי' המל'</b>: בשולי הגליון נרשם בגוכי\"ק: ים סוף מל' סופא דכל דרגין, ים הקדמוני חכ', ים סתם סובל שניהם, לכן נאמר הים סתם. שהנחלים הם מלמעלמ\"ט לים דמל', ומלמטלמ\"ע בים דחכ', אשר בזה יתורץ שלכן נאמר נחל כי לגבי החכ' נחל הם ולא נהר."]]],[2000510401,"ארץ ה\"א אחרונה בחי' מל', והתנאים הם המייסדים אותה כו', וזה\"ע נחל איתן, ונק' איתן ע\"ש משכיל לאיתן מלשון איתן מושבך, ובחי' זו באה בבחי' נחל כמ\"ש בלק\"ת בד\"ה ראה אנכי נותן<sup data-n=\"1304\">41</sup>, וזהו ג\"כ בחי' התנאים שהיו סמוכין איש מפי איש מפי משה בחי' מ\"ה דחכ' כו', שזהו בחי' איתן, ע' בלק\"ת בד\"ה ראה הנ\"ל ובהגהות לשם בספר תרך\"ב<sup data-n=\"1305\">42</sup>, שז\"ע בחי' שם ע\"ב. ונמצא שז\"ע מ\"ש כל הנחלים הולכים אל הים, ים הוא בחי' מל' תושבע\"פ הוא בחי' סופא דכל דרגין שמקבלת מאצי' ז\"ע התנאים שהיו סמוכין איש מפי איש עד משה בחי' נחל איתן כו'.\n<b>אמנם</b> לפי' הים הוא בחי' חכ' דאצי' ים הקדמוני, מה\"ע הנחלים שהולכים אל הים, צ\"ל שזהו ע\"ד לך הוי' הגדולה ביטול המדות לבחי' לאו מכל אינון מדות, כמשנ\"ת מזה באורך בד\"ה א\"ר יוסי יהא חלקי<sup data-n=\"1306\">43</sup> מגומרי הלל בכ\"י, והוא בבחי' חכ' כי השראת אוא\"ס הוא בחכ' שלכן נק' אחד האמת כמ\"ש בסש\"ב פל\"ה בהג\"ה. וענין מה שאיננו מלא<sup data-n=\"e69\">יב</sup> לפי שאל מקום שהנחלים הולכים שם הם שבים ללכת, היינו לפי' שהים הוא חכמה, זהו כפי' הב' בפי' הפסוק לך הוי' הגדולה שיש לך תלוי ראש על כל באי עולם כמ\"ש ברבות, וכמשארז\"ל לך הוי' הגדולה זו מע\"ב, א\"כ פי' לך ה' הגדולה הוא היפך מה שפי'<sup data-n=\"1307\">44</sup> לך הוי' הגדולה ביטול המדות לבחי' לאו מכל אינון מדות, וזהו ענין ההילוך בים החכמה וההחזרה משם. וגם י\"ל שע\"י לך ה' הגדולה בבחי' ביטול בתפלה עי\"ז נמשך לך ה' הגדולה שיומשך בבחי' גדולה, כי במקום גדולתו שם אתה מוצא ענוותנותו. ולפי' שפי' ים הוא בחי' מל', ענין כל הנחלים זהו ע\"י התורה בחי' נחל איתן והאיתנים מוסדי ארץ כנ\"ל, והים איננו מלא כי נקיט ויהיב. אך לפי מ\"ש אל מקום משמע שהולכים המים חזרה, וא\"כ קאי זה על העלאת מ\"ן דמל' ע\"י בחי' בירור התורה, ונמצא שעולה חזרה בבחי' מ\"ן לז\"א דאצי'. ולפי' הזהר שנמשך",[["1304","41","<b>בלק\"ת בד\"ה ראה אנכי נותן</b>: פ' ראה יח, ב."],["1305","42","<b>בד\"ה ראה הנ\"ל ובהגהות לשם בספר תרכ\"ב</b>: נדפס באוה\"ת ראה ע' תרלו. וראה גם סה\"מ תרכ\"ו ע' רח. הובא לקמן בד\"ה משכיל לאיתן."],["1306","43","<b>כמשנ\"ת מזה באורך בד\"ה א\"ר יוסי יהא חלקי</b>: סה\"מ תרכ\"ט ע' לב. וע' לד ואילך."],["1307","44","<b>כפי' הב' בפי'. . לך ה' הגדולה שיש לך תלוי ראש. . היפך מה שפי'</b>: ראה במדב\"ר פ\"א, ט: שאו את ראש, אמר הקב\"ה לישראל כו' כשם שיש לי תלוי ראש (זקיפת ונשיאת ראש) על כל באי עולם שנא' לך ה' הגדולה, כך עשיתי להיות לכם תלוי ראש. וראה סה\"מ תרכ\"ז (הוצאת תש\"ס) ע' רא: יש ב' פי' בפי' לך ה' הגדולה, הא' (מלמטלמ\"ע) הוא כי מדת הגדולה בטל וטפל לך לעצמותו ית', והב' (מלמעלמ\"ט) לך ה' הגדולה שנמשך בבחי' הגדולה וכמ\"ש במד\"ר כשם שיש לי תלוי ראש על כל העולם שנא' לך ה' הגדולה. וראה גם אוה\"ת מסעי ע' א'שסו. ואתחנן ע' רנד-ה. סה\"מ תרכ\"ז שם ע' שעב. ועוד.\n\n<b>יב</b>  <b>וענין מה שאיננו מלא</b>: בשולי הגליון נרשם בגוכי\"ק: צ\"ע ענין והים איננו מלא, וי\"ל לפי שצ\"ל תמיד והגית בה יומם ולילה, אך באמת י\"ל שהים איננו מלא לפי שאל מקום כו' שבים היינו פי' הב' בלך ה' הגדולה. ולפי' הא' שקאי על המל' לפי דנקיט ויהיב, כן בתורה עי\"ז נמשך המשכות אלקות בבי\"ע."]]],[2000510402,"בבי\"ע, כן י\"ל דנקיט ע\"י התורה מאצי' ויהיב בבי\"ע המשכת אלקות ע\"י התורה. אך מ\"ש וצדקה כנחל איתן י\"ל דקאי על בעלי עסקים, כי פי' כל הנחלים זהו ע\"י התורה ותפלה כנ\"ל, אמנם הבעלי עסקים שאינם פנוים כלל ללמוד, ובתפלה הגם שמתעורר מ\"מ אחר התפלה חולפת ועוברת והי' כלא הי', לכן אמר וצדקה כנחל איתן שע\"י הצדקה שנותן לעני ממה שהרויח והניח נפשו עלי' ה\"ז כנחל איתן, כי שיעור צדקה הוא חומש מהריוח כמאמר המבזבז אל יבזבז יותר מחומש, וע\"י החומש עי\"ז מגיע לבחי' והחמישית לפרעה, בחי' קוצו של יו\"ד כמ\"ש במ\"א<sup data-n=\"1308\">45</sup>, וזהו אל מקום שהנחלים הולכים שם הם שבים ללכת ע\"י הצדקה שהיא כנחל איתן לפי ב' הפירושים, וזהו תחת אשר לא עבדת כו' מרוב כל, נשמע שעבודה בשמחה היא יותר מבחי' כל היינו בחי' כל הנחלים, כל אותיות לך לפי ב' הפי', והעבודה בשמחה היא יותר מבחי' כל הנחלים שהולכים אל הים, וא\"כ מ\"ש אח\"כ הם שבים ללכת זהו בחי' עליונה יותר כו', ונמצא כל הנחלים הולכים אל הים זהו תפלה ותורה מלמטה למעלה ומלמעלה למטה, אל מקום וגו' שם הם שבים ללכת זהו ע\"י הצדקה שהיא כנחל איתן כו'.",[["1308","45","<b>לבחי' והחמישית לפרעה. . כמ\"ש במ\"א</b>: ראה לקו\"ת שה\"ש ו, ד. כד, רע\"ד. אוה\"ת ויגש (כרך ו) תתשיד, א. ובכ\"מ."]]],[2000510403,"<h3>[משכיל לאיתן האזרחי]</h3>\n<b></b><b>[ד\"ה משכיל לאיתן האזרחי] </b>\n<b></b>וביאור ענין נחל איתן צלמ\"ש משכיל לאיתן\nל\"ג בעומר\nבס\"ד. ל\"ג בעומר.\n<b></b>[מז)] וביאור ענין<sup data-n=\"1309\">1</sup> נחל איתן, צ\"ל מ\"ש משכיל לאיתן האזרחי, הנה פי' איתן הוא מלשון חוזק, מלשון איתן מושבך, האזרחי הוא מלשון כל האזרח בישראל, שענין פי' האזרח הוא מלשון כגר כאזרח, שהגר הבא ממקום אחר לכאן ה\"ה בכאן גר, היינו שלא כביר בא לכאן, ואזרח הוא אשר הוא נולד כאן עד\"מ",[["1309","1","<b>וביאור ענין. . משכיל לאיתן האזרחי</b>: מאמר זה הוא מאמר השביעי שבהמשך והחרים תרל\"א\". וראה לכללות המאמר לקמן ע' שסז ד\"ה ולהבין בתוס' ביאור כו' בענין והאיתנים שהוא רישומי דברים ממאמר זה.\nלכמה מעניני המאמר ראה ד\"ה זימנא חדא באוה\"ת ויקרא ע' רנד ואילך. ובסה\"מ תרכ\"ז ע' רצב. המאמר נמצא בקיצור בד\"ה וכי תאמרו מה נאכל בסה\"מ תרל\"ב ח\"א ע' קסו-ז. [וראה גם שם ע' שטו-ז]. ובארוכה בד\"ה להבין ענין רשב\"י תשמ\"ה בסה\"מ מלוקט ח\"ב ע' שא ואילך.\nלהתחלת וסיום המאמר (ע\"פ משכיל לאיתן האזרחי) ראה גם לקו\"ת ראה יח, א ואילך. אוה\"ת ויחי שפז, א ואילך. שצב, א ואילך. שם (כרך ה) תתרי, א ואילך. שמות ע' יד ואילך. ראה ע' תרלח ואילך. תרסב ואילך. סה\"מ תרכ\"ו ע' רח ואילך. תרל\"ג ח\"ב ע' תמד ואילך. וע' תנה ואילך."]]],[2000510404,"ואבותיו ואבות אבותיו היו כאן, לזה יקרא אזרח להיותו פה מאז ומעולם כמו מאז יסדה, או מאז היותו לאיש ה\"ה כאן, ונמצא כי איתן לפי פירושו מל' חוזק ל' איתן מושבך ואזרח קרובי' לגבי הדדי, כי מי שהוא אזרח במקום זה הרי ישיבתו בכאן הוא בחוזק, משא\"כ הגר הבא מארץ רחוקה אין ישיבתו בכאן בחוזק, אם מפאת אשר דעתו ולבו אל המקום אשר הלך משם, או מפאת אשר עדיין לא נתיישבה דעתו להיות כאזרחי הארץ להיות כהם בענין חן מקום על יושביה, ולכן דעתו אינו מקובלת להאזרחי' בענין הנהגת הארץ ההיא, וכמ\"ש ללוט האחד בא לגור וישפוט שפוט, שזהו מהתימה מאחר שעדיין לא נתיישב בפה הרבה רק לא כביר בא לכאן, שעש\"ז אמרו עליו לשון גרות שזה מורה על מי שבא לכאן לא כביר, לכן איך ישפוט שנקבל דעתו מאחר שכל ישיבתו אינו בחוזק עדיין כו'. ועוד יש פי' בענין אזרח לשון זריחה, כמו וזרח השמש, וא\"כ פי' האזרח<sup data-n=\"1310\">2</sup> הוא מה שאני עתיד להזריח בכם כו', ולפ\"ז צ\"ל מהו עוד הבחי' משכיל לבחי' איתן האזרחי. הנה ענין איתן כמשמעו קשה, פי' קשה שאינו נמשך כ\"כ בדרך השפעה כענין דבר רך.\n<b>והענין</b> הוא דהנה נת' לעיל בענין כל הנחלים הולכים אל הים שזהו ע\"י התורה והאיתנים מוסדי ארץ איתנים אותיות תנאים, שהם הם מוסדי ארץ תושבע\"פ שנק' ארץ כנ\"ל, ופי' וענין מוסדי לכאורה הוא מלשון יסוד כמו שעל היסוד עומד הבנין, שהעיקר תלוי בו, אם היסוד חזק עומד כל הבנין בחוזק, כן י\"ל ענין פי' מוסדי ארץ שהם יסוד הארץ דתושבע\"פ, וזה נודע שבזה אינו דומה יסוד שלמטה ליסוד שלמעלה, שלמטה היסוד למטה והבנין נבנה על היסוד, ולמעלה בהיפך שהיסוד הוא למעלה<sup data-n=\"1311\">3</sup> והבנין הוא למטה מהיסוד. אמנם באמת אינו דומה כלל המשל להנמשל בענין והאיתנים מוסדי ארץ שענין היסוד למטה אין היסוד עושה הבנין כלל, כ\"א סובלו, אבל הבנין הוא דבר בפ\"ע כו', אבל ענין והאיתנים שהם התנאים שהם מוסדי ארץ הנה הם הם העושים בחי' תושבע\"פ, שהרי הוא קיבוץ דינים ממאמריהם שמפרשים דברי הפסוק, ולכן אין הפי' מוסדי מלשון יסוד כ\"א מענין שהם המייסדים כל הבנין, ולא יסוד כענין סובל ומחזיק, אלא ע\"ד משפיע ועושה הכל. וה\"ז כמו יסוד למעלה שדרך בו עובר השפע למל', ומ\"מ אינו דומה ממש, שהרי למעלה מ\"מ נבנה בנין פרצוף המל' גם קודם השפעת היסוד היינו מבחי' מל' של כל ספי' כנ\"ל, ובענין תושבע\"פ ה\"ה הם המייסדים לגמרי ועושים הכל, אך י\"ל שענין בנין המל' מהמל' שבספי' י\"ל שזהו ג\"כ ע\"י בחי' יסוד של כל מדה, וצ\"ע. וזהו ענין הנחל איתן דתנאים מוסדי ארץ כמשנ\"ת לעיל, ונק' איתן ע\"ש קבלתם איש מפי איש מפי משה כו'.",[["1310","2","<b>פי' איתן. . מל' חוזק. . האזרחי. . מל' כל האזרח</b>: בהבא לקמן בפיסקא זו ראה בדרושים (ע\"פ משכיל לאיתן) שנסמנו בתחילת המאמר. לעיל ע' קנח. וש\"נ."],["1311","3","<b>שלמטה היסוד למטה. . ולמעלה בהיפך שהיסוד הוא למעלה</b>: ראה גם אוה\"ת שמות (כרך ז) ע' ב'תקלב (בשם הפרדס שכ\"ג ערך יסוד. וראה גם ס' דרך אמונה [להר\"מ בן גבאי] ספ\"ט). סה\"מ תרל\"ג ח\"ב ע' שסד. ובארוכה סה\"מ מלוקט ח\"א ע' סו."]]],[2000510405,"<b></b>[מח)] אמנם בכדי שיומשך מבחי' איתן, שהוא כמשמעו קשה שה\"ע העדר השפעה כמשי\"ת לקמן אי\"ה, לבחי' נחל הוא בחי' מדות, שהרי באמת אין ערוך המדות לגבי המוחין<sup data-n=\"1312\">4</sup> כלל, וכמש\"ל בענין המשלים דארי'<sup data-n=\"1313\">5</sup> דחסד לגבי ארי' דחכמה שאין ערוך ביניהם כלל, שז\"ע מה שארז\"ל אלפי' שנה קדמה תורה לעולם, שענין פי' קדמה אין פי' שקדמה בזמן כ\"א קדמה במדרגה, שהרי קודם שנבה\"ע לא הי' גם זמן, שהזמן הוא נברא ומחודש כמו המקום דעולם כו', אלא פי' קדמה הוא כנ\"ל במעלה ומדרגה, ולכן מחולקים הם גם בפעולתם, שהרי ענין המדות עד\"מ מדת החסד הו\"ע השפעת הטוב והחסד, שזהו רק שיש מציאות נברא על מי להתחסד או להתרחם, אבל כשלא יש עדיין מציאות נברא עוד על מי להתחסד או להתרחם הרי מתבטל מהות המדה לגמרי, שהרי כל ענין החסד הוא להתחסד וכשלא יש על מי להתחסד ממילא מתבטל המדה לגמרי, עד\"מ כשלא יש עני למי ליתן ממילא מתבטל מדת הנדיבות של זה, ואם הי' נמצא עכ\"פ בעולם עני היינו יכולי' לומר שמ\"מ מתעורר אצל הנדיב אי' ימצא עני להשפיע לו, אבל קודם שנברא עוד אדם וכ\"ש קודם שנבה\"ע לגמרי שמאחר שלא יש כלל למי להשפיע אינו מתעורר המדה כלל וכלל, שהרי ג\"ז אינו ידוע עדיין שיהי' עני ושיהי' מדת ההשפעה לעני. אמנם כ\"ז הוא באדם, אבל למעלה שייכים בחי' אלו גם קודם שנברא, והגם שנת\"ל ובכ\"מ בענין זכור רחמיך וחסדיך<sup data-n=\"1314\">6</sup> כי מעולם המה הנה הפי' שהם שייכים לעולמות, מ\"מ א\"א לומר שאם לא העולם הי' מתבטל המדה, שאפשר הי' באופן אחר השפעת המדות והחקר אלק' תמצא, אלא זה נוכל לומר גם באלקות, שכמו שאנו משיגים כעת ענין המדות אנו יודעים שהמדות שייכים לעולמות, ובלא העולם אין אנו יודעים כלל למה הוא ענין המדה כו', אבל ענין החכמה הרי יוכל לישב בפ\"ע ולהשכיל השכלות הגם כי לא יש לפני מי לסדר הדברים ולהשפיע לו כלל וכמו רשב\"י שישב במערה י\"ג שנה, ואעפ\"כ ניתוסף אצלו כמארז\"ל לגבי ר' פנחס בן יאיר, וע' מזה באריכות בד\"ה אשר ברא<sup data-n=\"1315\">7</sup> אלקי' לעשות, ואדרבה ענין פעולת החכ' כשצריכה לבוא על אמיתות הדבר לשפוט בשכלו אם כך הוא או כך הוא, אז ה\"ה שותק לגמרי בהעדר ההשפעה עד שיניח א\"ע בהנחה שכך הוא (בל\"א איבער לייגין בא זיך גופא אזוי ציא אזוי). ולכן מצינו במשנה דסנהדרין שהיו מזדווגין זוגות זוגות, ויש בזה ב' פירושי' רש\"י והרמב\"ם<sup data-n=\"1316\">8</sup>, או כל אחד ואחד לעצמו או עם בן זוגו, עכ\"פ לא הכל ביחד. ולכאו' למה לא ישבו כל הלילה יחד ויחדיו ימתיקו סוד הדבר",[["1312","4","<b>אמנם בכדי שיומשך. . אין ערוך המדות לגבי המוחין</b>: בהבא לקמן בפיסקא זו ראה סה\"מ תרכ\"ח ע' ד ואילך. תרכ\"ט ע' ט. תרל\"ג ח\"ב ע' תקמ-מא. תרל\"ד ע' נד ואילך. עזר\"ת ע' קסח ואילך. תש\"ח ע' 272 ואילך. ועוד."],["1313","5","<b>וכמש\"ל בענין המשלים דארי'</b>: ד\"ה ואתה הרם את מטך (לעיל ע' רפח-ט)."],["1314","6","<b>שנת\"ל ובכ\"מ בענין זכור רחמיך וחסדיך</b>: לעיל ד\"ה ואתה הרם שם. ובמקומות שנסמנו לעיל בהערה ד\"ה: אמנם בכדי שיומשך."],["1315","7","<b>וע' מזה באריכות בד\"ה אשר ברא</b>: סה\"מ תרכ\"ח שם ע' ד."],["1316","8","<b>ולכן מצינו. . דסנהדרין שהיו מזדווגין זוגות. . ב' פירושי' רש\"י והרמב\"ם</b>: ראה בארוכה סה\"מ תרכ\"ח שם ע' ה. תרכ\"ט שם ע' ט."]]],[2000510406,"לבוא על הענין איך הוא, אלא ע\"כ צ\"ל שבכדי לבוא על אמיתות הענין יותר טוב שיהי' כאו\"א לעצמו מכמו שיהיו כולם יחד, או עם בן זוגו לבד, והיינו שי\"ל כי ע\"י בן זוגו מאיר ההעלם שלצורך השפעה, ואז יוכל לבוא לידי גילוי מהעלם הכללי שלצורך עצמו, כמשי\"ת מזה לקמן אי\"ה. עכ\"פ היוצא מזה שהחכ' והמדות רחוקים הם זמ\"ז בתכלית, הן מצד עצמן והן מצד גילוי בחי' ומדריגותם, וא\"כ בכדי שיומשך מבחי' איתן שהוא כמשמעו קשה בחי' העדר ההשפעה, לבחי' נחל בחי' מדות שהם כל מהותם ה\"ה בחי' השפעה לזולתו, צריך להיות ממוצע ביניהם.\n<b></b>[מט)] ולהבין ענין הממוצע<sup data-n=\"1317\">9</sup> צריכים להקדים תחלה ענין מה שמצינו בזהר ששיבחו את רשב\"י בשבחים נוראים<sup data-n=\"1318\">10</sup>, כמו שאמרו שם ר' יהודה הוה קרי לי' שבת והיינו כמו שהשבת היא קדש כמ\"ש ושמרתם את השבת כי קדש היא, כן רשב\"י הוא קדש, והיינו שהי' קרי לי' קדש לגבם, כמו קדש לגבי החול כן הי' רשב\"י נגדם, וא\"כ ה\"ז כמו שבת שבתון בחי' קדה\"ק, שהרי גם הם היו סמוכים איש מפי איש עד משה, ות\"ח הוא שמקבל מחכ' הנק' קדש, ומ\"מ הוא הי' שבת נגדם. וכן מצינו פעם בזהר שאמרו מאן פני האדון דא רשב\"י, בזח\"ב פ' בא דל\"ח ע\"א, שלכאו' יפלא מאד האיך יאמרו על נברא מאן פני האדון הלא כתיב האדון ה' בפ' משפטים, וא\"כ האיך יאמרו על רשב\"י, שמ\"מ הי' נברא<sup data-n=\"1319\">11</sup> ונשמה המלובשת בגוף, מאן פני האדון דא רשב\"י, וגם מהו ענין השבחים, שלכאורה אין זה מדת חסידות כלל שישבחו אותו בפניו כ\"כ.\n<b>אך</b> הענין דהנה צ\"ל ענין שארז\"ל לעולם יסדר אדם שבחו של מקום<sup data-n=\"1320\">12</sup> ואח\"כ יתפלל, דלכאו' זהו ג\"כ פלא מהו ענין השבחים שמשבחים הבורא ית', ומה תופס מקום",[["1317","9","<b>ולהבין ענין הממוצע</b>: בהבא לקמן ראה בארוכה ד\"ה להבין ענין רשב\"י תשמ\"ה בסה\"מ מלוקט ח\"ב שם. וראה גם סה\"מ תרכ\"ז שם ר\"ע רצב."],["1318","10","<b>ששיבחו את רשב\"י בשבחים נוראים</b>: בסה\"מ מלוקט שם מציין ע\"ז: ראה ספר שבחין דרשב\"י (להריא\"ז מרגליות)."],["1319","11","<b>שאמרו מאן פני האדון דא רשב\"י. . האיך יאמרו. . שמ\"מ הי' נברא</b>: ראה בארוכה מאמרי אדה\"ז תקס\"ד ע' קו. אוה\"ת ויחי שנח, ב. סה\"מ תרל\"ב ח\"א ע' לח ואילך. וש\"נ. [ובהנסמן בהמ\"מ שם לתחילת המאמר]. וע' ר ואילך."],["1320","12","<b>אך הענין דהנה צ\"ל ענין שארז\"ל לעולם יסדר אדם שבחו של מקום</b>: בהבא לקמן בפיסקא זו ראה הוספות לתו\"א ויחי קב, א. קג, ג ואילך. [ראה ד\"ה לה\"ע רשב\"י תשמ\"ה (הנחה): יש לומר (לפענ\"ד) שביאור זה [בהמאמר דתרל\"א] מיוסד על מאמר כ\"ק אדמו\"ר הזקן הנחת כ\"ק אדמו\"ר האמצעי הנדפס בהוספות לתורה אור]. ובארוכה מאמרי אדה\"ז תקס\"ח ח\"א ע' שע ואילך [ד\"ה ועתה אלקינו]. שם ח\"ב ע' תש ואילך. ובתוס' הגהות באוה\"ת חנוכה (כרך ה) תתקלה, א ואילך. דרך מצותיך קמח, א ואילך [ד\"ה להבין ענין הלל]. וראה גם לקו\"ת קדושים כט, סע\"ב-ג. סידור עם דא\"ח נו, ב. שערי אורה שער החנוכה יח, א ואילך. דרך מצותיך שם קיח, א. אוה\"ת ויקרא (כרך ב) ע' תרצז. נ\"ך (כרך א) ע' שנד. וראה ד\"ה לה\"ע רשב\"י בסה\"מ מלוקט שם: ויש לומר דמ\"ש בהמאמר (דתרל\"א) דענין שבחי רשב\"י יובן מענין שבחו של מקום, הוא בנוסף על הבאת ראי' שבכדי לעורר השפעה שבאי\"ע צריך לשבחים, אלא גם שהאין ערוך דשאר התנאים לגבי רשב\"י הוא בדוגמת האין ערוך דנברא לבורא."]]],[2000510407,"ענין השבח מה שמשבח אותו הנברא פרטי, הלא כתיב אני הוי' לא שניתי שלא יש ח\"ו שום שינוי בין קודם שנבה\"ע לאחר שנברא העולם, שלכאורה זהו יפלא איך לא ימצא שינוי, הלא מתחלה לא הי' העולם ונבראים, ועכשיו יש, ה\"ז שינוי גדול, וע\"כ לגבי הדבר שנתהוו ממנו צ\"ל ג\"כ שיש קצת שינוי, שהרי יש כח הפועל בנפעל, ואיך אומרים אתה הוא קודם שנבה\"ע ואתה הוא לאחר שנבה\"ע. אך הענין ידוע שזהו מפני שכלליות השתלשלו' העולמות שנתהוו הוא רק מהארה בעלמא<sup data-n=\"1321\">13</sup> שאינו נוגע לעצמותו כלל וכלל ואינו תופס מקום כלל ההארה שנמשכה ונבהקה מאתו ית' להוות העולמות, אשר לכן אני הוי' לא שניתי כלל כמ\"ש מזה במ\"א באורך וכנ\"ל. ואי לזאת תגדל הקושיא בענין סידור שבחו של מקום, וענין הללוי' מהו ענין ההילול ומה תופס מקום ענין הילול זה. אך הענין הוא דהנה מזה עצמו להיותו אינו תופס מקום כלל כלליות העולם וכל אשר בה, לזאת ע\"י השבח וההילול אנו מעוררים אותו ית' שיומשך ההארה ורצון חדש (היינו לחדש הישנות מה שעלה ברצונו) על חידוש הישנות בחי' חיות העולמות בבחי' פנימי', שז\"ע זכרונות כמ\"ש במ\"א שמבקשים שיזכור על הדבר<sup data-n=\"1322\">14</sup> שבעצם רחוק הוא מזה, וכ\"ה ענין ההילול שבכל יום, להיות כי אדם נידון בכל יום וכמ\"ש לרגעים תבחננו כמ\"ש במ\"א<sup data-n=\"1323\">15</sup>, והיינו שכמו שאנו רואים עד\"מ במי שהוא נדבן בעצם ואעפ\"כ יכול להיות שמצד איזה טרדא או שאר מניעה ישכח על העני המקבל ודורש טובתו, וכ\"ש מי שהוא כילי בעצם, הנה ע\"י השבח שמשבחים אותו עי\"ז יתעורר<sup data-n=\"1324\">16</sup> מדת נדבנותו, או רחמנותו עכ\"פ בכילי, להשפיע טוב וחסד להעני הצריך לזה בהשפעת חיי שעה. ועד\"ז יובן בענין סידור שבחו של מקום שלהיות שכלליות ההשתלשלו' הוא מהארה קטנה ומועטת שאינו בערך כלל להמשפיע, יותר מטיפה נגד הים כמ\"ש במ\"א באריכות<sup data-n=\"1325\">17</sup> וכנ\"ל, ובכדי להיות ההתהוות זהו ע\"י שנמשך מיש האמיתי לאין ומאין ליש כנ\"ל, אי לזאת מצד גודל שפלותינו אין אנו כדאי כלל להיות בזכרונו להשפיע לנו טוב וחסד כו', לכן אנו מעוררים אותו בשבחים איך שהללו את ה' מן השמים כו' והללו את ה' מן הארץ וגו', וכל ריבוי השבחים שאנו משבחים ומעוררים הוא בכדי שיפנה ויתעורר ברצון להשפיע גם למי שאין ערוך כלל וכלל היינו כלליות ההשתל', ואח\"כ מתפלל על",[["1321","13","<b>העולמות. . מהארה בעלמא. . לכן אני ה' לא שניתי כלל כמ\"ש מזה במ\"א באורך</b>: ראה תו\"א יתרו סז, א. לקו\"ת דרושים לר\"ה נח, ג. שה\"ש ז, ד. ובכ\"מ."],["1322","14","<b>זכרונות כמ\"ש במ\"א שמבקשים שיזכור על הדבר</b>: ראה בארוכה לקו\"ת דרושים לר\"ה נח, ג שם."],["1323","15","<b>אדם נידון בכל יום וכמ\"ש לרגעים תבחננו כמ\"ש במ\"א</b>: ראה בארוכה לקו\"ת קרח נה, ג ואילך. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרמח ואילך. אוה\"ת ראה ע' תשכב ואילך. דרך מצותיך קו, א ואילך. קיב, א ואילך. סה\"מ תרכ\"ז ע' סד ואילך. וש\"נ. קונטרס ומעין סוף מאמר יז ואילך (ע' 108 ואילך). חנוך לנער ע' 46 ואילך. סה\"מ מלוקט ח\"ד ע' רצא ואילך. לקו\"ש ח\"ט ע' 375 ואילך."],["1324","16","<b>ע\"י השבח שמשבחים אותו עי\"ז יתעורר</b>: ראה גם (נוסף למקומות שנסמנו בתחילת הפיסקא) תו\"א וישב ל, א."],["1325","17","<b>ההשתלשלות. . שאינו בערך. . יותר מטיפה נגד הים כמ\"ש במ\"א באריכות</b>: ראה סה\"מ תרכ\"ז ע' רצג. שצ. תסה. תרכ\"ט ס\"ע ב. תרל\"ב ח\"א ע' קסט. ח\"ב ע' תקסו. וראה גם לקו\"ת מסעי פח, ד. מאמרי אדה\"ז הנחות הר\"פ ס\"ע קז-ח. ועוד."]]],[2000510408,"הפרט בי\"ב ברכות אמצעיות שאדם שואל בהן צרכיו כו', ולזה עצת חז\"ל במה שאמרו לעולם יסדר אדם שבחו של מקום ואח\"כ יתפלל, והיינו שבכדי שיהי' תפלתו רצוי' שיעשה לו בקשתו לזה יעצו לו להקדים שבחו של מקום בתחלה ואח\"כ יתפלל כו'.\n[נ)] <b>אך</b> מ\"מ עדיין אינו מתורץ כלל שהרי נודע שענין התפלה הוא בקשת יהי רצון שיומשך רצון חדש לרפאות החולי ולברך השנים שזהו להמשיך בחי' שגם במקור לא יש עדיין, וכנודע שזהו ההפרש בין תפלה לברכה<sup data-n=\"1326\">18</sup>, שענין הברכה הוא להמשיך רק מה שכבר ישנו בשרשו ומקורו רק שנתעכב מחמת איזה סיבה יהי' מה שיהי' בסדרי ההשתלשלו', לזה הו\"ע הברכה שיומשך משם בלי עיכוב, אבל אם גם בשרש ומקור לא יש ולא נמשך כלל לא יועיל ענין הברכה כלל, וכמ\"ש איש אשר כברכתו בירך אותם, או כענין הברכות שבירך יעקב למנשה ואפרים כשתמך יוסף יד אביו להסיר אותה מעל ראש אפרים על ראש מנשה, וא\"ל יעקב ידעתי בני ידעתי גם הוא יהי' לעם וגם הוא יגדל ואולם אחיו הקטן יגדל ממנו וזרעו יהי' מלא הגוים, ולכאו' למה לא ברכו שגם מנשה יגדל כמו אפרים וזרעו יהי' ג\"כ מלא הגוים. אך הענין הוא דהנה שרש ענין הברכה הוא להמשיך מהמקור מה שיש שם, רק מפני איזהו עיכוב אשר נתעכב ולא נמשך למטה, זהו ענין הברכה שיומשך למטה ממקור שרשו כמו שהוא במקור שרשו כו'. אבל ענין התפלה הוא להמשיך ע\"י תפלתו שיומשך רצון חדש לרפאות החולי ולברך השנים, שזהו אם ח\"ו נגזר גזירה רעה על החולה או על תבואות השנה יפעול ע\"י תפלתו שיומשך רצון חדש שיתרפא החולה ויתברך השנה היפך הגזר דין כו', והיינו לפי שע\"י התפלה ממשיכים מלמעלה מה שבמקור ג\"כ לא יש עדיין, וע\"י התפלה ממשיכים רצון חדש שיומשך במקור ושורש. ונמצא כי ענין התפלה היא למעלה מבחי' המקור ושרש לפרט הבקשה הזה. וא\"כ מהו ענין הסידור שבחו של מקום קודם התפלה, וכי מאי ענין זל\"ז, הלא סידור שבחים הוא סיפור איך שמשבחים השמים וארץ ומלאכים ונשמות שכל זה הוא בסדר השתלשלות, וענין התפלה הוא להמשיך יהי רצון מלמעלה מהשתלשלו', שלכאורה רחוקים הם זמ\"ז, ומה גם להקדים שבחו של מקום, ואם מפני שלא יתעכב בסדרי ההשתל' שז\"ע אדם נידון בכל יום כנ\"ל הלא לכל הפחות הי' צריך להקדים תפלה תחלה כסדר מלמעלמ\"ט שזהו עיקר התפלה להמשיך מלמעלה מהשתלשלו', וכ\"ש שיועיל השבח שעי\"ז יתקבל תפלתו שלכאו' זהו פלאי. אך הענין דהיא הנותנת שלפי שמעלת התפלה שממשיכים בחי' יהי רצון שזהו מלמעלה מסדר ההשתל', הנה נודע כי שם אם צדקת כו' ואינו תופס מקום, וא\"כ משם ודאי שאין שום מניעה כלל וכלל להשפעת החיים לחולה והברכה לתבואות, וא\"כ מה\"ע שיתקבל תפלתו הלא",[["1326","18","<b>וכנודע שזהו ההפרש בין תפלה וברכה</b>: בהבא לקמן בפיסקא זו ראה מאמרי אדה\"ז תקס\"ח ח\"ב שם ע' תשז ואילך [ד\"ה ועתה אלקינו]. סה\"מ תרכ\"ו ע' קלב ואילך. תרכ\"ז ע' שצד ואילך [ובהנסמן שם]. תרכ\"ט ע' ב ואילך. תרל\"ב ח\"ב ע' תמה ואילך [ובהנסמן שם]. תקנד ואילך. תרל\"ה ח\"א ע' ר ואילך. וע' רו ואילך. תרנ\"ד ע' שיא ואילך. תרע\"ח ע' תב ואילך."]]],[2000510409,"משם בודאי יומשך כן, א\"ל שיש ח\"ו איזה עיכוב בסדרי השתלשלו' שעי\"ז יתעכב תפלתו ולא יתקבל מחמת עיכוב בסדרי ההשתלשלות, לזאת יעצו חז\"ל לעולם יסדר אדם שבחו של מקום ואח\"כ יתפלל להיות כי ע\"י הסידור שבחו של מקום עי\"ז יתעורר רחמיו וחסדיו שלא יהי' שום עיכוב בההשפעה הבאה מלמעלה מסדר השתלשלו' ע\"י התפלה בקשות יהי רצון כו'. ונמצא כי העיכוב שחששו חז\"ל שלא יתקבל תפלתו זהו מחמת סדר השתלשלו', וע\"י השבח פועל שלא יהי' עיכוב בסדרי השתל' דוקא, ומ\"מ צריך להקדים שבחו של מקום קודם התפלה מטעם הנ\"ל.\n<b></b>[נא)] ועפי\"ז יובן ענין השבחים<sup data-n=\"1327\">19</sup> שהיו משבחים את רשב\"י הוא בכדי שיתעורר שפע הפנימי לצאת מהעלם אל הגילוי בחי' פנימיות תורתו, כי מאחר שהוא הי' הממוצע ביניהם א\"כ ע\"כ יש בו ב' בחי', שהם ב' בחי' ים וארץ, ורצו שיומשך בהם גם מבחי' ים שבו היינו בחי' ההעלם כו'. וביאור הענין הוא כנ\"ל בענין הוי זנב לאריות שבחי' זו הוא מה שהוא מקבל מבחי' שלמעלה ממנו, וכענין ים סוף בחי' סופא דכל דרגין דאצי' והים הוא מעלים בו כל שפע האצי', כן יובן בענין רשב\"י שהי' הממוצע בין בחי' איתן להתנאים הנק' איתנים, ה\"ה מעלים בתוכו כל שפע מבחי' ים הקדמוני דחכ', והיינו בחי' ההעלם שלצורך עצמו תחילה, ואח\"כ הוא בחי' ההעלם בכדי שאחר העלם זה יוכל להיות גילוי, שזהו בחי' ים וארץ, והים הוא סיבה שיוכל להיות ארץ אח\"כ, שזהו בחי' ההעלם שהוא סיבת הגילוי, אבל בחי' ההעלם אשר בו עצמו המעלים אור קבלתו לצורך עצמו זה אינו שייך כלל לגילוי. אמנם ע\"י ההילול והשבח שמשבחים אותו, עי\"ז נתעורר שפע המשפיע שיושפע להם גם מבחי' ההעלם שלו עצמו ג\"כ, ומפני היותו ממוצע בין בחי' איתן מ\"ה דחכמה, לכן לא הי' שייך כלל לאמר איזהו הרגש קל ח\"ו מענין השבחים שהרי כבוד חכמים ינחלו כמ\"ש במ\"א<sup data-n=\"1328\">20</sup>, ומ\"מ ע\"י השבחים עוררו אותו שיומשך להם מבחי' ההעלם שלצורך עצמו כו'. וזהו איתן האזרחי, מלשון כגר כאזרח שפי' תושב. והרמ\"ז פי' שאזרח הוא בחי' שם ע\"ב, כי בנין התהו ע\"מ לסתור, והסתירה ע\"מ לבנות ע\"י בחי' התיקון שם מ\"ה החדש, אבל שם ע\"ב הוא בחי' אזרח, וע' בד\"ה ראה אנכי דתרך\"ב הגהות על הלקו\"ת בהקיצור<sup data-n=\"1329\">21</sup> שם ששם ע\"ב הוא בחי' א\"ק.",[["1327","19","<b>ועפי\"ז יובן ענין השבחים</b>: בהבא לקמן ראה בקיצור בד\"ה זימנא חדא באוה\"ת ויקרא שם ע' רנז: וגם על ידי השבחים מעורר החכמה שבכח בהעלם לבוא מן ההעלם אל הגילוי. וראה (באו\"א) בסה\"מ תרכ\"ז שם ע' רצט, וז\"ל: ענין ההעלאת מ\"ן של החברייא ששיבחו אותו בעסק תורתו הוא בכדי להגביה את נשמת רשב\"י כו' ע\"י השבחים ששיבחו את רשב\"י בעסק תורתו העלו אותו לקשרו באוא\"ס ב\"ה שישרה אוא\"ס בחי' דבר הוי' כו' בעסק תורתו."],["1328","20","<b>לא הי' שייך כלל לאמר. . שהרי כבוד חכמים ינחלו כמ\"ש במ\"א</b>: ראה לקו\"ת אחרי כז, ג. מאמרי אדה\"ז תקס\"ז ע' שכא. סידור עם דא\"ח קל, ב. שערי תשובה ח\"א עג, ג. אוה\"ת תצוה (כרך ז) ע' ב'תשנב ואילך. דרך מצותיך קעט, ב. וראה גם סה\"מ תר\"ל ע' עג. עו."],["1329","21","<b>בד\"ה ראה אנכי דתרך\"ב. . בהקיצור</b>: נדפס באוה\"ת ראה ע' תרלו. וראה גם סה\"מ תרכ\"ו ע' רח. הובא לעיל בסד\"ה כל הנחלים."]]],[2000510410,"<b>ועפ\"ז</b> יובן ג\"כ ענין השבחים ששיבחו אותו שר' יהודה הוה קרי לי' שבת<sup data-n=\"1330\">22</sup>, והיינו שכמו השבת הוא קדש וכמ\"ש ושמרתם את השבת כי קדש היא וכנודע שהשבת נותן כח בששת ימי החול, וע\"ד מ\"ש כי תבואו אל הארץ ושבתה שש שנים וגו', שמשמע מיד כי תבואו ושבתה, ובאמת היו השש שנים תחלה, אך נת' ע\"ז שלהיות כי שביתת השמיטה נותנת כח בהשש שנים לכן נאמר ושבתה תחלה, ע' בלק\"ת בד\"ה כי תבואו ושבתה<sup data-n=\"1331\">23</sup>, ובד\"ה כי תבאו ושבתה שלא נדפס (למ\"ד)<sup data-n=\"1332\">24</sup>. וכ\"ה בשבת, וכנודע שעד יום ד' הוא בתר שבתא, ומיום ד' ואילך הוא קמי שבתא, והיינו שכל שבת הוא הוא הנותן כח לפניו ולאחריו. ועד\"ז רשב\"י שהי' ממוצע בין התנאי' שנק' איתן ע\"ש שהיו סמוכים איש מפי איש עד משה, ואם כי נת' בד\"ה וסמך את ידו<sup data-n=\"1333\">25</sup> על ראש העולה שענין הסמיכה הוא נתינת הכח, ולכן צ\"ל בידים בחי' דבר גשמי דוקא יעו\"ש, מ\"מ בכדי שיומשך שפע הפנימי דבחי' איתן שהוא בחי' שפע דחכ', והיינו כי חכמה הוא כ\"ח מ\"ה ונת' בפרד\"ס שבחי' כ\"ח שבחכ' זהו בחי' יחודה עם הבינה, אבל בחי' מ\"ה שבחכמה זהו בחי' ביטול החכ' לגבי הכתר<sup data-n=\"1334\">26</sup>, ולהיות כי זהו בחי' שלמעלה מהשתלשלו' שזהו בחי' מוחין דאבא, שנת' בלק\"ת בד\"ה מצה זו ובד\"ה פקודי ובד\"ה ולא תשבית<sup data-n=\"1335\">27</sup>, שבחי' מוחין דאבא הם למעלה מהשתל', וע' בסש\"ב פ\"ג ופי\"ח, אי לזאת בכדי שיומשך עליו גם בחי' שפע הפנימי לזה קרי לי' שבת, והיינו כמו שבת הוא בחי' הפנימי' כו' שלכן שער החצר הפנימי' הפונה קדים סגור יהי' ששת ימי המעשה וביום השבת יפתח, כן רשב\"י הי' הממוצע שיומשך להם ע\"י מבחי' שפע הפנימי דמ\"ה דחכמה כו'.\n<b></b>[נב)] ומה שאמרו פני האדון דא רשב\"י היינו לפי דכתי' הנה האדון ה' צבאות מסעף וגו'<sup data-n=\"1336\">28</sup>, פי' ה' צבאות הוא בחי' שם שבבריאה אות הוא בצבא דילי' וכמ\"ש בת\"א בד\"ה ויהי וגו' יצאו כל צבאות ה' בפ' בא<sup data-n=\"1337\">29</sup>. ואומרו האדון ה' הוא להיות כי על שם הוי' שייך לאמר גם ל' אדנות ג\"כ להיותו מחי' ומהוה, וכמשארז\"ל במד\"ר ששאל הקב\"ה מאדה\"ר ואני מה שמי א\"ל לך נאה לקרות הוי' שאתה אדון לכל בריותיך<sup data-n=\"1338\">30</sup> הה\"ד אני הוי' הוא שמי, הוא שמי שקרא לי אדה\"ר, ולכאו' אינו מובן כלל,",[["1330","22","<b>ועפ\"ז יובן ג\"כ. . קרי לי' שבת</b>: בהבא לקמן בפיסקא זו ראה (באו\"א) בסה\"מ תרכ\"ז שם ע' ש."],["1331","23","<b>בלק\"ת בד\"ה כי תבואו ושבתה</b>: פ' בהר מ, ד."],["1332","24","<b>ובד\"ה כי תבואו ושבתה שלא נדפס (למ\"ד)</b>: סה\"מ תר\"ל ע' קלב. ס\"ע קלז-ח."],["1333","25","<b>בד\"ה וסמך את ידו</b>: תרל\"א (לעיל ע' רלג-ד)."],["1334","26","<b>כח שבחכ'. . עם הבינה. . מ\"ה שבחכמה. . לגבי הכתר</b>: ראה בארוכה המשך וככה תרל\"ז פכ\"ה (ע' כט). ופל\"ב (ע' מג). לעיל ד\"ה ועשו ארון. [וראה גם בהנסמן בהע' הבאה]."],["1335","27","<b>בלק\"ת בד\"ה מצה זו ובד\"ה פקודי ובד\"ה ולא תשבית</b>: ד\"ה מצה זו בלקו\"ת צו יא, ד ואילך. וד\"ה אלה פקודי בלקו\"ת פקודי ג, סע\"ג ואילך. וד\"ה לא תשבית בלקו\"ת ויקרא ד, ג. וראה גם סה\"מ תרל\"ב ח\"א ע' רטז. וש\"נ. תרל\"ג ח\"א ע' קנב. וס\"ע קנו."],["1336","28","<b>דכתי' הנה האדון ה' צבאות מסעף וגו'</b>: ראה ישעי' י, לג: הנה האדון ה' צבאות מסעף פארה (יפשח (יכרית) פאורות עיקר ענפי אילנותיו רש\"י)."],["1337","29","<b>בת\"א בד\"ה ויהי גו' יצאו. . בפ' בא</b>: דף ס, ב ואילך."],["1338","30","<b>לך נאה לקרות הוי' שאתה אדון לכל בריותיך הה\"ד אני ה' הוא שמי</b>: במד\"ר בראשית יז, ד שלפנינו הגירסא: לך נאה לקרות אדנ-י\". אך כהגירסא שהובא בפנים נמצא בב\"ר עם שינויי נוסחאות (הוצאת תיאדור-אלבק). ובתנחומא שמיני ח. חוקת ו. וביל\"ש בראשית רמז כג. ועוד. [ולהעיר שבד\"ה לה\"ע רשב\"י תשמ\"ה (סה\"מ מלוקט ח\"ב שם ע' שו-ז, המיוסד על מאמר דידן) מבאר זה עפ\"י הגירסא לך נאה לקרות אדנ-י\". עיי\"ש]."]]],[2000510411,"מהו שאומר לך נאה לקרות הוי' שאתה אדון שהטעם הוא על שם אד' מלשון אדון, ואיך אמר נאה לקרות הוי' וגם מביא פסוק אני הוי' הוא שמי. אלא שעל שם הוי' שייך לומר גם בחי' אדנות ג\"כ<sup data-n=\"1339\">31</sup> להיותו אדון מושל ושולט, והיינו שההתהוות שנתהוה ע\"י שם הוי' הוא בדרך ממילא ומאליו כמ\"ש יהללו וגו' כי הוא ציוה ונבראו, כמ\"ש ביאור ד\"ז במ\"א<sup data-n=\"1340\">32</sup>, וע' בלק\"ת בד\"ה קול דודי<sup data-n=\"1341\">33</sup>, ובד\"ה קול דודי שלא נדפס ובכ\"ד בת\"א ובלק\"ת<sup data-n=\"1342\">34</sup>, וזהו עצמו ענין אדנות כו'. ועד\"ז אמרו על רשב\"י מאן פני האדון להיותו מושל ושולט להמשיך להם שפע הפנימיות, ובכח תורתו הי' יכול להמשיך השפעת גשמי', וכמו משה שביקש לכנוס לארץ שנת' ע\"ז במ\"א<sup data-n=\"1343\">35</sup> שרצה להמשיך בנש\"י הכח שיומשך להם הכל מלמעלמ\"ט ע\"ד ההמשכה שנמשך ע\"י התורה, ולא כמו ההמשכה שע\"י התפלה שהיא מלמטלמ\"ע<sup data-n=\"1344\">36</sup>. ולכאו' מהו ההפרש בין מלמעלמ\"ט ובין מלמטלמ\"ע יהי' איך שיהי' הלא נמשך כו'.\n<b>אך</b> הענין יובן שזהו ההפרש בין ג\"ע לתחה\"מ<sup data-n=\"1345\">37</sup>, שהרי אנו רואי' עד\"מ אברהם נשמתו היא בג\"ע יותר מג' אלפים שנה<sup data-n=\"1346\">38</sup>, ועכ\"ז תרד בתחה\"מ להתלבש עוד בגוף בכדי",[["1339","31","<b>מהו שאומר לך נאה לקרות הוי'. . אלא שעל שם הוי' שייך לומר גם בחי' אדנות ג\"כ</b>: ראה בביאור יותר בסה\"מ תרח\"צ ע' קט: דלכאו' הנה מטעם זה דהוא ית' אדון על כל בריותיו הי' צ\"ל השם אד' המורה על האדנות ולמה אומר שם הוי', אלא להיות דזהו שם הוי' דלתתא דפירושו לשון מהווה. ראה עד\"ז לעיל ד\"ה כמה גדולים יורדי הים: ב' שמות הוי' הם כו' שם הוי' הא' כו' שמקור לסדר ההשתלשלות כו' לשון מהוה כו' וכמארז\"ל במד\"ר ואני מה שמי לך נאה לקרות אדון שאתה אדון לכל בריותיך כו', אמנם שם הוי' דלעילא. עיי\"ש. וראה (באו\"א) בסה\"מ תרל\"ב ח\"ב ע' שסז: וי\"ל למה אמר הוי', היינו מפני כי נכתב בשם הוי' ונקרא בשם אד', ועל שם הקריאה אמר כן. (וראה עד\"ז בפי' עץ יוסף תנחומא שמיני ח. חוקת ו). ועוד ביאור ע\"ז בסה\"מ תרפ\"ב ע' לב (וסה\"מ תש\"י ע' 97): זהו מורה על גודל השגתו (של אדה\"ר), דההתהוות הוא העלם והסתר הבורא מן הנברא כו', וזהו לך נאה לקרות הוי' מפני שאתה אדון דההתהוות הוא משם הוי' אמנם הוא באופן כזה שאינו נרגש כלל, וכמו העבד שעושה מה שהאדון מצוה עליו מפני עצם מהותו שהוא עבד."],["1340","32","<b>ממילא ומאליו כמ\"ש. . כי הוא ציוה ונבראו כמ\"ש ביאור ד\"ז במ\"א</b>: ראה סה\"מ תרכ\"ט ס\"ע קלה ואילך. תרל\"ב ח\"א ע' כ ואילך. וש\"נ. כח ואילך. [ובהנסמן בהערות שלאח\"ז]."],["1341","33","<b>וע' בלק\"ת בד\"ה קול דודי</b>: לקו\"ת שה\"ש יד, ג."],["1342","34","<b>ובד\"ה קול דודי שלא נדפס ובכ\"ד בת\"א ובלק\"ת</b>: מאמרי אדה\"ז תקס\"ט ע' מב ואילך. וראה גם תו\"א מג\"א צו, ג. לקו\"ת ראה כ, ג. ועוד."],["1343","35","<b>משה שביקש לכנוס לארץ שנת' ע\"ז במ\"א</b>: לקו\"ת ואתחנן ב, סע\"ג ואילך. ג, ג ואילך. ובארוכה סה\"מ תרל\"ג ח\"ב ע' תכג. [ובהנסמן שם בתחילת המאמר]."],["1344","36","<b>מלמעלמ\"ט. . ע\"י התורה. . התפלה שהיא מלמטלמ\"ע</b>: ראה בכ\"ז בארוכה סה\"מ תרכ\"ז ע' רצב ואילך. שפט ואילך. תרל\"ב ח\"א ע' קסח ואילך. שיח ואילך."],["1345","37","<b>אך הענין יובן. . ההפרש בין ג\"ע לתחה\"מ</b>: בהבא לקמן בפיסקא זו ראה תו\"א יתרו עג, ב. סה\"מ תרל\"ג ח\"ב ע' תכא ואילך. תצב ואילך. המשך תער\"ב ח\"ב ע' תשעט ואילך. סה\"מ מלוקט ח\"ג ע' לג ואילך. וש\"נ. ח\"ד ע' קעז ואילך. וש\"נ. לקו\"ש חי\"ז ע' 344 ואילך. וש\"נ. [וראה גם סה\"מ תרל\"ב ח\"א ע' קכא-ב. ובהנסמן שם]."],["1346","38","<b>אברהם נשמתו היא בג\"ע יותר מג' אלפים שנה</b>: ראה עד\"ז בסה\"מ תרל\"ג ח\"ב ע' תכא. תצב. המשך וככה תרל\"ז פ\"ה (ע' יז). ובכ\"מ. ונת' בסה\"מ מלוקט ח\"ג ע' לז."]]],[2000510412,"להשיג הגילוי שיהי' בתחה\"מ, ולכאורה מדוע לא יסתפק בגילויי' שבג\"ע שהרי הוא עולה במעלות כמ\"פ ביום, שע\"ז אמרו צדיקים אין להם מנוחה לא בעוה\"ז ולא לעוה\"ב שנא' ילכו מחיל אל חיל, והיינו הגם שנא' בספרים רק ב' בחי' ג\"ע, ג\"ע התחתון והעליון<sup data-n=\"1347\">39</sup>, זהו בדרך כלל אבל בדרך פרט יש בחי' ג\"ע בעילוי אחר עילוי עד אין קץ, שהרי נשמת אברהם עולה במעלות ג' פעמים בכל יום, וזהו יותר מג' אלפים שנה ועכ\"ז היא עולה עוד כו', ולמה לא יסתפק בזה עד שיצטרך להתלבש בגוף בתחה\"מ, הן אמת שגילוי' שבג\"ע זהו מלמטלמ\"ע, אבל בתחה\"מ אם כי תחה\"מ היא ג\"כ מלמטלמ\"ע שהתחתון יתעלה, ולא ע\"ד מ\"ת שירד הוי' על ה\"ס הגם כי לא נזדכך העולם עדיין, אמנם בתחה\"מ יהי' ע\"ד מלמטלמ\"ע היינו שהתחתון יתעלה ג\"כ, אבל הגילוי יהי' מלמעלמ\"ט. ונמצא שכמו ההפרש בין ג\"ע למ\"ת, שג\"ע הוא עליות מלמטלמ\"ע נאמר בו מי יעלה בהר ה' היינו בחי' ג\"ע, נקי כפים ובר לבב כו', אבל במ\"ת ירד הוי' על ה\"ס הגם כי העולם לא נזדכך כלל עדיין, וכמשל ב' בנ\"א אחד עומד בעמק ואחד עומד בהר<sup data-n=\"1348\">40</sup>, שיש ב' אופנים באופן יחודם, או שהתחתון יעלה למעלה או שהעליון ירד למטה, ומובן אשר בעליית התחתון לגבי העליון כמה עקולי ופשורי איכא<sup data-n=\"e70\">יג</sup>, אבל בירידת העליון אין שום מניעה וכענין וירד הוי' על הר סיני ומי יעכבו. כן עד\"ז יובן בענין תחה\"מ שעם היות שיהי' אחר הזדככות הנבראי', שז\"ע כל העבודה דעכשיו לזכך כו', מ\"מ הגילוי יהי' ע\"ד מלמעלמ\"ט, ולכן אברהם אע\"ה שיושב יותר מג' אלפים שנה בג\"ע יבוא להתלבש בגוף בכדי לחזות בנועם ה' שיתגלה בתחה\"מ כו'.\n<b>ועד\"ז</b> יובן ההפרש בין ההמשכה שע\"י התפלה, שעם היות שע\"י התפלה ממשיכים בחי' יהי רצון כנ\"ל, אמנם הנה עליות התפלה היא בבחי' מלמטלמ\"ע, אמנם ע\"י התורה נמשך זה מלמעלמ\"ט. וזהו שביקש משה ליכנס לארץ היינו בשביל להמשיך הכח בנש\"י שיוכלו להמשיך המשכת אלקות מלמעלמ\"ט כענין ההמשכה ע\"י התורה, וכן גם השפעת גשמיות יומשך ג\"כ ע\"י ההמשכה מלמעלמ\"ט וכמו שנצטוה ודברתם אל הסלע כמארז\"ל שנה עליו פרק אחד<sup data-n=\"1349\">41</sup> ועי\"ז יוציא הסלע מימיו",[["1347","39","<b>הגם שנא' בספרים רק ב' בחי' ג\"ע ג\"ע התחתון והעליון</b>: ראה גם תו\"א שמות מט, סע\"א. ובכ\"מ."],["1348","40","<b>וכמשל ב' בנ\"א אחד עומד בעמק ואחד עומד בהר</b>: ראה גם לקו\"ת ראה כו, א. כז, ד. מאמרי אדה\"ז תקס\"ג ח\"ב ע' תרסז. תקס\"ט ע' קלא. פרשיות ח\"ב ע' תרצו. אמרי בינה שער הק\"ש עג, ד. שערי תשובה ח\"ב כו, ב. סה\"מ תרל\"ב ח\"א ע' קיח [ובהמ\"מ שם]. תרל\"ג ח\"ב שם ע' תכא ואילך [ובהנסמן שם בתחילת המאמר]."],["1349","41","<b>ודברתם אל הסלע. . שנה עליו פרק אחד</b>: נתבאר בסה\"מ תרכ\"ו ע' קנ ואילך. תרל\"ב ח\"ב ע' שעח ואילך [ובהנסמן שם בתחילת המאמר].\n\n<b>יג</b>  <b>בעליית התחתון לגבי העליון כמה עקולי ופשורי איכא</b>: בגוכי\"ק נוסף כאן: אבל בירידת העליון לגבי התחתון יש הרבה מונעים שלא נזדכך עדיין ועוד כמה מניעות. אך בהמשך והחרים תרל\"א הנדפס בכת\"י הר\"ש סופר הוקף כ\"ז בחצאי עיגול."]]],[2000510413,"שזהו השפעה בגשמיות כו'. וכן מצינו ברשב\"י שכשהיו צריכים לגשם דרש להם דרוש ע\"פ הנה מה טוב<sup data-n=\"1350\">42</sup> ומה נעים שבת אחים גם יחד ירד גשם כו', כמ\"ש בזח\"ג דנ\"ט ע\"ב. ולכן אמרו עליו מאן פני האדון להיותו אדון מושל בכח תורתו להמשיך גם בחי' השפעות הגשמיות ע\"י התו' מלמעלמ\"ט.\n<b></b>[נג)] ועפ\"ז יובן ג\"כ ענין הסתלקותו שהי' בל\"ג בעומר שהוא ספי' הוד שבהוד, כי הנה נודע שבעת הסתלקותו השיג שרש נפשו כמו מרע\"ה שהשיג בעת הסתלקותו בחי' שער הנו\"ן דבינה שכל ימי חייו לא השיג רק בחי' מ\"ט שערי בינה, ובעת הסתלקותו השיג בחי' שער הנו\"ן, ולכן לעליונים נדמה להם למטה ולתחתונים נדמה להם למעלה, ואם כי שער החמשים הוא רק המחבר חו\"ב, אבל באמת ה\"ה גבוה משניהם כמשנ\"ת ביאור ד\"ז בד\"ה את שבתותי תשמורו (ך\"ב)<sup data-n=\"1351\">43</sup> בענין נתיב הל\"ב דחכ' ושער הנו\"ן שז\"ע נתיב לא ידעו עיט ולא שזפתו עין איה, והיינו בחי' התגלות עתיק שבבינה. וכן יובן שרשב\"י בעת הסתלקותו השיג שרש דשרש נפשו לכן הי' זמן הסתלקותו בל\"ג בעומר ספי' הוד שבהוד. והענין הוא דכתי' ויברכו את שם כבודך שבבחי' שם שייך לשון ברכה, אבל בעצמותו ית' אינו שייך לשון ברכה כלל כ\"א בחי' הודאה<sup data-n=\"1352\">44</sup> לבד כמ\"ש מודים אנחנו לך, שלך היינו לבחי' עצמותו אינו שייך כ\"א בחי' הודאה, ונודע ענין ההודאה אינו שייך כ\"א על דבר שאינו מבין, כי אם מבין הדבר אינו נופל לשון הודאה ע\"ז, כ\"א ענין ההודאה הוא שהגם שע\"פ השגתו והבנתו וסברותיו הענין כך הוא, מ\"מ ה\"ה מודה לזולתו שאומר שלא כן הוא כאשר הי' בדעתו קודם, וכענין ומודים חכמים לר\"מ, הגם כי שם י\"ל<sup data-n=\"1353\">45</sup> שגם ע\"פ סברתם י\"ל כן, מ\"מ מי הביא להם שיאמרו כך מפני כי ר\"מ אמר היפוכם והם הודו לו, ואחר כל המשל אינו דומה להנמשל, להיות כי שם הוא בפרטיות ד\"ת שאמרו עלי' לא בשמים היא, וידיעת ד\"ת הוא בין תבין כו', אמנם בדבר אשר זהו למעלה מהשגה היינו למעלה מהגבלת השכל וההשכלה, א\"א כ\"א בדרך הודאה בלבד כו'. וזהו ענין מודים אנחנו לך שבעצמותו אינו שייך כ\"א לשון הודאה בלבד ולא השגה, וא\"כ ענין ספי' הוד הוא בחי' הודאה שזה שייך כ\"א בעצמותו בלבד, שהרי בבחי' שמות עד\"מ למה ענין ההודאה הלא בזה יכול להיות השגה. וא\"כ הוד שבהוד הוא כענין הודאה דהודאה, והיינו כי להיות הענין רחוק כ\"כ מהשגה עד שמעט לנו לומר שאנו מודים לו כ\"א בדרך הודאה להודאה כו', והיינו כי להיותו ממוצע בין בחי' מ\"ה שבחכ' להוביל בחי' זו לבחי' המדות שהם הנחלי' שהולכי' אל הים הוא בחי' והאיתנים מוסדי ארץ כנ\"ל, ולהיות כן הרי נתעלה בבחי' שם שעל בחי' זו נא' והחכ' מאין",[["1350","42","<b>ברשב\"י. . דרש. . ע\"פ הנה מה טוב</b>: נת' בארוכה בסה\"מ תרכ\"ז ע' רצא ואילך. וש\"נ."],["1351","43","<b>כמשנ\"ת ביאור ד\"ז בד\"ה את שבתותי תשמורו (ך\"ב)</b>: נמצא בבוך 1120 [הכולל מאמרי הצ\"צ מהשנים תרכ\"ב-כ\"ה] קלג, א. ונדפס באוה\"ת ויקרא (כרך ג) ע' תתקטו. וראה גם שם (כרך ד) ע' א'קלט."],["1352","44","<b>בל\"ג בעומר ספי' הוד שבהוד. . בחי' הודאה</b>: ראה בארוכה סידור עם דא\"ח דש, א ואילך. שו, ג ואילך. אוה\"ת ויקרא (כרך ד) ע' א'קיט. ועוד."],["1353","45","<b>וכענין מודים חכמים לר\"מ הגם כי שם י\"ל</b>: ראה גם סה\"מ תרל\"ב ח\"ב ע' תל [בשולי הגליון]."]]],[2000510414,"תמצא שלזה בא ע\"י עבודתו, ולכן בעת הסתלקותו בא להודות לבחי' עצמותו כו', ולכן נסתלק בל\"ג בעומר בחי' הודאה שבהודאה כו'. ובכ\"ז יובן ענין מ\"ש משכיל לאיתן האזרחי, פי' האזרחי נת' לעיל שזהו ענין מלשון אזרח הארץ תושב בחי' שם ע\"ב. אמנם עוד יש פי' האזרחי מל' כל האזרח כל מה שעתיד לזרוח, והיינו כי משה הי' גואל ראשון וגם הוא יהי' גואל אחרון, ורשב\"י שהי' ג\"כ נשמה מעלמא דאתכסיא כמ\"ש בד\"ה לויתן זה בפ' שמיני בלק\"ת<sup data-n=\"1354\">46</sup> לכן שייך עליו ג\"כ בחי' זו שכל מה שעתיד לזרוח. וזהו משכיל לבחי' איתן שהוא בעצם קשה לבוא לידי גילוי, ולא כמו שהוא עכשיו עדיין כ\"א כמו שיהי' לע\"ל, והארה מבחי' זו נמשך גם עכשיו בהממוצע שבכל דור ודור, ולכן רשב\"י שהי' ממוצע להמשיך אור התורה להתנאים בבחי' סתים וגליא שזהו ב' בחי' שבממוצע שייך עליו ענין משכיל לאיתן האזרחי.",[["1354","46","<b>בד\"ה לויתן זה בפ' שמיני בלק\"ת</b>: דף יח, א. וראה מ\"ש ע\"ז לקמן ע' שסט ד\"ה ולהבין בתוס' ביאור כו' בענין והאיתנים."]]],[2000510415,"<h3>[אם בחוקותי]</h3>\n<b></b><b>[ד\"ה אם בחוקתי תלכו<sup data-n=\"1355\">1</sup>] </b>\nואמנם כו' איתן כו' אם בחוקותי כו'\nבהו\"ב\nבס\"ד. פ' בהר בחוקתי.\n<b></b>[נד)] ואמנם ענין בחי' איתן<sup data-n=\"1356\">2</sup> זה הגם כי הוא כמשמעו קשה, מ\"מ כדי שיומשך מבחי' אוא\"ס ב\"ה בחי' איתן זה שה\"ה ג\"כ בחי' הגבלה שהרי הוא קשה, ואם כי זהו מחמת איידי דטריד הוא בחי' הביטול דמ\"ה לבחי' אין דכתר לכן לא פליט הוא בחי' ההשפעה ה\"ז עצמו הוא בחי' הגבלה.\n<b>ויובן</b> בהקדם ענין מ\"ש אם בחוקתי תלכו וגו' ונתתי גשמיכם בעתם ונתנה הארץ יבולה ועץ השדה יתן פריו, ופי' רש\"י וכ\"ה בילקוט ובמדרש אם בחוקתי",[["1355","1","<b>ואמנם. . אם בחוקתי תלכו</b>: מאמר זה הוא מאמר השמיני שבהמשך והחרים תרל\"א\". חלק מהמאמר מיוסד על ד\"ה ענין קי\"ס באוה\"ת בשלח ע' תקעב ואילך. וחלק מהמאמר הוא מד\"ה רכב אלקים בסה\"מ תרכ\"ח ע' קסו ואילך.\nלהתחלת וסיום המאמר ראה ד\"ה אם בחוקתי להצ\"צ תרט\"ז הנחה בגוכי\"ק כ\"ק אדמו\"ר מהר\"ש (כת\"י 1029 צז, א). ובשינויים בסה\"מ תרכ\"ו ע' ק-קא. תר\"ל ע' קמה-ו. קנג-ד. וראה גם אוה\"ת ויקרא (כרך ב) ע' קצה-ו. סה\"מ עטר\"ת ע' תכט.\nלכללות המאמר ראה לקמן ד\"ה והנה כמו שכדי שיומשך המשכת החכ' שהוא רישומי דברים ממאמר זה.\n[בהמשך והחרים הנדפס מכת\"י הר\"ש סופר התחלת מאמר זה הוא בפיסקא האחרונה של המאמר הקודם: ובכ\"ז יובן ענין מ\"ש משכיל לאיתן האזרחי. אך בגוכי\"ק אדמו\"ר מהר\"ש נסמן שכאן צ\"ל התחלת המאמר]."],["1356","2","<b>ואמנם ענין בחי' איתן</b>: בגוכי\"ק נרשם בתחילה התחלת המאמר: ולהבין בתוס' ביאור ענין בחי' איתן, ואח\"כ העביר ע\"ז הקולמוס והתחיל את המאמר כבפנים."]]],[2000510416,"תלכו יכול זה קיום המצות, כשהוא אומר ואת מצותי תשמורו וגו' הרי קיום המצות אמור, הא מה אני מקיים אם בחוקתי תלכו שתהיו עמלים בתורה. ובילקוט בחוקתי רמז תרע\"א מלמד שנתאוה המקום שיהיו ישראל עמלים בתורה שנא' לו עמי שומע לי ישראל בדרכי יהלכו, וצ\"ל מהו ענין שנתאוה המקום שיהיו ישראל עמלים בתורה. וגם צ\"ל מ\"ש אח\"כ ונתתי גשמיכם כו' שזהו התשלום שכר על מה שיהיו ישראל עמלים בתורה, שלכאו' יפלא שהתשלום גמול עבור העמל בתורה יהי' דבר פשוט כזה ירידת גשמים בעתם ופרי הארץ ופרי העץ, שלכאו' הול\"ל תשלום גמול יהי' בחי' השגת הרוחניות<sup data-n=\"1357\">3</sup> שיהי' גילוי כבוד ה' כמ\"ש לע\"ל ונגלה כבוד ה' וראו כל בשר כו', ומהו ענין דברים אלו הגשמיי' שיהיו עולים לתשלום גמול ושכר עבור לימוד התורה, ועוד שיהיו ישראל עמלים בתורה כו'.\n<b>הנה</b> כתי' פקדת ארץ ותשוקקיה וגו' פלג אלקי' מלא מים תכין דגנם וגו' תלמי' רוה נחת, פי' הפשוט שע\"י פקידת הארץ בגשם עי\"ז יהי' נכון דגנם וגם התלמים יתרוו נחת כמ\"ש רש\"י. ובפדר\"א סי' ה' הובא בבחיי פ' עקב ע\"פ ועצר את השמים, שבזמן שהארץ שותת ממי אוקיינוס ומתהום שעז\"נ תהום אל תהום קורא לקול צנוריך, אז היא כאלמנה שמזנת כו', ובזמן שהקב\"ה חפץ לשלוח ברכה אז היא שותה ממים העליונים, וכ\"א במד\"ר קורא א' יש בשמים שממנה הגשמים יורדים ובתענית דף ח' ב' תנא כמין קובה יש ברקיע שממנה גשמים יוצאין. ולכאו' יפלא מהו הנפ\"מ אם היא שותת ממי אוקיינוס או ממים העליונים, הלא אינה צריכה כי אם למים, ומאי נפ\"מ אם מים אלו או אלו.\n<b></b>[נה)] אך הענין יובן בהקדם מ\"ש וצדקה כנחל איתן, מהו ענין הצדקה וגודל מעלתה כ\"כ עד שתהי' כנחל איתן כו'. אך הענין הוא דהנה נת\"ל בענין איתן שהוא כמשמעו קשה בחי' העדר ההשפעה, עד שבכדי להמשיך בחי' איתן זה להיות בבחי' נחל הוא בחי' כל הנחלים הולכים אל הים בחי' והאיתנים מוסדי ארץ, זהו ע\"י ממוצע דרשב\"י שהי' מבחי' עלמא דאתכסיא, כמו במשה דכתי' בי' כי מן המים משיתיהו, ולכן ע\"י תורתו פעל השפעות גשמי' כמו שהי' הציווי למשה ודברתם אל הסלע רק שחטא בזה כמ\"ש יען לא האמנתם בי להקדישני, משמע שאם היו מדברים אל הסלע והיינו שנה עליו פרק אחד היו מקדישי', והיינו שהי' נמשך הגשמי' מבחי' חכ' שנק' קדש, וכן רשב\"י כו', וכמ\"ש לעיל באריכות. אמנם כ\"ז הוא היותו ממוצע בין בחי' איתן לתנאים שנק' איתנים סמוכים איש מפי איש עד משה, וע\"י התורה. אך הנה הבעלי עסקים שא\"א לעסוק בתורה, ומחמת ריבוי הסתר העולם נדמה להם שאין להם פנאי כלל, לכן בכדי שגם הם ימשיכו בחי' איתן עז\"נ וצדקה כנחל איתן.",[["1357","3","<b>ונתתי גשמיכם. . שלכאו'. . תשלום גמול יהי' בחי' השגת הרוחניות</b>: ראה עד\"ז בפי' האברבנאל ר\"פ בחוקותי הובא בלקו\"ש חל\"ז ע' 79 ואילך (עיי\"ש). וראה גם אוה\"ת בחוקתי (כרך ב) ע' קצז."]]],[2000510417,"<b>והענין</b> דהנה הגם שנת\"ל בענין איתן שהוא בחי' מ\"ה דחכ' שלכן הוא כמשמעו קשה בחי' העדר ההשפעה כנ\"ל, מ\"מ הנה כתי' והחכ' מאין תמצא שמציאות התהוות החכמה מאין דכתר ה\"ה בדרך מציאה<sup data-n=\"1358\">4</sup>, וכמו מי שהוא מצא מציאה שאינו יודע מאין הוא בא, שהרי אם יודע בעליה אין זה בכלל מציאה כלל, רק מפני שיודע שזהו של חבירו צריך להשיבו, עד\"מ אם ראה ממי נפל צריך להחזיר לו כמ\"ש בשו\"ע חו\"מ הל' אבידה ומציאה סי' רס\"ב ס\"ד, ושם מציאה שחייב להכריז הוא שמצא ואינו יודע של מי הוא, וכמשנ\"ת פרטי הנצרכי' למציאה בריש הל' אבידה ומציאה סי' רנ\"ט ס\"ב. ועד\"ז יובן בענין מציאות התהוות החכ' מבחי' אין דכתר, זהו ע\"ד מציאת המציאה הנ\"ל. ונמצא מובן כי אין ערוך כלל וכלל החכ' והאצי' לגבי א\"ס המאציל, שהרי אין דרך להתהוות החכמה כ\"א ע\"ד שתמצא מאין כמציאה כו', שהרי באמת העשי' לגבי האצי' הוא יותר חשוב ערך מאצי' לגבי א\"ס כמ\"ש בת\"א בד\"ה פתח אלי'<sup data-n=\"1359\">5</sup>, שהרי בכדי להיות בי\"ע צ\"ל תחלה אצי', ונמצא כי אצי' היא מ\"מ הקדמה לבי\"ע, אבל בכדי להיות אצי' זהו ע\"י צמצום ומקום פנוי. וביאור הענין דהנה כתי' בראשית ברא אלקי', פי' בראשית ב' בחי' ראשית ח\"ע וח\"ת וגם אפי' בחי' ח\"ע היא ג\"כ ברא אלקי', פי' שגם החכ' נחשב בריאה לגבי בחי' אלקי' דכתר, וכמ\"ש אנכי ה' אלקיך אנכי מי שאנכי בחי' כתר הוא אלקיך, ולגבי בחי' אלקי' זה החכ' שהוא ראשית האצי' נחשב לבחי' בריאה כמו בי\"ע שהם בריאה יש מאין. וי\"ל פי' כמו שבי\"ע הם נבראי' מבחי' אין, כן אצי' הוא נאצל מבחי' אין דכתר שנק' ג\"כ אלקים. ויותר י\"ל שאצי' לגבי אלקות נחשב לבריאה כמו בי\"ע. וז\"ע בורא קדושים ישתבח שמך, שהקדושים בכ\"י יהללוך סלה וכל העליות הוא בבחי' שמך לבד, וזהו אשר שם שמת בארץ א\"ת שמת אלא שמות, כמ\"ש מזה בלק\"ת פ' בהר בד\"ה את שבתותי תשמורו<sup data-n=\"1360\">6</sup> באורך יעו\"ש.\n<b></b>[נו)] והענין הוא דהנה אצי' הוא מל' ויאצל מן הרוח דכתי' גבי משה, הנה גם לאחר שנאצל הרוח מן משה וניתן על ע' איש הזקנים מ\"מ לא הי' משה חסר כלום<sup data-n=\"1361\">7</sup>, וכמ\"ש רש\"י למה משה דומה באותו שעה כנר המונח ע\"ג המנורה<sup data-n=\"1362\">8</sup> והכל מדליקין ממנה ואיננה חסר כלום, וא\"כ ענין אצילות הרוח דמשה הי' רק כמדליק נר מנר שאינה חסר כלום, וממילא ההארה הנאצל הוא הארה בעלמא, שאם הי' איזה תפיסות הי' נחסר ממקום אצילתן, אלא זהו כמשל הריח כשמריחין",[["1358","4","<b>והחכ' מאין תמצא. . מאין דכתר ה\"ה בדרך מציאה</b>: ראה תו\"א מג\"א צ, ב. לקו\"ת תזריע כב, ג. בהר מא, ד. ואתחנן ב, סע\"ב. דרושים לר\"ה נה, א. שה\"ש מא, ד. ובכ\"מ."],["1359","5","<b>בת\"א בד\"ה פתח אלי'</b>: דף יד, א ואילך."],["1360","6","<b>בלק\"ת פ' בהר בד\"ה את שבתותי תשמורו</b>: דף מא, ב, ואילך."],["1361","7","<b>אצי' הוא מל' ויאצל. . מ\"מ לא הי' משה חסר כלום</b>: ראה תו\"א בראשית ג, א. שם יד, א. מאמרי אדה\"ז תקס\"ג ח\"א ע' רצב. אוה\"ת ואתחנן ע' קפו ואילך. סה\"מ תרל\"ב ח\"א ע' מב. רד. לעיל ד\"ה ראה נתתיך."],["1362","8","<b>שנאצל הרוח מן משה. . כנר המונח ע\"ג המנורה</b>: ראה בארוכה לקו\"ש ח\"ח ע' 75 ואילך."]]],[2000510418,"ממנו זמן רב ומ\"מ אינו חסר כלום, וכמשנ\"ת מזה במ\"א<sup data-n=\"1363\">9</sup>. ועד\"ז יובן אצי' העליון שעם שנאצלו ע\"ס, מ\"מ גם לאחר אצי' אינו שייך לומר שום שינוי כלל וכלל, ואני הוי' לא שניתי כלל מקודם האצי' לאחר האצי' וכמ\"ש בעה\"ק ח\"א פ\"ג שמפרש עד שלא נברא העולם על עולם האצי'<sup data-n=\"1364\">10</sup>, והיינו כי אצי' הוא רק הארה מועטת מאד, וענין האצי' הוא גילוי ההארה זו מבחי' ההעלם אל הגילוי. והגם כי איהו וחיוהי חד ואיהו וגרמוהי חד<sup data-n=\"1365\">11</sup> בהון, ואצי' הוא אלקות, מ\"מ למה אמרו איהו וחיוהי חד שאם גם קודם האצי' הוא כמו האצי' א\"צ לומר שהן חד, וגם אם נאמר שהם שוין א\"כ מה נאצל, אלא שזה אמת ויציב שבאצי' איהו וחיוהי חד ואיהו וגרמוהי חד, והיינו שכמו שבחי' איהו מתייחד עם בחי' גרמוהי להיות חד בהון לברוא בהן וע\"י בחי' יש מאין כן בחי' איהו מתייחד עם חיוהי עוד ביחוד נפלא יותר, שלכן לא נאמר איהו וחיוהי וגרמוהי חד אלא אמרו בכל אחד מהן לשון חד בפ\"ע שזהו להורות שהיחוד שמתייחד בחי' איהו עם חיוהי הוא יחוד היותר נעלה ונפלא ביתר על היחוד שמתייחד עם גרמוהי, ומ\"מ גם עם גרמוהי מתייחד להיות חד בהון, כן נבין שעם שא\"ס שלפני האצי' אינו בערך האצי' כלל, מ\"מ בחי' איהו שלפני האצי' מתייחד ביחוד נפלא עם בחי' חיוהי כו', ומ\"מ לגבי בחי' איהו עצמו שלפני האצי' הנה האצי' היא רק הארה מועטת שאין בערך כלל עד שנוכל לומר שאין ערוך לך כלל, היינו בחי' האצי' נגד בחי' א\"ס שלפני האצי' וכנ\"ל בשם הת\"א בד\"ה פתח אלי', וע' מענין איהו עצמו בביאור על פך\"ג שבסש\"ב (רי\"ג)<sup data-n=\"1366\">12</sup> בענין איהו וחיוהי חד ואיהו וגרמוהי חד. ולפ\"ז בכדי שיהי' התהוות האצי' מא\"ס המאציל זהו ע\"י ממוצע, והוא בחי' הכתר שהוא ממוצע בין א\"ס המאציל ובין אצי' העליון, וכמו שבממוצע צ\"ל ב' בחי', והיינו מה שהוא מסוף בחי' המאציל ומה שהוא בערך האצי' וזהו בחי' עת\"י ואריך אנפין, עת\"י הוא בחי' המתנשא מימות עולם, מלשון המעתיק הרים שנעתק ונבדל גם מהיות עדיין מקור לאצי' כ\"א הוא מעלים בתוכו הארת הא\"ס, וזהו בחי' ים וכמו ים סוף מעלים בתוכו הארת האצי' בכדי שיוכל להיות בחי' ארץ, היינו בחי' המל' שנעשה כתר ועתיק לבריאה וההעלם הוא סיבה לגילוי כנ\"ל באורך, כן יובן ג\"כ בבחי' עת\"י שלהיותו נעתק ונבדל ומעלים בתוכו אור הא\"ס ה\"ה סיבה שיוכל להיות בחי' אריך אנפין שהוא מקור לאצי', ולכן דעת הרמ\"ז שאצי' נחשב מבחי' חכ' דאריך והיינו להיותו מקור וערך לאצי', ובחי' זו נק' לגבי אצי' בשם ארץ.",[["1363","9","<b>כמשל הריח. . אינו חסר כלום וכמשנ\"ת מזה במ\"א</b>: ראה לקו\"ת מסעי צ, סע\"ד. שה\"ש לג, א. סידור עם דא\"ח כח, ג."],["1364","10","<b>וכמ\"ש בעה\"ק. . שמפרש עד שלא נברא העולם על עולם האצי'</b>: ראה גם סה\"מ תרל\"ב ח\"א ע' כ. [וש\"נ]. סה\"מ תרמ\"ד (הוצאת תשס\"ג) ע' שמו. וש\"נ."],["1365","11","<b>לא נא' איהו וחיוהי וגרמוהי חד אלא אמרו בכ\"א מהן לשון חד בפ\"ע</b>: ראה בארוכה המשך מים רבים תרל\"ו ע' לז. לט ואילך. קסה. המשך וככה תרל\"ז פע\"ו (ע' קכא). המשך תער\"ב ח\"א ע' שא ואילך. שסו. סה\"מ תשט\"ז ע' 510 ואילך."],["1366","12","<b>בביאור על פך\"ג שבסש\"ב (רי\"ג)</b>: נדפס בס' ליקוט פירושים ומ\"מ (להר\"א חיטריק) לתניא פכ\"ג ע' תמו [נמצא בכת\"י 2111 קצג, א, בכותרת: נא' כ\"ד טבת תרי\"ג]. וראה גם: שם ע' תלו ואילך. מאמרי אדהצ\"צ תרט\"ו ע' נט ואילך. סה ואילך. ריב ואילך. סה\"מ תרל\"ג ח\"ב ע' שמג ואילך. תרנ\"ג ע' רכד ואילך."]]],[2000510419,"<b>וזהו</b> וצדקה כנחל איתן, שהבעלי עסקים שאין להם פנאי ללמוד כ\"כ, הנה כשמקיימים מצות לימוד פרק אחד שחרית ופרק אחד ערבית עכ\"פ שזהו חיוב הבעלי עסקים ג\"כ, אז בכדי שגם הוא ימשיך בחי' איתן זהו ע\"י הצדקה, והיינו כי כל המצות נק' בשם צדקה כמ\"ש וצדקה תהי' לנו<sup data-n=\"1367\">13</sup> כי נשמור לעשות את כל המצוה, ובפרט היא מצות הצדקה שנותן לזולתו מיגיע כפו שנותן נפשו עלי', ונודע כי שיעור הצדקה הוא חומש הריוח לכן ע\"י חומש זה מגיע לבחי' והחמישית לפרעה, והיינו כי ארבע הידות יהי' לכם זהו ד' פרצופי' דאצי', והחמישית זהו פרצוף ה' פרצוף הכתר כו' ועי\"ז הם ממשיכים עוד מבחי' גבוה יותר מהבעלי תורה, והיינו כי החיצוני' שמבחי' גבוה הוא גבוה יותר מבחי' הפנימי' של הנמוך במדריגה. וזהו וצדקה כנחל איתן שע\"י הצדקה יכולים להמשיך בחי' הנחל שנמשך ע\"י נחל זה אל בחי' איתן כו'.\n<b></b>[נז)] והנה באמת יש בחי' ים וארץ עוד גבוה יותר<sup data-n=\"1368\">14</sup>, והיינו שאצי' בכלל הוא רק בחי' אדם דעשי', וכתר (או עקודים) נק' אדם דיצי', וא\"ק אדם דבריאה, ואיתא בזהר\"ק<sup data-n=\"1369\">15</sup> דט\"ו שיש כדוגמת עתיק לעילא מגולגלתא דא\"ק וזהו בחי' אצי' דכלליות, וא\"כ כמו שמל' דאצי' יש בו בחי' ים וארץ, כן אצי' דכלליות בבחי' ב\"ן דבחי' עתיק זה שלעילא מגולגלתא דא\"ק יש ג\"כ ב' בחי' ים וארץ, וע' מענין מ\"ה וב\"ן דעתיק בד\"ה אשה כי תזריע בספר ויקרא<sup data-n=\"1370\">16</sup>, והיינו שבשרש הכל הנה הק\"ו הוא בחי' ממכ\"ע, והעיגול שלפני הקו הוא סוכ\"ע, והצמצום הוא בחי' ים המעלים אור הא\"ס וכמ\"ש בע\"ח סילק אורו הגדול על הצד שזהו ע\"י הצמצום כו' שהוא בכלליות בחי' ים סוף המעלים וכונס בתוכו הא\"ס כו', ואם כי אינו דומה ע\"ד העלם המל' או בחי' עת\"י כנ\"ל לענין להעלים בתוכו, מ\"מ הנה הוא מעלים שלכן יתכן לקרותו בשם ים. וזהו עד שלא נבה\"ע הי' הוא ושמו בלבד, פי' שמו הוא ג\"כ שם הוי' רק זהו בחי' שמו הגדול כו', וע' בהגהות לד\"ה ואלה שמות שבת\"א<sup data-n=\"1371\">17</sup>, ובבחי' שם הוי' יש ב' בחי', בחי' שם הוי' הנראה כמ\"ש באברהם לה' הנראה אליו, ובחי' שם הוי' המסתיר<sup data-n=\"1372\">18</sup> כמ\"ש וחכיתי לה' המסתיר פניו שגם זה הוא משם הוי', כן עד\"ז יש בבחי' שמו הגדול כו' כח המעלים וכח הגילוי, ושניהם שמו הגדול הוי' שם העצם, וזהו בחי' ים וארץ כו'.",[["1367","13","<b>כל המצות נק' בשם צדקה כמ\"ש וצדקה תהי' לנו</b>: ראה תניא פל\"ז (מח, ב). תו\"א מקץ לח, ג. מב, ג. לקו\"ת דברים א, ד. שה\"ש מד, ג. סה\"מ מלוקט ח\"א ע' רח. וש\"נ."],["1368","14","<b>והנה באמת יש בחי' ים וארץ עוד גבוה יותר</b>: בהבא לקמן בפיסקא זו ראה ד\"ה ענין קי\"ס באוה\"ת בשלח שם ע' תקעב-ג. ד\"ה בוקע ים בסה\"מ תרכ\"ח ע' קמא. ד\"ה ויט משה בסה\"מ תרל\"ב ח\"א ע' קלז."],["1369","15","<b>בזהר\"ק</b>: בס' זהר הרקיע על ס' הזהר."],["1370","16","<b>וע' מענין מ\"ה וב\"ן דעתיק בד\"ה אשה כי תזריע בספר ויקרא</b>: אוה\"ת ויקרא (כרך ב) ע' תק. וראה גם סה\"מ תרכ\"ו ע' עז-ח."],["1371","17","<b>וע' בהגהות לד\"ה ואלה שמות שבת\"א</b>: אוה\"ת שמות ע' יא. ובארוכה שם ע' קג ואילך."],["1372","18","<b>שם הוי' יש ב' בחי'. . הוי' הנראה. . הוי' המסתיר</b>: ראה גם סה\"מ תרכ\"ז ע' שפה. תרכ\"ט ע' קסג. תרל\"ב ח\"א ס\"ע רעו."]]],[2000510420,"<b></b>[נח)] ולהבין הענין צ\"ל שם א\"ק מהו<sup data-n=\"1373\">19</sup>, שלכאורה הוא מורכב מב' ענינים שונים ונגדיים זל\"ז, ששם אדם אינו נופל אלא על הנברא מאין ליש כמ\"ש ויברא אלקי' את האדם בצלמו, ושם קדמון פירושו היפוכו שהוא קדמון ולא נברא, שלכל נברא בהכרח שיהי' הבורא אותו קדם לו, משא\"כ קדמון, ולכן א\"ס ב\"ה הוא קדמון לכל הקדומים שהכל נמצאים מאתו ית' שממנו ית' נמצאו כל הנמצאים, ובתי' א\"ק הרכיבו ב' הבחי' יחד, וממ\"נ אם הוא בחי' אדם אינו קדמון ואם הוא קדמון אינו אדם. אך הענין הוא שצ\"ל מה\"ע האדם, דהנה האדם הוא נחלק לבחי' בפ\"ע בהד' בחי' דצח\"מ, והגם כי לכאו' יתרון האדם על הבהמה להיותו בר שכל וחכים להבין דבר, משא\"כ הבהמה. אך באמת אינו כן, שהרי גם הבהמה יש לה קצת שכל שהרי תזהר לבלי תנזק באחת הבורות והפחות והאבנים וכדומה, או תמשך למקום אשר המאכל שם שזהו קצת השכלה, ומה גם כי השועל שהוא פקח שבחיות ואנו רואים שיש לו השכלה בפרטי' שונים יותר מהאדם, שהרי כשירצה האדם ללוכדו הנה הוא מגדר כל הדרכים לפניו לבלי יוכל להנצל מאתו, ועכ\"ז הנה הוא ממציא לו דרך איך לברוח מאתו, ונמצא כי השכלת השועל מרובה יותר, שהאדם בשכלו לא בא ע\"ז מה שהמציא השועל דרך איך לברוח, ועכ\"ז הנה השועל בכלל וסוג מין החי יחשב, ומחמת השכלתו לא יצא מכלל בעלי החי להיות נמנה בסוג אחר, רק הוא נק' פקח שבחיות, שגם שם זה מורה שיש ענין השכל והשכלה בבעלי החי רק שהשועל הוא הפקח שבהם כו'. אלא עיקר מעלת האדם הוא להיותו מדבר<sup data-n=\"1374\">20</sup>, משא\"כ כל הבעלי חי אפי' הפקח שבהם, או אפי' הארי שהוא מלך שבחיות, עכ\"ז לא נמצא הדבור כלל, ולכן תרגמו האונקלוס ותרגום יונתן ע\"פ ויהי האדם לנפש חיה לרוח ממללא מה שלא תרגמו כן ע\"פ תוצא הארץ נפש חי', היינו להיות כי נפש חיה שבאדם יתרונו על נפש החיה שבבהמה וחי' במה שהוא מדבר, ולכן תרגמו לרוח ממללא בחי' הדבור, והיינו מפני כי כל שורש ומקור בחי' הבע\"ח הוא מבחי' החכ' כמ\"ש והחכ' תחי', שהחכ' הנה הוא בחי' שרש ומקור הראשון לכל בחי' הבעלי החי, אבל שורש דיבור האדם הוא מבחי' מדבר בחי' הכתר כנודע<sup data-n=\"1375\">21</sup>, וזהו בחי' יתרון האדם על הבהמה וחי' במה שהוא מדבר כו'.\n<b></b>[נט)] והנה אנו רואים שכל עיקר פעולת הדיבור הוא שמגלה לזולתו העלם הצפון בלבו או במחשבתו ושכלו, שבלא הדבור לא יוכל זולתו להבין מה",[["1373","19","<b>ולהבין הענין צ\"ל שם א\"ק מהו</b>: הבא לקמן (עד פיסקא: ומ\"מ לגבי א\"ס) הוא מד\"ה רכב אלקים בסה\"מ תרכ\"ח שם ע' קסו ואילך. ונמצא בשינויים בסה\"מ תרכ\"ח שם ע' צד ואילך. תרל\"ג ח\"ב ע' תקט ואילך."],["1374","20","<b>עיקר מעלת האדם הוא להיותו מדבר</b>: ראה נוסף למקומות שנסמנו בהערה שלפנ\"ז אוה\"ת בשלח ע' שצא. ויקרא (כרך ג) ע' תתכא. לעיל ע' פג."],["1375","21","<b>שורש דיבור האדם. . בחי' הכתר כנודע</b>: ראה הוספות לתו\"א יתרו קט, א. ובארוכה מאמרי אדה\"ז תקס\"ז ע' יד. אוה\"ת חנוכה (כרך ה) תתקמט, א. תזריע (כרך ב) ע' תקכד. סה\"מ תרל\"ה ח\"א ע' ר. וע' רח."]]],[2000510421,"שהשכיל בשכלו או מה שמחשב במחשבתו או מה שאהוב בלבו, וע\"י אמצעי' הדבור יוכל לגלות לזולתו מה שהוא צפון ונעלם מעין כל חי, משא\"כ ע\"י המחשבה, שהרי כשיחשוב כל היום וכל הלילה לא יבין זולתו כלל מה הוא מחשב, כי רק הדבור מגלה לזולתו כנ\"ל ולא המחשבה, רק שפעולת המח' לגבי עצמו<sup data-n=\"1376\">22</sup> הוא כמו הדיבור לגבי זולתו. ועד\"מ כשמשכיל איזה השכלה חדשה שמתחלה נעשה אצלו בחי' בריקת וסקירת השכל, שבחי' ברק המבריק הנמשך מבחי' משכיל לבחי' השכל הנה להיותו דק עדיין הוא נעלם גם מאתו, כי אינו רק שנפתח מקורו להמציא איזה ענין חדש אבל עדיין לא בא בבחי' השגה והבנה<sup data-n=\"1377\">23</sup> כלל, ואח\"כ כשבא בבחי' השגה והבנה להבין עומק הענין וההשכלה על בוריו הנה זה ע\"י לבוש המח' שמתלבש השכל בבחי' לבוש המח' עד שמשיגו בהבנת הדברים כל דבר על אופנו. ונמצא כי ע\"י אמצעית המח' בא ההשכלה לידי השגה והבנה להאדם עצמו שהשכיל השכלה זו ובלעדה לא יוכל גם הממציא ההשכלה להבין את ההשכלה, והרי המח' הוא כמו ממוצע בין כח המבריק ההשכלה לבחי' ההשגה והבנה שנמשך מבחי' הבינה, הגם שבאמת אינה ממוצע כ\"א לבוש, אך ע\"י אמצעית לבוש זה בא ההשכלה לידי השגה והבנה להאדם שהשכילה, ונמצא כי פעולת המחשבה לגבי עצמו הוא כמו הדיבור לגבי זולתו כו'. אמנם הנה ממחשבת האדם לא יתהוה כלום, שהרי אם יחשוב כל היום בענין התהוות איזה דבר לא יתהוה מזה כלום, כ\"א מדבור האדם כמו דבר מלך שלטון יוכל להתהוות איזה דבר, וג\"ז רק יש מיש ולא יש מאין, וכמארז\"ל שאם מתכנשין כל באי עולם אינם יכולים לברוא אפי' כנף יתוש א'. אבל הוא ית' הממציא כל הנמצאים כתיב בי' כי לא מחשבותי מחשבותיכם<sup data-n=\"1378\">24</sup> שממחשבת האדם לא יתהוה כלום, אבל אצלו ית' תיכף ומיד כשעלה ברצונו הפשוט להטיב לברואיו הנה ממח' זו נתהווה כל התהוות הנבראי' וכמ\"ש בזהר שבמח' א' נבראו כל הנבראי' והיינו בחי' מח' הקדומה דא\"ק וכמ\"ש בע\"ח כשעלה ברצונו הפשוט כו', וז\"ע מארז\"ל בראשית נמי מאמר הוא היינו בחי' מאמר הכללי<sup data-n=\"1379\">25</sup> שכולל כל עשרה מאמרות, והיינו שבחי' מחשבה זו מגלה העלם העצמי לבוא בבחי' גילוי, וכ\"ז בעצמותו עדיין, וכמשנת\"ל שפעולת המח' אצל האדם לגבי עצמו כמו פעולת הדבור לגבי זולתו, ועד\"ז יובן בבחי' אוא\"ס ב\"ה שמה שעלה ברצונו הפשוט הנה ע\"י בחי' מחשבה זו נתהוה הכל מאתו ית'. אמנם הנה כ\"ז הוא לגבי עצמותו עדיין, וכמו העלם המחשבה שמגלה העלם העצמי לגבי עצמו. וזהו בחי' א\"ק היינו בחי' מח' הקדומה, ונק' אדם להיותה מקור לבחי' אדם, והיינו מה שעלה ברצונו להטיב לברואיו, ואם אין נבראים למי ייטיב, ולהיותה מקור לבחי' אדם לכן נק' אדם, וגם קדמון להיותה לבוש לבחי' א\"ס הקדמון וכמו שהוא ית' קדמון לכל הקדומים כמו\"כ לבושו ית' קדמון וכהדין קמצא",[["1376","22","<b>הדיבור הוא שמגלה לזולתו. . המחשבה לגבי עצמו</b>: ראה גם סה\"מ תרכ\"ח ע' קעה. תרל\"ג ח\"ב שם ס\"ע תקו-ז. ס\"ע תקט-י. המשך וככה תרל\"ז פע\"ט (ע' קכו). ובכ\"מ."],["1377","23","<b>שמתחלה נעשה. . בריקת וסקירת השכל. . ואח\"כ. . בבחי' השגה והבנה</b>: ראה גם תניא פ\"ג. ועוד."],["1378","24","<b>כי לא מחשבותי מחשבותיכם. . ממחשבה זו נתהווה כל התהוות הנבראים</b>: ראה בארוכה סה\"מ תרל\"ד ע' רמ. וראה גם סה\"מ תרל\"ג ח\"ב שם ע' תקח. ובכ\"מ."],["1379","25","<b>בראשית נמי מאמר הוא. . מאמר הכללי</b>: ראה בארוכה סה\"מ תרכ\"ז ס\"ע רפב ואילך. [ובהנסמן שם בתחילת המאמר]."]]],[2000510422,"דלבושי' מיני' ובי', שכ\"ז הוא רק לשבר את האוזן כו', ובחי' זו היא בחי' בריאה דכלליות. ונמצא מתורץ מה שא\"ק נק' אדם דבריאה בכלליות, וגם מתורץ מה שנק' אדם ואעפ\"כ הוא נק' גם קדמון.\n<b>ומ\"מ</b> לגבי א\"ס הוא בחי' בריאה עדיין, ובכדי להיות א\"ק זהו ע\"י צמצום עדיין, והיינו הצמצום להיות מח' הקדומה זו כו', וכן יש בחי' אצי' דכלליות<sup data-n=\"1380\">26</sup> שהוא גילוי שורש הפרשת הארה שזהו בחי' אצי', שבד\"כ זהו ההפרש בין אצי' לבי\"ע, בי\"ע הם נבראים מחודשים ואצי' גילוי ההעלם, וכשם שיש שורש הבריאה היינו מה שמגלה העלם העצמי לגבי עצמו, כן יש בחי' שורש הפרשת הארה דאצי' גם בבחי' עצמותו, וביניהם יש שורש בחי' המל' דאצי' המהוה בריאה העליונה מח' הקדומה. ועד\"ז נבין עוד יותר מה ששיער עצמו בכח מה שעשה בפועל<sup data-n=\"1381\">27</sup>, הנה שיעור אינה מדידה כ\"א השערה לבד, דאילו כמו שעלה ברצונו הלא כתי' כי לא מחשבותי מחשבותיכם שלמעלה מיד כשעלה ברצונו הרי נתהוה ובא לידי פועל, אלא ענין ההשערה הוא מה שהוא בכח עדיין קודם שבא לידי פועל כו', ובחי' זו הוא באמת לפני הצמצום דאילו לפי מה שנת\"ל בענין שהקו הוא בחי' ממכ\"ע, והעיגול הגדול שלפני הקו הוא סוכ\"ע הנה הק\"ו הוא לאחר הצמצום והעיגול אם שזהו א\"ס שלפני הצמצום מ\"מ ה\"ז בא ע\"י סיבת הצמצום שהרי סילק אורו הגדול על הצד ע\"י הצמצום כמ\"ש בע\"ח וכנ\"ל, ומה\"ע ים וארץ לפני הצמצום, אלא שצ\"ל כנ\"ל שכ\"ז הוא בענין ההשערה בכח קודם שבא לידי פועל אפי' להיות מחה\"ק ואצי' הנ\"ל.\n[ס)] <b>ובזה</b> נבין דברי אאמו\"ר זצללה\"ה זיע\"א שאמר בדרוש דקרי\"ס<sup data-n=\"1382\">28</sup> שיש ים וארץ לפני הצמצום וקריעת ים סוף לפני הצמצום והוא ע\"ד הנ\"ל דוקא, והקרי\"ס שנתגלה העלם שבכח להיות בבחי' גילוי שבכח, ולכן אמר אז שזהו גילוי יש האמיתי כו', והיינו לפי שעה בהלכם בים נתגלה להם בחי' יש האמיתי שקדום לכל כו'. והנה קרי\"ס הי' ע\"י ג' פסוקים ויסע ויבא ויט<sup data-n=\"1383\">29</sup> שהם כנגד ג' אבות אברהם יצחק יעקב, ונמצא כי ויט הי' כנגד יעקב, והיינו על האבות נאמר בעבר הנהר ישבו אבותיכם היינו בחי' עבר הנהר דבינה וכמ\"ש במ\"א שהם בחי' חג\"ת דא\"א<sup data-n=\"1384\">30</sup>, ויעקב הוא בחי' ת\"ת הוא בחי' בריח התיכון המבריח מן הקצה אל הקצה בחי' קצה העליון שזהו בחי' אוירא עילאה שנת' בזהר ופי' המקובלים שזהו בחי' אויר קדמון, אויר",[["1380","26","<b>ובחי' זו היא בחי' בריאה דכלליות. . יש בחי' אצי' דכלליות</b>: ראה בארוכה לקו\"ת מסעי צה, א ואילך. סה\"מ תרמ\"ד (הוצאת תשס\"ג) ע' שמו ואילך."],["1381","27","<b>ששיער עצמו בכח. . שיעור אינה מדידה כ\"א השערה בלבד</b>: ראה בהנסמן בסה\"מ תרמ\"ד שם ע' שנב."],["1382","28","<b>ובזה נבין דברי אאמו\"ר זצללה\"ה זיע\"א שאמר בדרוש דקרי\"ס</b>: הכוונה למאמר כ\"ק אדמו\"ר הצ\"צ ד\"ה ענין קרי\"ס באוה\"ת בשלח שם ס\"ע תקעב-ג."],["1383","29","<b>והנה קרי\"ס הי' ע\"י ג' פסוקים ויסע ויבא ויט</b>: בהבא לקמן עד סוף הפיסקא ראה אוה\"ת בשלח שם ע' תקעה."],["1384","30","<b>בעבר הנהר ישבו אבותיכם. . עבר הנהר דבינה וכמ\"ש במ\"א. . חג\"ת דא\"א</b>: ראה לקו\"ת בחוקתי מו, סע\"ד ואילך. אוה\"ת דרושים לר\"ה ע' א'שכט."]]],[2000510423,"אור יו\"ד כמ\"ש בת\"א בד\"ה מזוזה מימין<sup data-n=\"1385\">31</sup> הוא בחי' כתר הקדמון כו', והיינו כי יעקב הוליד י\"ב שבטים שהיתה מטתו שלימה ולא כאברהם שיצא ממנו ישמעאל ולא כיצחק שיצא ממנו כו' אלא היתה מטתו שלימה, ונמצא כי הוא מקור כל ישראל, ואיתא בתנא דבי אליהו שני דברים יש בעולם תורה וישראל, ואיני יודע איזהו מהם קדמו, דרכן של בנ\"א אומרים התורה קדמה ואני אומר ישראל קדמו, והיינו כי כל התורה היא ציוויים לבנ\"י כמ\"ש דבר אל בנ\"י צו את בנ\"י והיתכן לומר שעדיין ישראל לא היו וכתב בתורה ציוויים להם אלא שישראל קדמו, וכן אמרו במד\"ר ז' דברים קדמו כו' ומחשבתן של ישראל קדמה לכל דבר, ולכן יעקב שהוא מקור כ\"י<sup data-n=\"1386\">32</sup> הגיע ע\"י שהי' בריח התיכון לשורש שרשם הוא בחי' אויר קדמון כו'.\n<b>וזהו</b> פקדת ארץ ותשוקקיה, פי' ארץ קאי על נש\"י כמ\"ש כי תהיו אתם ארץ חפץ, והיינו כמו פקידת הארץ הוא ע\"י גשמים כן פקידת הארץ דנש\"י להיות בבחי' תשוקה לשורש ומקור חוצבם במח' הקדומה זהו ע\"י פלג אלקים, פי' אמת המים כמ\"ש רש\"י והמצ\"ד, והיינו כי אלקים הוא צירוף ב' תיבות מי אלה, ובחי' מי ברא אלה, אמנם הנה זהו ע\"ד העלם והסתר הבורא מהנברא אבל כשנתגלה בחי' מי בבחי' אלה וזהו פלג אלקים פי' אמת המים, וה\"ז משל כמו ע\"י אמת המים נעשה מלא מים שגם תלמיה ירוו נחת, כן ע\"י המשכת אלקות שהי' בקריעת ים סוף שז\"ע פלג אלקים אמת המים עי\"ז נעשה מלא מים שגם בארץ יתמלא מים, והיינו להיות וידגו לרוב בקרב הארץ שגם בארץ יהיו כמו בחי' דגים שבים שמובלעים במי הים וכמשנת\"ל באריכות.\n<b></b>[סא)] וזהו אם בחוקתי תלכו<sup data-n=\"1387\">33</sup> ונתתי גשמיכם כו', כי הנה ארז\"ל במד\"ר [פ' בראשית] ס\"פ ך\"ו א\"ר יוחנן כל אורה האמור באלי'<sup data-n=\"1388\">34</sup> אינה אלא ירידת גשמים, ועמדו המפרשים ע\"ז באיוב<sup data-n=\"1389\">35</sup> ופי' שהאורה כשתרד למטה מתגשמת כו'. אמנם באמת א\"צ לזה שהרי רש\"י פי' בפסחים דס\"ח ע\"פ והי' וגו' שבעתים כאור שבעת הימים ז' פעמים ז' מ\"ט, וז' פעמים מ\"ט שמ\"ג וזהו גשם עולה שמ\"ג, ונמצא פי' ונתתי גשמיכם שיומשך הגשם מבחי' זו והיינו שיומשך ההשפעה מבחי' אור ז' הימים ע\"ד",[["1385","31","<b>בת\"א בד\"ה מזוזה מימין</b>: פ' מקץ מב, ג. מג, ב."],["1386","32","<b>מקור כ\"י</b>: כנסת ישראל (או: כל ישראל)."],["1387","33","<b>וזהו אם בחוקתי תלכו</b>: בהבא לקמן עד סוף המאמר ראה גם אוה\"ת ויקרא (כרך ב) שם ע' קצה-ו. סה\"מ תרכ\"ו שם ע' ק-קא. תר\"ל שם ע' קמה-ו. קנג-ד."],["1388","34","<b>ארז\"ל. . כל אורה האמור באלי'</b>: במד\"ר שם: כל אורה שנאמר באליהוא (בן ברכאל הבוזי, הנזכר בסוף איוב. פי' המ\"כ והמהרז\"ו שם) אינה אלא בירידת גשמים (כגון יפיץ ענן אורו (איוב לז, יא) והרבה כמו כן. פירש\"י שם). וראה גם תענית ז, ב."],["1389","35","<b>ועמדו המפרשי' ע\"ז באיוב</b>: בד\"ה אם בחוקתי הנ\"ל להצ\"צ: והקשו בספרים מהו שייכות אור לגשם ותירצו (כבפנים). וראה איוב לו, ל: פרש עליו אורו. ובפי' האב\"ע שם: פרש על העב מטרו. וי\"א כי נק' המטר אור בעבור המאור הקטן כי בתנועותיו יהי' המטר בציווי הבורא. ובמצו\"צ שם: פרש עליו אורו, אורו ענין המטר, וכן כל אור האמור בענין, והוא מלשון יורה ומלקוש."]]],[2000510424,"שלע\"ל יהי' ז' פעמים ז' אור ז' הימים, וכ\"ז יבוא ע\"י העבודה דעכשיו, וא\"כ גם עתה אם בחוקתי תלכו שתהיו עמלים בתורה אז ונתתי גשמיכם שיומשך הגשם מבחי' שמ\"ג הנ\"ל שעולה גשם, וה\"ז בק\"ו ומה בקרי\"ס שהי' הקדמה למ\"ת הי' מלא מים מבחי' פלג אלקי', כ\"ש ע\"י התורה עצמה ושתהיו עמלים למלאות מה שנתאוה המקום הוא בחי' א\"ס שהוא מקומו של עולם ואין העולם מקומו שיהיו ישראל עמלים בכדי שיהי' לו ית' דירה בתחתונים דוקא, ומדוע נתאוה כך זהו למעלה מהשגתינו<sup data-n=\"1390\">36</sup> רק כך עלה ברצונו, רק זה אנו מבינים שנתאוה הקב\"ה להיות לו ית' דירה בתחתונים וכמ\"ש במד\"ר ע\"פ שוקיו עמודי שש שוקיו זה העולם שנשתוקק הקב\"ה לבראותו יעו\"ש בפ' במדבר פ\"י, וזהו ע\"י התורה שלכן נתאוה המקום שיהיו ישראל עמלים בתורה כו'. וזהו שאמרו בפדר\"א שבזמן שהקב\"ה חפץ לשלוח ברכתו אז הגשמים באים מעל השמים, שלכאו' מהו נפ\"מ אם מקבלת מעננים שקיבלו מאוקיינוס ותהומות, אלא שהענין כך הוא שעד שלא נבה\"ע הי' מים במים, פי' מים תחתונים היו מעורבים עם מים עליונים, וממילא לא היו מים עליונים בתכלית העילוי כ\"כ ומים תחתונים לא ירדו כ\"כ, כמו היין כשמעורב עם השמרים וכמ\"ש במ\"א<sup data-n=\"1391\">37</sup>, והנה המים הם המצמיחים כל מיני תענוג הן רוחני והן גשמי<sup data-n=\"1392\">38</sup>, ולכן כשמקבלת ממי אוקיינוס ה\"ז מקור להשפיע רק בחי' תענוגי' גשמיי', אמנם כשחפץ לשלוח ברכתו אז גם הגשמיות נשפע ממקום גבוה היינו מבחי' המים המצמיחים תענוגים רוחני' כענין דכתי' ונהר יוצא מעדן להשקות הגן, גן הוא בחי' ג\"ן סדרים דאורייתא, והנהר הוא המשקה ג\"ן הלזה, וכשנמשך מבחי' מים אלו אז גם הדברים הגשמיי' מתרבים ומתברכים בשפע רבה. וזהו אם בחוקתי תלכו שתהיו עמלים בתורה אז ונתתי גשמיכם כו' בחי' שמ\"ג גשם, ונתנה הארץ יבולה ועץ השדה יתן פריו, יבולה בה\"א הידיעה ופריו היינו ג\"כ הידועים, או שיהי' עצו ופריו שוים ע\"ד לע\"ל דוקא, שזהו דוקא ע\"י ההילוך בתורה בבחי' עמל ויגיעה דוקא, וזהו אם בחוקתי וגו' ונתתי גשמיכם וגו'.",[["1390","36","<b>ומדוע נתאוה כך זהו למעלה מהשגתינו</b>: ראה מאמרי אדה\"ז תקס\"ג ח\"א ע' שלח. אוה\"ת בלק ע' תתקצז. המשך תרס\"ו ס\"ע ז. תרכ\"ז ע' תנג. תר\"ל ע' רפט. תש\"ב ע' 34. לקו\"ש ח\"ו ע' 21. ועוד."],["1391","37","<b>מים במים פי' מים תחתונים היו מעורבים עם מים עליונים. . וכמ\"ש במ\"א</b>: ראה סה\"מ תרכ\"ו ע' לג ואילך. ע' נח. תרכ\"ז ע' רלא. שעז ואילך. (וראה גם שם ע' רסו ואילך). המשך וככה תרל\"ז פנ\"ב-ג (ע' עז ואילך)."],["1392","38","<b>המים הם המצמיחים כל מיני תענוג הן רוחני והן גשמי</b>: ראה תניא ספ\"א. סה\"מ תרכ\"ו ע' כ. לג. נח."]]],[2000510425,"<h3>[ויאמר גו' מחר חודש]</h3>\n<b></b><b>[ד\"ה ויאמר גו' מחר חודש]\nבס\"ד. פ' במדבר, מחר חדש.</b>\nולהבין כו' פקדת הארץ\nבמדבר, מ\"ח\n<b></b>[סב)] ולהבין ביאור<sup data-n=\"1393\">1</sup> הענין בענין פקדת ארץ ותשוקקיה, צ\"ל מ\"ש ויאמר לו יהונתן מחר חדש ונפקדת כי יפקד מושבך ושלשת תרד מאד וגו', ופרש\"י ונפקדת אבי יפקדך וישאל היכן אתה, כי יפקד מושבך שיהי' מושבך חסירה, וכן ת\"י ותיתבעי ארי יהי' מרוח בית אסחרנותך, ונמצא כי פי' ונפקדת הוא מלשון זכרון שע\"י שיהי' חסר מקום מושבו עי\"ז יזכור שאול עליו וידבר גינו. וה\"ז כענין פקדת ארץ שהוא ג\"כ זכרון על הדבר הצריך לארץ והוא גשמים, או פקידת האשה לבנים כמ\"ש וה' פקד את שרה וכלשון רז\"ל חייב אדם לפקוד כו', ולכן ארז\"ל בתענית ד\"ח ע\"ב נאמר פקידה באשה ונא' פקידה בגשמים, נאמר פקידה באשה וה' פקד את שרה ונאמר פקידה בגשמים פקדת הארץ ותשוקקיה, ולכאורה צ\"ל מהו ענין זה אצל זה להשוות ענין פקידת האשה לבנים לפקידת הארץ לגשמים וכמו שהשוה עוד שם לענין עצירה ולידה יעו\"ש<sup data-n=\"1394\">2</sup>.\n<b>אך</b> הענין הוא דהנה ארז\"ל בשלהי מ\"ק [אמר רבא] בני חיי ומזוני לאו בזכותא תליא מילתא אלא במזלא תליא, וגשמים הם השפעת מזונות שמים מצמיחים כו', לכן השוום רז\"ל למצוא בהם מה שהם שוים לבנים להיות כי שניהם במזלא תליא. אך",[["1393","1","<b>ולהבין ביאור. . ויאמר לו יהונתן</b>: מאמר זה הוא מאמר התשיעי שבהמשך והחרים תרל\"א\". והוא מיוסד על כמה דרושים: חלקו הראשון (עד פיסקא: ולפרש זה. ופיסקא: ומעתה יובן ענין וה' פקד ופיסקא שלאח\"ז) מיוסד על ביאוה\"ז לאדהאמ\"צ יא, ב ואילך [ד\"ה ויעש ה' לשרה]. מאמרי אדה\"ז תקס\"ג ח\"א ע' כה ואילך. [ובשינויים באוה\"ת וירא (כרך ד) תשנה, ב ואילך. ביאוה\"ז להצ\"צ ח\"א ע' מד ואילך. ח\"ב ע' תרלז-ח. סה\"מ תרמ\"ג ע' רפז ואילך. לעיל ד\"ה וה' פקד תרל\"א פרקים ג-ד. וראה גם מאמרי אדה\"ז על מארז\"ל ע' קצח. רג].\nפיסקא: ולפרש זה, וסיום המאמר (פיסקא: וזהו ויאמר לו יהונתן): מיוסד על ד\"ה ויאמר גו' מחר חודש בס' מאמרי אדה\"ז תקס\"ז ע' מט ואילך. וע' נה ואילך. [ובשינויים באוה\"ת בראשית ו, סע\"ב ואילך. יא, א ואילך. מאמרי אדהאמ\"צ במדבר ח\"א ע' קכג ואילך. קמז ואילך. סה\"מ תרס\"ג ע' עא ואילך].\nפיסקא: והנה ענין היחוד, עד פיסקא: וזהו\"ע כל הנחלים, הוא חלק מד\"ה בזאת יבוא בסה\"מ תר\"ל ע' קכא-ב. תרל\"ב ח\"א ע' קלט-מ.\nהמאמר נמצא בשינויים ובתוס' הגהות: בד\"ה זה בסה\"מ תרל\"ג ח\"א ע' רלז ואילך. וע' רמז ואילך. סה\"מ תרנ\"ח ע' קעט ואילך. תרמ\"ד ע' קנה-ח [ד\"ה וה' פקד]. ד\"ה והוי' פקד תשמ\"ג. לעניני המאמר ראה גם ד\"ה זה: (דש\"פ שמיני) תשכ\"ח (סה\"מ מלוקט ח\"ה ע' רמג ואילך [ושם נתבאר שייכות מאמר דידן לער\"ח סיון, עיי\"ש]). תשל\"א (סה\"מ תשל\"א ע' 460 ואילך). תשל\"ו (סה\"מ תשל\"ו ע' 31 ואילך. 221 ואילך). תשמ\"ה.\nלכללות המאמר ראה לקמן ע' שעא ד\"ה וביאור ענין פקדת ארץ שהוא רישומי דברים ממאמר זה."],["1394","2","<b>וכמו שהשוה עוד לענין עצירה ולידה יעו\"ש</b>: ראה תענית ח, ב שם: נאמרה עצירה באשה שנא' כי עצור עצר ה' בעד כל רחם ונאמרה עצירה בגשמים דכתי' ועצר את השמים כו', נאמר לידה באשה דכתי' ותהר ותלד בן ונאמר לידה בגשמים דכתי' והולידה והצמיחה."]]],[2000510426,"לפ\"ז אינו מובן מהו אומרו וה' שידוע מארז\"ל בזה במד\"ר פ' וארא ופ' בא וה' הוא ובית דינו, ומאחר שדבר זה תלוי במזלא מה\"ע בית דין לשם, שנודע שבית דין הם ע\"ב סנהדרין שיושבין בהיכל הזכות<sup data-n=\"1395\">3</sup> לשפוט לאיש כדרכיו כו', והאיך יכולים לשפוט דבר התלוי בבחי' מזלא ולא בדידהו תליא מילתא. וגם הלא מצינו בפירוש דכתי' ועבדתם וגו' ובירך את לחמך ואת מימך וגו' לא תהי' משכלה ועקרה וגו' את מספר ימיך אמלא, הרי בני חיי ומזוני, ונאמר ע\"ז תחלה ועבדתם את ה' אלקיכם שתלוי בעבודה, שנמצא משמע שזה תלוי בזכות כו'. וגם בעיקר ענין מאמר רבא צ\"ל מה שהקשו התוס' משבת דקנ\"ו אין מזל לישראל, נראה שמפרשי' מזל היינו מזלות, אך אאזמו\"ר רבינו ז\"ל פי' אין מזל לישראל<sup data-n=\"1396\">4</sup> היינו שבחי' אין הוא המזל של ישראל, ונמצא שניהם אמת כי אין מזל לישראל הוא בבחי' המזלות דהילוך הכוכבים ומזלות, אבל בחי' אין הוא המזל של ישראל, וע' בלק\"ת בד\"ה יונתי<sup data-n=\"1397\">5</sup> בחגוי הסלע שפי' מארז\"ל אע\"ג דאיהו לא חזי מזלייהו חזי, שא\"א לומר על מזלות שהרי ארז\"ל אין מזל לישראל, אלא הכוונה הוא על בחי' שורש ומקור הנשמה, ובד\"ה האזינו הא' בסופו<sup data-n=\"1398\">6</sup> פי' שבחי' טל<sup data-n=\"1399\">7</sup> הוא למעלה משורש ומקור נש\"י שמקורם הוא במזלות דנוצר ונקה. ולפ\"ז יתכן מאמר רבא שאמר לא בזכותא תליא אלא במזלא היינו בחי' מזל דנוצר ונקה. אמנם פסוק ועבדתם וגו' אינו מיושב עדיין למה תלה ג' דברים אלו בבני חיי ומזוני בעבודה כו'. וגם צ\"ל מאחר שגם מזונא במזלא תליא א\"כ זהו כמ\"ש בפדר\"א הנ\"ל<sup data-n=\"1400\">8</sup> שבזמן שהקב\"ה חפץ לשלוח ברכה בצמח הארץ אזי פותח אוצרות השמים ומקבלת הארץ ממים עליונים שמעל השמים שנת\"ל שזהו כענין בחי' אור ז' הימים<sup data-n=\"1401\">9</sup> שפי' רש\"י בפסחים ע\"פ שבעתיים כאור שבעת הימים ז' פעמים ז' מ\"ט וז' פעמים מ\"ט עולה שמ\"ג וזהו כאותיות גשם.\n<b></b>[סג)] ולפרש זה צ\"ל מ\"ש (תלים מ\"ו) נהר פלגיו<sup data-n=\"1402\">10</sup> ישמחו עיר אלקים פי' נהר הוא בינה, פלגיו הוא הנחלים הנמשכים מבינה שהם ז' מדות הנולדים מבינה שז\"ע כל הנחלים הולכים אל הים שנת\"ל<sup data-n=\"1403\">11</sup>, וא\"כ מהו עוד ענין נהר פלגיו",[["1395","3","<b>שנודע שבית דין הם ע\"ב סנהדרין שיושבין בהיכל הזכות</b>: ראה ביאוה\"ז לאדהאמ\"צ ולהצ\"צ שם. וראה גם מאמרי אדה\"ז תקס\"ו ס\"ע שצב. המשך תער\"ב ח\"ג ע' א'תיא. ובכ\"מ."],["1396","4","<b>אך אאזמו\"ר רבינו ז\"ל פי' אין מזל לישראל</b>: לקו\"ת ר\"פ האזינו עא, ד. מאמרי אדה\"ז תקס\"ג ח\"ב ע' תשנז. וראה גם מאמרי אדהאמ\"צ דברים ח\"ד ע' א'קסט. וש\"נ."],["1397","5","<b>בלק\"ת בד\"ה יונתי</b>: לקו\"ת שה\"ש טז, ד."],["1398","6","<b>ובד\"ה האזינו הא' בסופו</b>: לקו\"ת האזינו עג, סע\"ב-ג."],["1399","7","<b>שבחי' טל</b>: בהמשך והחרים תרל\"א הנדפס מכת\"י הר\"ש סופר: שבחי' מזל\", והוא ט\"ס ראה לקו\"ת האזינו שם."],["1400","8","<b>כמ\"ש בפדר\"א הנ\"ל</b>: לעיל ד\"ה אם בחוקתי (ע' שכז)."],["1401","9","<b>שנת\"ל שזהו כענין בחי' אור ז' הימים</b>: לעיל סד\"ה אם בחוקתי (ע' שלד)."],["1402","10","<b>צ\"ל מ\"ש. . נהר פלגיו</b>: ראה עוד ע\"פ זה לקו\"ת במדבר ה, ג ואילך. ו, ד ואילך. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תקפא ואילך. תקפט ואילך. ובארוכה בס' מאמרי אדהאמ\"צ במדבר ח\"א ע' ק ואילך. סה\"מ תרנ\"ט ע' פט."],["1403","11","<b>שז\"ע כל הנחלים הולכים אל הים שנת\"ל</b>: לעיל ד\"ה כל הנחלים."]]],[2000510427,"ישמחו עיר אלקים, ונודע כי עיר אלקים הוא בחי' המל' הנק' עיר אלקינו ומה\"ע השמחה<sup data-n=\"1404\">12</sup> כו'. הנה נודע כי בכל ר\"ה הוא בנין המל' כי אדה\"ר וחוה דו פרצופים נבראו, ונסר אחת מצלעותיו היא חוה ראשונה ויבן ה' אלקים את הצלע זהו בחי' בנין המל', והיינו כי מדת המל' נאצלה בסוד שורש רק נקודה אחת לבד, ובר\"ה הוא בנין המל' שבונים אותה להיות בבחי' פרצוף שז\"ע ט' ברכות וט' תקיעות דר\"ה כנ\"ל<sup data-n=\"1405\">13</sup> שע\"י הברכות והתקיעות ממשיכים ט' ספירות לבחי' נקודת המל' ואז נעשית בבחי' פרצוף שלם כו', וזהו ענין פסוקי מלכיות<sup data-n=\"1406\">14</sup> זכרונות ושופרות שמביאים ראי' מן התורה שצ\"ל בנין המל', כמו אחד האומר לחבירו תדע שהנכון אתי שהרי פלוני אומר ג\"כ כן, וכן אומרים ככתוב בתורתך ענין בנין המל', והם כל פסוקי מלכיות, וכן הוא בענין זכרונות ושופרות כו', וזהו ג\"כ ענין והאיתנים מוסדי ארץ שהם מייסדים תושבע\"פ שנק' ארץ בחי' מל'. ומ\"מ בכל ר\"ח צ\"ל יחוד שימשא וסיהרא לצורך קבלתה אור חדש מהשמש, דהנה השמש הוא בחי' שמש הוי', וכתי' זה הוי' קוינו לו שיש בחי' שם הוי' שנמשך בציור קוין חח\"ן מימין בג\"ה משמאל דת\"י באמצע, ויש י\"ב צירופי הוי', והיינו בחי' י\"ב גבולי אלכסון דז\"א<sup data-n=\"1407\">15</sup>, והוא כי חח\"ן הוא חיבור חכ' עם החסד והנצח, ובג\"ה הוא בחי' חיבור הבינה עם הגבורה ועם ההוד, ונודע כי נצח ענף החסד והוד ענף הגבורה<sup data-n=\"1408\">16</sup>, אמנם בכדי להיות חיבור והתכללות החסד עם ההוד והגבורה עם הנצח זהו ע\"י בחי' גבולי אלכסונים שבאלכסון מתחבר החסד עם ההוד והגבורה עם הנצח ובכל הששה מדות יש י\"ב גבולי אלכסון שבהם מתחברים הששה מדות כו', ובכל ר\"ח מקבלת הלבנה צירוף חדש מי\"ב צירופי הוי' שהם בחי' י\"ב גבולי אלכסון דו' מדות דז\"א. וזהו אחר שכבר נבנית בר\"ה דוקא, וכמו באדה\"ר שלאחר שנסר אחת מצלעותיו בנה אותה בבחי' בנין כמ\"ש ויבן ה' אלקים את הצלע, ואח\"כ ויביאה אל האדם להיות היחוד ואז אמר זאת הפעם עצם מעצמי וגו'. וכן הוא בבחי' המל' ג\"כ, שתחלה צ\"ל בנין המל' בר\"ה, ואח\"כ בכל ר\"ח מקבלת היחוד מהשמש בחי' אור חדש דצירוף חדש. ומ\"ש במ\"א שבעת קבלתה נסתר כל בנינה עד שנעשית נקודה תחת היסוד, אמת שכן הוא אך זהו בבחי' הביטול לפי שא\"א לה לקבל האור באופן אחר, אמנם זהו רק לפי שעה ולא כל בנינה",[["1404","12","<b>מהו עוד ענין נהר פלגיו ישמחו עיר אלקים. . ומה\"ע השמחה</b>: בד\"ה בסה\"מ תרל\"ג שם ע' רלט-מ מבאר זה: ואם נאמר ש[פסוק נהר פלגיו] זהו ענין אחד עם פסוק כל הנחלים, הרי שם נאמר והים איננו מלא, עי' בפי' המפרשים ע\"ז, ועכ\"ז לדברי כולם צריך לומר שהים אינו מתפעל מזה כ\"כ, והרי זהו היפך השמחה שענינה הוא התפעלות שמצד הגילוי כו', אלא בהכרח לומר ששני ענינים הם."],["1405","13","<b>שז\"ע ט' ברכות וט' תקיעות דר\"ה כנ\"ל</b>: לעיל ד\"ה כל הנחלים שם."],["1406","14","<b>וז\"ע פסוקי מלכיות שמביאין ראי' מן התורה</b>: ראה בכ\"ז לקו\"ת דרושים לר\"ה נו, ג. סידור עם דא\"ח רלח, ב. רמא, ג. מאמרי אדה\"ז תקס\"ד ע' ריח. ועוד."],["1407","15","<b>י\"ב צירופי הוי' והיינו בחי' י\"ב גבולי אלכסון דז\"א</b>: ראה לקו\"ת מסעי צד, א. ראה כז, ג. מאמרי אדהאמ\"צ ויקרא ח\"א ע' רכה. במדבר ח\"א ע' קכד ואילך. [וראה שם ע' שז]. ביאוה\"ז לאדהאמ\"צ פה, א ואילך. ולהצ\"צ ח\"א ע' תנא ואילך. אוה\"ת בראשית שם ז, א. בא ע' רנד. [ובדרושים ע\"פ מחר חודש שנסמנו לעיל בתחילת המאמר]."],["1408","16","<b>ונודע כי נצח ענף החסד והוד ענף הגבורה</b>: ראה בארוכה לקו\"ת מסעי צ, ג ואילך. ועוד."]]],[2000510428,"דאל\"כ הי' צ\"ל בנין המל' בכל ר\"ח כמו בר\"ה והי' צריך לומר פסוקי מלכיות וזכרונות ושופרות כו' אלא כנ\"ל.\n<b></b>[סד)] והנה ענין היחוד שמקבל הלבנה מבחי' השמש, הן אמת שבחי' שמש הוי' הוא מבחי' חכ' ואילך, והיינו שז\"א נק' שמש, וגם החכ' נק' שמש הוי' כמ\"ש הוי' בחכמה, וכתי' ממזרח שמש וזרח השמש שהוא בחי' יסו\"א כמ\"ש במ\"א<sup data-n=\"1409\">17</sup>, ונמצא כי היחוד הוא מבחי' ז\"א וע\"ס, מ\"מ שרש היחוד הוא מאוא\"ס שלמעלה מהחכ', וכמ\"ש בלק\"ת בד\"ה אלה פקודי<sup data-n=\"1410\">18</sup> משכן העדות, שבכדי להיות יחוד חו\"ב שרש ההמשכה הוא מבחי' ישת חושך סתרו בחי' כתר, וכן בענין יחוד זו\"נ דבחי' שימשא וסיהרא מאחר שיחוד זה נמשך גם מבחי' החכמה דכתי' ה' בחכ', הנה גם לצורך יחוד זה נמשך המשכה מלמעלה מהחכ' ואינה דומה לשאר יחוד זו\"נ כו', ומה גם כי שורש ז\"א בעתיקא<sup data-n=\"1411\">19</sup> אחיד ותליא<sup data-n=\"1412\">20</sup>, והיינו כי הגם שבינה היא אם הבנים והיא המולדת ששה בנים הם ו\"ק דז\"א, מ\"מ שורש ז\"א בעתיקא אחיד ותליא, וכמו\"כ במל' בנין המל' הוא מט\"ס דע\"ס שזהו ענין כל הנחלים הולכים אל הים, ושרש יחוד המל' נמשך הכח ע\"ז מלמעלה מהשתלשלו' ומ\"מ נמשך דרך חו\"ב, והעיקר יחוד זו\"נ.\n<b>וביאור</b> ענין ז\"א בעתיקא יובן דהנה לידת המדות אהוי\"ר זהו מבחי' ההתבוננו' דבינה, דהנה כתי' ואהבת את הוי' אלקיך, פי' ואהבת ל' ציווי ולכאו' יפלא איך שייך לשון ציווי על אהבה שהיא מדה שבלב, אך הענין דהציווי הוא על התבוננות שיתבונן בגדולת אוא\"ס, ועי\"ז יבוא לבחי' אהבה הטבעי' שיש בכאו\"א מישראל בירושה לנו מאבותינו. ולכן יתכן ל' ציווי על בחי' אהבה זו, שהרי ביכולת האדם להוציאה מהעלם אל הגילוי ע\"י ההתבוננות בפסוק ראשון דק\"ש איך שה' אחד בחי' יחו\"ע, ומפני שלא כל אדם יוכל לבוא להוליד אהבה מהתבוננו' דיחו\"ע לכן אומרים ברוך שם כבוד מלכותו לעולם ועד, שם כבוד מלכותו הוא בחי' הארה דהארה דהארה כמ\"ש במ\"א<sup data-n=\"1413\">21</sup>, ובחי' זו היא לעולם ועד כל העליות בנו\"ן אלפים יובלות, ועי\"ז בא לבחי' ואהבת כו', וזהו בחי' האהבה שהמשיך אאע\"ה בנש\"י בטבע",[["1409","17","<b>החכ' נק' שמש הוי'. . בחי' יסו\"א כמ\"ש במ\"א</b>: ראה סידור עם דא\"ח קפב, א. פירוש המלות לאדהאמ\"צ כה, ג ואילך."],["1410","18","<b>וכמ\"ש בלק\"ת בד\"ה אלה פקודי</b>: ראה שם דף ג, רע\"ד."],["1411","19","<b>וביאר ענין ז\"א בעתיקא</b>: בהבא לקמן עד סוף הפרק ראה סה\"מ תר\"ל שם ע' קכא-ב. תרל\"ב שם ע' קלט-מ."],["1412","20","<b>שורש ז\"א בעתיקא אחיד ותליא</b>: ראה בכ\"ז תו\"א יתרו עג, א. לקו\"ת שמיני יט, ב. חוקת נח, ב. מאמרי אדה\"ז תקס\"ז ע' שסד. תקס\"ח ח\"א ע' א. וע' ד ואילך. ענינים ע' תיח ואילך. סה\"מ תרל\"ב ח\"א ע' יז. [ובהנסמן שם בע' יב]."],["1413","21","<b>שם כבוד מלכותו הוא בחי' הארה דהארה דהארה כמ\"ש במ\"א</b>: ראה לקו\"ת אמור לא, סע\"ג-ד."]]],[2000510429,"תולדותם, אך הנה היא מוסתרת ונעלמת, וע\"י בחי' התבוננות יכול כ\"א להוציאה מהעלם אל הגילוי מאחר שכבר ישנה בהעלם בטבע תולדתו שלכן נק' אהבה טבעית. אבל עוד יש פי' ואהבת לשון הבטחה<sup data-n=\"1414\">22</sup> היינו סופך לבוא לידי אהבה, זהו מעלת ומדרגת אהבה דאהרן<sup data-n=\"1415\">23</sup> שהוא בחי' אה\"ר שלמעלה מן הטו\"ד שאין זה ביכולת האדם לבוא ע\"י התבוננות כ\"א כשנותנים לו מלמעלה, ואינו דומה לבחי' אהבה הטבעית שנמשכת מהתבוננו', שזהו ע\"פ השגת השכל וה\"ז בבחי' הגבלה, שזה\"ע לאהבה את ה' כי הוא חייך, והיינו כמו האדם אוהב חיי נפשו, כן כאשר יתבונן שאוא\"ס ב\"ה הוא חיי החיים כו', מהתבוננות זו נמשך לו בחי' אהבה, משא\"כ אה\"ר דאהרן הוא אהבה שבלי גבול לצאת מהכלי כו' היפך הגבלת השכל כו', היא הבאה מלמעלה כו' ע\"י המשכת אהרן כה\"ג כי אהרן הוא אותיות נראה והיינו בחי' באורך נראה אור, באורך דוקא הבא מלמעלה כו', וזהו שרש ההפרש בין אהבה דאהרן לאהבה דאברהם אוהבי. אמנם בכדי להיות המשכת אה\"ר דאהרן, הגם שהוא בעצם בלי גבול, מ\"מ הנה אין נותנים זה לאדם כ\"א לפי ערך אהבה הטבעית שבכח האדם ההוא להתגלות ע\"י ההתבוננות בה' אחד כו', וכמארז\"ל כל המאריך באחד<sup data-n=\"1416\">24</sup> מאריכין לו ימיו ושנותיו, פי' אחד הוא ההתבוננות איך דכולא קמי' כלא חשיב, שהגם שנבראו ז' רקיעים וארץ וד' רוחות, מ\"מ הם בטלים בתכלית לגבי אור א\"ס ב\"ה אלופו של עולם כמשנ\"ת ביטול הגשמיות לגבי הרוחני' בד\"ה מי כמוכה<sup data-n=\"1417\">25</sup>, ועד\"ז יובן בגבוה מעל גבוה עד המקור הא' שלא יש שום מציאות אמיתי זולתו ית'. וכאשר מאריך באחד, פי' באריכות ההתבוננו', שלפ\"ע האריכות לפ\"ע זה יוצא אצלו האהבה הטבעית מהעלם אל הגילוי כו', אזי מאריכין לו ימיו, פי' יום הוא בחי' חסד כמ\"ש יומם יצוה ה' חסדו, והיא בחי' אהבה דאברהם איש החסד, ופי' מאריכין לו ימיו שנמשך לו מבחי' א\"א<sup data-n=\"1418\">26</sup> הוא בחי' ורב חסד שלמעלה מהחכמה כו'. אמנם מ\"מ זהו דוקא כשמאריך באחד דוקא, הוא בחי' האהבה דאברהם אוהבי כו'.\n<b>ונמצא</b> כי בחי' אה\"ר שורשה מבחי' מדות שלמעלה מהשכל. ועד\"ז יובן ענין ז\"א הגם כי לידת ז\"א הוא מאימא כו', מ\"מ שרש ז\"א בעתיקא אחיד ותליא הוא בחי' טורי חשוכא מדות שלמעלה מהשכל כו'. ולפ\"ז יובן ג\"כ בבחי' המל' שבנין המל' הוא מט\"ס שמבחי' מל' דט\"ס דאצי' נבנית המל' להיות בבחי' פרצוף.\n<b></b>[סה)] וזהו ענין כל הנחלים הולכים אל הים כמשנת\"ל באריכות, והוא ג\"כ בחי' האיתנים שהם מוסדי ארץ כמשנת\"ל בענין יסוד כו'. אך מה שהיא",[["1414","22","<b>ואהבת. . ל' ציווי. . ל' הבטחה</b>: ראה תו\"א תשא פו, ג. סה\"מ תרל\"ב ח\"א ע' צה. וראה גם הקדמה לשעהיוה\"א הנק' חינוך קטן\". המשך וככה תרל\"ז ע' קעג ואילך."],["1415","23","<b>האהבה שהמשיך אאע\"ה. . ומדרגת אהבה דאהרן</b>: ראה בכ\"ז תו\"א תצוה פב, א. לקו\"ת בהעלותך כט, ג. ובכ\"מ."],["1416","24","<b>וכמארז\"ל כל המאריך באחד</b>: בהבא לקמן ראה בארוכה סה\"מ תרכ\"ט ע' קסה ואילך. [ובהנסמן שם]."],["1417","25","<b>כמשנ\"ת ביטול הגשמיות. . בד\"ה מי כמוכה</b>: סה\"מ תרכ\"ט ע' קנז ואילך."],["1418","26","<b>ופי' מאריכין לו ימיו. . מבחי' א\"א</b>: ראה אוה\"ת תצוה ע' א'תרכט. סה\"מ תרכ\"ט שם ע' קסח."]]],[2000510430,"מקבלת היחוד מבחי' שמשא זהו בחי' נהר פלגיו<sup data-n=\"1419\">27</sup> ישמחו עיר אלקים, פי' פלגיו הוא בשפע יותר הרבה מבחי' נחל שלא כמו הנחל שהוא נהר קטן כמשנת\"ל בשם הג\"פ<sup data-n=\"1420\">28</sup> סי' קך\"ח, אבל פלגיו הוא ג\"כ המדות אך זהו כמו שהן בהפלגה והיינו כנ\"ל ששרש השפע בא מלמעלה מהשתלשלו', ולכן כשבא השפע זו בבחי' עיר אלקינו הוא בחי' המל', כנודע מענין שתי אבנים בונות שתי בתים ע' בד\"ה כמגדל דוד צוארך<sup data-n=\"1421\">29</sup>, הנה עז\"נ ישמחו עיר אלקים שהשמחה היא מצד הגילוי דבחי' שמשא שמאיר הארה חדשה בחי' צירוף חדש מי\"ב צירופי הוי' כו'. וביאור הענין יובן ממ\"ש במ\"א בענין בעטרה שעטרה לו אמו<sup data-n=\"1422\">30</sup> ביום חתונתו שע\"י השפעת הז\"א למל' עי\"ז נמשך בז\"א בחי' עטרה מבחי' אמו וכמ\"ש זכר ונקבה כו' ויברך אותם. ושרש הברכה הוא כמ\"ש בזהר כד ע\"ק בעי לאשדא ברכאין אשדי בההוא עמיקא עילאה, פי' עמיקא עילאה הוא בחי' בינה, והברכה אשר בה נמשך מבחי' ע\"ק, ולכן בר\"ח כשיש יחוד שמשא וסיהרא ארז\"ל על קרבן דר\"ח שאמר הקב\"ה הביאו עלי כפרה כו', עלי כמו על ה' שיומשך משם הברכה ע\"י הזיווג, ולכן בזה\"ג הצדיק אבד<sup data-n=\"1423\">31</sup> צדיק יסוד ז\"א אבד מלקבל ברכאן מחמת העדר ההשפעה למל' בזה\"ג, נשמע מזה שע\"י ההשפעה מתברך, וזהו הברכה שע\"י ההשפעה, וכמו\"כ בכדי להיות השפעה זהו ג\"כ ע\"י שנמשך כח מלמעלה.\n<b>ומעתה</b> יובן ענין וה' פקד<sup data-n=\"1424\">32</sup> הוא וב\"ד, כי הנה בר\"ה נפקדה שרה, והיינו כי בר\"ה הוא בנין המל' וכנ\"ל, והבנין הוא בשביל היחוד, וע\"ז הוא הדין והמשפט דר\"ה אם ראוי' שיהי' בנין המל' וכו', ועיין בפי' רש\"י ע\"פ והוא מסבות מתהפך בתחבולותיו ומ\"ש בזהר ע\"פ זה<sup data-n=\"1425\">33</sup>. וכמו\"כ בענין בנין עדי עד שזהו פקידה דאשה להוליד בנים זהו ג\"כ ע\"י דין ומשפט תחלה, והיינו כי הגם שבני לאו בזכותא תליא, היינו שאין בכחם ליתן דבר זה בעצמם כ\"א שצריך שיומשך מבחי' מזלא, וה\"ז כמשל כשצריכים לדון איזה דבר גדול הנה הדיין והפוסק הדבר הגדול הזה הוא המלך עצמו, מ\"מ בעלי משפט הקטנים מעיינים תחלה בדבר הזה אם ראוי הוא שיובא לפני המלך, ואם ע\"פ שכלם אינו ראוי אזי אין מעלים זה כלל לפני המלך, ואם ע\"פ שכלם ראוי ונכון לעשות לו כבקשתו את הדבר הגדול הזה אז הם מעלים זה לפני המלך, והיינו מפני שהם עצמם אין בכחם ליתן דבר זה כי לא בדידהו תליא מילתא, אבל",[["1419","27","<b>וזהו ענין כל הנחלים. . בחי' נהר פלגיו</b>: בהבא לקמן בפרק זה ראה מאמרי אדה\"ז תקס\"ג שם ע' קסט. ביאוה\"ז להצ\"צ ח\"א ע' רלג. ח\"ב ע' תשעז. אוה\"ת שה\"ש ס\"ע מ."],["1420","28","<b>כמשנת\"ל בשם הג\"פ</b>: לעיל ד\"ה כל הנחלים פל\"ח."],["1421","29","<b>ע' בד\"ה כמגדל דוד צוארך</b>: סה\"מ תר\"ל ע' כז."],["1422","30","<b>ממ\"ש במ\"א בענין בעטרה שעטרה לו אמו</b>: ראה אוה\"ת בראשית שם י, ב. ובארוכה סה\"מ תרנ\"ט ע' י. פר\"ת ע' קנב. סה\"מ מלוקט ח\"ה ע' רמג. ועוד."],["1423","31","<b>ולכן בזמן הגלות הצדיק אבד</b>: בהבא לקמן עד סוף הפיסקא ראה בשינויים בד\"ה זה בסה\"מ תרל\"ג שם ע' רמד."],["1424","32","<b>ומעתה יובן ענין וה' פקד</b>: בהבא לקמן (עד פיסקא: וזהו ויאמר לו יהונתן) ראה ביאוה\"ז ומאמרי אדה\"ז תקס\"ג שנסמנו לעיל בתחילת המאמר."],["1425","33","<b>ועיין בפי' רש\"י ע\"פ והוא מסיבות. . ומ\"ש בזהר ע\"פ זה</b>: הובא ונת' בביאוה\"ז להצ\"צ ח\"א ע' לא ואילך. המשך תער\"ב ח\"ג ע' א'תכט ואילך. סה\"מ תש\"ד ע' 27 ואילך."]]],[2000510431,"מ\"מ מעיינים אם ראוי או אינו ראוי כו'. ועד\"ז יובן בענין בני חיי ומזוני שהגם שבמזלא תליא, מ\"מ צ\"ל דין ומשפט אם ראוי המבקש הדבר הזה שיעשו לו בקשתו, הן אמת כי בבחי' המזלא הם בחי' ונוצר ונקה אינו תופס מקום כלל, שהרי משם נמשך סליחות עוונות, מ\"מ יש דין ומשפט אם להעלות לשם וכנ\"ל במשל. ונמצא יתורץ מ\"ש וה' הוא וב\"ד הם ע\"ב סנהדרין שיושבין בהיכל הזכות לעיין אם ראוי למלאות בקשה זו ואח\"כ מעלים. וכן מ\"ש ועבדתם וגו' ובירך את לחמך ואת מימך לא תהי' משכלה ועקרה את מספר ימיך אמלא, דהן אמת שבני חיי ומזוני במזלא תליא, מ\"מ תלוי ג\"כ בזכות אם להעלות לבחי' מזלא, ולכן צ\"ל ועבדתם את ה' אלקיכם הוא בחי' וה' הוא וב\"ד בכדי שיזכה בב\"ד שראוי למלאות בקשתו בבני חיי ומזוני, ואז יעלו זה לבחי' מזלא כו', ומשם יומשך בני חיי ומזוני.\n<b></b>[סו)] וזהו פקדת הארץ, בכדי להיות פקידת הארץ בגשמים מבחי' מים שמעל השמים כו' שמ\"ג בחי' ז\"פ אור שבעת הימים כמ\"ש רש\"י בפסחים, מ\"מ צ\"ל אם בחוקתי תלכו שתהיו עמלים בתורה כי ואד יעלה מן הארץ ולפ\"ע ההעלאה כן נמשך ההמשכה, והגם כי מזוני תלוי במזלא, מ\"מ אם בחוקתי תלכו דוקא אז ונתתי גשמיכם וגו', והיינו כי ענין הגשם הוא באתעדל\"ת אתעדל\"ע, ולכן ע\"י ואד יעלה מן הארץ הוא ענין אם בחוקתי תלכו שתהיו עמלים בתורה עי\"ז ונתתי גשמיכם בעתם, וזהו כמו שבני במזלא תליא מ\"מ צריך להיות זכות כנ\"ל. וזהו פקדת הארץ ותשוקקי', והיינו כמו פקידת הארץ הגשמי הוא בגשמים, כ\"ה בענין מה שנש\"י קרוים ארץ כמ\"ש כי תהיו אתם ארץ חפץ, הנה פקידת הארץ זה הוא לבוא לבחי' תשוקה וכמארז\"ל במד\"ר בראשית פ\"ה למה נקרא שמה ארץ שרצתה לעשות רצון קונה, לשון רצוא והיינו הרצוא לבוא לשורש ומקור נש\"י שקדמו לכל<sup data-n=\"1426\">34</sup> כנ\"ל, והיינו להיות בבחי' ועמך לא חפצתי, פי' מי לי בשמים כי שמים וארץ ג\"ע התחתון והעליון, ובאמת צריך האדם לבוא במדריגת רצוא ותשוקה שלא יחפוץ לא בגעה\"ת ולא העליון ולא עוה\"ב, כל מה שהוא עמך אפי' בחי' כי עמך מקו\"ח מאחר שזהו רק עמך לא יחפוץ בזה, כ\"א שיהי' עיקר חפצו ורצונו לבחי' אוא\"ס ב\"ה העצמי ולא בבחי' מה שהוא עמך. וזהו פקדת ארץ הוא בחי' נש\"י להיות ותשוקקיה היינו להיות בבחי' תשוקה ליכלל וליבטל באוא\"ס ב\"ה עצמותו ומהותו.\n<b></b>[סז)] וזהו ויאמר לו יהונתן<sup data-n=\"1427\">35</sup> מחר חדש, פי' מחר יהי' יחוד שמשא וסיהרא, ונפקדת מלשון וה' פקד, שע\"י שיפקד מושבך פי' שיהי' חסר מקום מושבך, עי\"ז יפקדך אבי שאול מרחובות הנהר בחי' בינה, היינו מקור לבחי' ההשתלשלו' כענין מי ברא אלה, מי הוא בחי' בינה, ברא אלה ו\"ק דז\"א, ועי\"ז היינו ע\"י היחוד דשמשא",[["1426","34","<b>ארץ. . לשון רצוא והיינו הרצוא לבוא לשורש ומקור נש\"י שקדמו לכל</b>: בד\"ה זה בסה\"מ תרל\"ג שם תוקן בגוכי\"ק: ארץ. . לשון רצוא ותשוקה לבחי' אוא\"ס ב\"ה."],["1427","35","<b>וזהו ויאמר לו יהונתן</b>: בהבא לקמן עד סוף המאמר ראה מאמרי אדה\"ז תקס\"ז ואוה\"ת בראשית שם."]]],[2000510432,"וסיהרא יפקד מושבך הוא מושב בחי' המל'. ופי' ויאמר לו יהונתן, יהונתן הוא יה\"ו נתן, וע' במאו\"א יו\"ד נ\"ד, נתן ה\"א אחרונה ת\"ק בהכאה, וא\"כ יהונתן הוא שם הוי' י\"ה ו\"ה, לו היינו לדוד שהוא ג\"כ ה' אחרונה. וא\"כ צ\"ל מה\"ע ב\"פ ה\"א היינו ביהונתן וגם בדוד, שלפמ\"ש בכ\"ד פי' יהונתן ודוד הוא בחי' יה\"ו נתן אל דוד ה\"א אחרונה<sup data-n=\"1428\">36</sup>. אמנם לפי' המאו\"א הנ\"ל צ\"ל שזהו ב' בחי' שבמל' ים וארץ והיינו בחי' זנב לאריות וראש לשועלים שנת\"ל<sup data-n=\"1429\">37</sup>, ובחי' נתן שהוא עולה ת\"ק ה\"א בהכאה זהו בחי' מל' כמו שהוא בחי' ים המעלים בתוכו כל אורות ושפע המשפיע, ודוד הוא בחי' מל' כמו שהוא מקור לבחי' שלמטה שזהו הנקרא ארץ. וא\"כ פי' ויאמר לו יהונתן שדוד קיבל מאמר ודברי יהונתן זהו כענין הפך ים ליבשה, בחי' קרי\"ס. ואז אמר לו ושלשת תרד מאד, פי' ושלשת הוא כענין והשלישית יוותר בה וארז\"ל אלו ישראל שהם משולשים כהנים לוים וישראלים, והיינו בחי' סגול ע\"י העבודה, וכמ\"ש והייתם לי סגולה<sup data-n=\"1430\">38</sup> מכל העמים פי' מבחי' הבירור שמבררים מכל העמים בחי' כח\"ב דתהו ועי\"ז נעשי' בחי' סגולה מכל העמים, היינו בחי' סגולתא כח\"ב קדהק\"ד, קדשים חו\"ב קדש הקדשים כתר, או י\"ל ג' ראשי ראשים אור צח אור מצוחצח אור קדמון. ופי' תרד מאד עד שיהי' ההמשכה גם בעשי', וזהו וישבת אצל אבן האזל הוא בחי' עשי', והיינו שכמו בקרי\"ס ראתה שפחה הוא בחי' מדרגו' התחתונות דעשי' יותר ממה שראה יחזקאל, והיינו מפני שהאיר ונתגלה מבחי' יש האמיתי שלגבי' אצי' ועשי' שוין, כן ושלשת וגו' עד אבן האזל בחי' עשי'. אך גילוי זה יהי' לע\"ל ג\"כ בבחי' דוד דוקא כו' היינו משיח בן דוד. ולכן המטה שהי' אצל משה וקרע בו את הים איתא בי\"ח שהי' אצל כל מלך ממלכי יהודה וירושלים וכן עתיד להיות ביד מלך המשיח שנא' מטה עוזך וגו'.",[["1428","36","<b>שלפמ\"ש בכ\"ד פי' יהונתן ודוד. . יה\"ו נתן אל דוד ה\"א אחרונה</b>: ראה ד\"ה זה בסה\"מ תרל\"ג שם ע' רנג: אמנם רבינו ז\"ל פי' בכ\"ד שיהונתן הוא יה\"ו נתן אל דוד ה\"א אחרונה, נמצא כי זהו ענין יחוד שמשא וסיהרא כו', וגם לפי' המאו\"א יש ליישב. וראה מאמרי אדה\"ז תקס\"ז שם ע' נה. תקס\"ח ח\"א ע' תקלד. נביאים ע' יג. אוה\"ת בראשית שם יא, א. ברכה ע' א'תתצב."],["1429","37","<b>והיינו בחי' זנב לאריות וראש לשועלים שנת\"ל</b>: לעיל ד\"ה כל הנחלים פמ\"ג."],["1430","38","<b>פי' ושלשת. . בחי' סגול. . והייתם לי סגולה</b>: בהבא לקמן ראה בארוכה מאמרי אדה\"ז תקס\"ז שם ע' סב ואילך. מאמרי אדהאמ\"צ במדבר ח\"א שם ע' קנב ואילך. אוה\"ת בראשית שם יב, סע\"א ואילך."]]],[2000510433,"<h3>[כמראה הקשת]</h3>\n<b></b><b>[ד\"ה כמראה הקשת אשר יהי' בענן]\nבס\"ד. חג השבועות. </b>\nולהבין כו' כמראה הקשת\nחה\"ש\n<b></b>[סח)] ולהבין<sup data-n=\"1431\">1</sup> ביאור הדברים הנ\"ל בענין יהונתן ודוד, צ\"ל מ\"ש כמראה הקשת אשר יהי' בענן ביום הגשם כן מראה הנוגה סביב הוא מראה דמות כבוד ה', ונודע כי בקשת יש ג' גווני הקשת<sup data-n=\"1432\">2</sup>, ואיתא בזהר נח דע\"ב ב' לא תצפי לרגלי משיחא עד דאתחזי קשת בגוונין נהירין, ולכאו' יפלא מהו ענין הקשת כשיהי' בגוונין נהירין לרגלי משיחא, הלא הקשת הוא אות אשר הגם כי לא אכשיר דרא מ\"מ לא יהי' המבול לשחת כל בשר וכמ\"ש זאת אות הברית וגו', ומהו ענין אנפין נהירין דקשת לרגלי משיחא, שלכאו' אינם שייכים זל\"ז כלל. וגם צ\"ל מ\"ש במד\"ר נח פל\"ה ע\"פ והיתה הקשת בענין וראיתי' לזכור ברית עולם בין אלקי' ובין נפש כל חי', בין אלקי' זו מדה\"ד שלמעלה, ובין נפש כל חי' זו מדה\"ד שלמטה, מה\"ע שני בחי' מדה\"ד אלו, וגם מה\"ע וראיתי' לזכור ברית עולם הלא אין שכחה לפני כסא כבודך. וגם צ\"ל מה שסימן יהונתן לדוד הי' כשיורה בקשת ויאמר לנער הלא החצים ממך והנה קחנה ובאה כי שלום לך, ואם כה אומר לעלם הנה החיצים ממך והלאה לך כי שלחך ה', מהו ענין הקשת והחיצים דוקא, וגם מהו שלשת החיצים ולא די באחת או בשתים. הנה בתה\"ד סי' רל\"ג כתב לענין שם יהונתן<sup data-n=\"1433\">3</sup> בגיטין, וז\"ל ובשם יהונתן דקדקתי בספר שמואל ביהונתן בן שאול דמאז שכרת הברית עם דוד נכתב בכל מקום יהונתן, ומקודם לכן נכתב ברוב מקומות יונתן עכ\"ל, ולפ\"ז צ\"ל מהו ענין הה\"א שניתוסף לו ע\"י אשר כרת ברית עם דוד, ולכאו' זהו כענין ה\"א שניתוסף לאברהם ע\"י המילה, וצ\"ל זה.\n<b>הנה</b> כתיב עדות ביהוסף שמו<sup data-n=\"1434\">4</sup> בצאתו על ארץ מצרים שפת לא ידעתי אשמע, ופי' במאו\"א יו\"ד מ\"ם שה\"א הנוספת בשם יוסף הוא ה\"א עילאה ע' רברבא וממנה",[["1431","1","<b>ולהבין. . כמראה הקשת אשר יהי' בענן</b>: מהפטורת יום א' דחג השבועות (יחזקאל א, כח). והוא מאמר העשירי שבהמשך והחרים תרל\"א\".\nמאמר זה מיוסד על ביאור לד\"ה ויאמר גו' מחר חודש באוה\"ת בראשית יז, א. שם כא, ב ואילך. [ועוד דרושים שנסמנו לקמן בפרטיות].\nלהתחלת וסיום המאמר ראה ד\"ה כמראה הקשת באוה\"ת דרושים לחה\"ש ע' קז-ח. וראה גם מאמרי אדה\"ז תקס\"ד ע' קכז ואילך. אוה\"ת נח עא, א. שם (כרך ג) תרמח, א ואילך. תרנא, א ואילך. משפטים ע' א'שכ.\nחלק מהמאמר הובא ונתבאר בד\"ה ויאמר גו' מחר חודש (דש\"פ שמיני) תשמ\"ה. וראה גם ד\"ה ויאמר גו' מחר חודש (דש\"פ תולדות) תשד\"מ.\nלכללות המאמר ראה לקמן ע' שעב ד\"ה עדות ביהוסף שהוא רישומי דברים ממאמר זה. וראה עוד ע\"פ כמראה הקשת באוה\"ת נ\"ך ע' שצט. סה\"מ תר\"ל ע' לו-ז."],["1432","2","<b>ונודע כי בקשת יש ג' גווני הקשת</b>: ראה אוה\"ת נח עב, א. משפטים ע' א'שכ. דרושים לחגה\"ש ס\"ע קז-ח."],["1433","3","<b>בתה\"ד. . כתב לענין שם יהונתן</b>: בס' שו\"ת תרומת הדשן הובא באוה\"ת בראשית שם יז, א. ובד\"ה ויאמר גו' מחר חודש תשמ\"ה שם. וראה גם מאמרי אדהאמ\"צ במדבר ח\"א ע' קמח. ד\"ה ויאמר גו' מחר חודש תשד\"מ שם."],["1434","4","<b>הנה כתיב עדות ביהוסף שמו</b>: בהבא לקמן (עד פיסקא: ושרש ענין הבירורים) ראה רשימות הצ\"צ לתהלים יהל אור ע' רפה-ו. וראה גם אוה\"ת בראשית שם יז, א. אוה\"ת לך לך (כרך ד) תשכד, א. ד\"ה ויאמר גו' מחר חודש תשד\"מ שם."]]],[2000510434,"ידע ע' לשון, וסי' נלעג לשון אין בינה<sup data-n=\"1435\">5</sup> עכ\"ל, ובי\"נ<sup data-n=\"1436\">6</sup> הראה מקום בזח\"ג פנחס דרי\"ג ב' ושם ר' חייא פתח עדות ביהוסף וגו' הא אוקמוה דאוליף שבעין פתקין ולשון הקודש יתיר הה\"ד שפת לא ידעתי אשמע, אבל מאי עדות, ת\"ח בשעתא דאיתתא דפוטיפר הות אחידא בי' להאי מלה הוי יוסף עביד גרמי' כמאן דלא ידע לישנא דילה כו' עד ותתפשהו בבגדו, ורוה\"ק צווח לקבלי' לשמרך מאשה זרה, מאי קמ\"ל אלא כל דנטיר גרמי' מהאי אתקשר בה בשכינתי' ואחיד בההוא עדות, ומאי הוא ה\"א דאיתוסף בי' דכתי' עדות ביהוסף שמו. והרמ\"ז בפי' למאה\"ז הנ\"ל דקדק מהו הלשון פתקין, ופי' שזהו מלשון פותקין מים לגינה מערב שבת (בשבת די\"ח) ופי' נעקים קטנים<sup data-n=\"1437\">7</sup> שבהם יקרו המים לגינה. ועד\"ז פי' בענין ע' שרים שהם ע' [אומות] שנחלקו לע' לשון בעת שבלל ה' שפתם בדור הפלגה, ובהכרח הם צריכין לקבל חיות מהקדושה, אבל זהו ע\"י נהירא דקיק יוצא דרך בקיעה דקה מאד שיוצאת עד מקום ע' שרים, וע\"י ריבוי החילופי' והתמורות נשתנה עד שנעשו לשונות אחרים (גם י\"ל שלהיות הארץ תחלה שפה אחת ודברים אחדים בלשון הקדש, ואח\"כ בלל לשונם לע' לשון הרי נלקח זה מלשון הקדש), ולכן פרעה שמלך על ע' לשון כמו שהביא הרמ\"ז הי' צריך להכיר כל הע' לשונות, אבל על ישראל לא מלך עד גלות מצרים, לכן לא ידע לה\"ק, וז\"ש ולה\"ק יתיר. וכ' עוד הרמ\"ז שהס\"ם ונוק' נתלבשו בפוטיפר ואשתו, ולכן פוטיפר גימ' ס\"ם מלא, ואם היו מנצחים את יוסף הי' נחרב העולם, וכמארז\"ל הובא בילקוט נטל הקב\"ה אבן שתי' ואמר לו אם תגע בה הריני משליכה ומחריב את העולם, אבן שתי' מל' בת זוג דיוסף יסוד ז\"א, מאן דנטיר כו' ה\"א דאיתוסף בי', פי' ה\"א יסוד אימא שהנשמר מזונה נקשר בשכינתי' ומאיר לו אור הדעת. ונמצא לפי פי' הרמ\"ז ע' לשון זהו חיות ע' אומות. ורבינו ז\"ל פי' בביאור ע\"פ מה יפו פעמיך<sup data-n=\"1438\">8</sup> בנעלים שמה שידע יוסף ע' לשון בכדי שיהי' יניקה מועטת לע' שרים מיסוד ז\"א צדיק יסוד עולם, שידיעתו ע' לשון זהו שרש ההשפעה לע' שרים, מ\"מ הנה ארז\"ל בסוטה דל\"ו ב' שכשאמר ובלעדיך לא ירים אמרו אצטגניניו עבד כו' ימלוך כו' עד בא גבריאל ולמדו ע' לשון, לא הוי קא גמיר הוסיף לו אות בשמו שנא' עדות ביהוסף (וע\"ז כיוונו בזהר מ\"ש והא אוקמוה), א\"כ קודם שאמר פרעה ובלעדיך לא הוי ידע ע' לשון, ומ\"מ הי' ע' לשון גם קודם מאז בלל ה' שפת כל הארץ עד יוסף בעת שהי' במצרים, וא\"כ צריך לומר כמו שפי' הרמ\"ז. אמנם באמת עיקר החיות שלהם הוא כמ\"ש רבינו ז\"ל<sup data-n=\"1439\">9</sup> שמזה שידע יוסף ע' לשון זהו בכדי",[["1435","5","<b>וסי' [ וסימנך] נלעג לשון אין בינה</b>: ע\"פ לשון הפסוק ישעי' לג, יט: נלעג לשון (מי שאינו מכיר הלשון מצו\"ד) אין בינה."],["1436","6","<b>ובי\"נ</b>: וביאיר נתיב למאורי אור שם."],["1437","7","<b>מלשון פותקין מים לגינה. . ופי' נעקים קטנים</b>: ראה גם פירש\"י שבת יח, א שם: פותקין, פותחין, עושין נגר קטן משפת המעין לגינה."],["1438","8","<b>ורבינו ז\"ל פי' בביאור ע\"פ מה יפו פעמיך</b>: מאמרי אדה\"ז תקס\"ג ח\"א ע' רנא (בנוסחא הב'). ונו\"א שם ע' רסו. מאמרי אדהאמ\"צ דרושי חתונה ח\"א ע' צו. אוה\"ת שה\"ש (כרך ג) ע' תתקעו."],["1439","9","<b>כמ\"ש רבינו ז\"ל</b>: מאמרי אדה\"ז תקס\"ג שם."]]],[2000510435,"שיקבלו הע' לשון חיות מיוסף יסוד ז\"א צ\"ע, והיינו כי עיקר חיות הניצוץ הוא מה שנותנים לו חיות מהקדושה שיוכל להתעלות, ובלא זה ה\"ה בכלא ומאסר, ויוסף ע\"י שהי' במצרים נתן כח בהם שיוכלו להתברר, ע\"ד שנת' בד\"ה ויברך יעקב את פרעה<sup data-n=\"1440\">10</sup> הוא שנתן כח בפרעה שיוכל להתברר וכן יוסף נתן ג\"כ כח ע\"ז, וזהו סיבת ירידתו מה שהורד יוסף יסוד ז\"א למצרים, ומ\"מ הי' צריך לברכת יעקב כי אין קורין אבות אלא שלשה כו', וע' בד\"ה מי יתנך (ל\"א<sup data-n=\"1441\">11</sup>) מענין ירידת יוסף למצרים. וזהו שאמרו החייתנו פי' שהרגישו בעצמם חיותם שקיבלו מיוסף שהוא מה שנתן בהם כח שיוכלו להתעלות, וזהו שהעבירם ממקומם מקצה ארץ מצרים עד קצהו כמ\"ש בס\"פ ויגש, והיינו שעשה בהם הזזה ממקומם כו'.\n<b></b>[סט)] וביאור הענין הנה ארז\"ל בר\"ה יצא יוסף מבית האסורים<sup data-n=\"1442\">12</sup>, פי' שיוסף כמו שהוא במאסר בכלא זהו כשק\"נ חופה על יסוד ז\"א, ויציאתו מבחי' כלא פועל להיות בחי' כלה בה\"א כלתה נפשי, והיינו להיות ואל אישך תשוקתך, וזהו בר\"ה שאז זמן פקידת עקרות, וכנ\"ל בענין בני חיי ומזוני שבמזלא תליא כו', ומ\"מ צ\"ל וה' פקד, וממילא יוצא יוסף יסוד ז\"א לחירות, וגמר יציאתו לחירות הוא בשלימות הבירורים שיהי' לע\"ל במהרה בימינו אמן, כי הלא עדיין ג\"כ בכל ר\"ה יוצא יוסף מבית האסורים, והיינו מפני כי עדיין לא נגמרו הבירורים ובהכרח שהמברר יתלבש במקום המתברר, ולכן לא די במה שבחי' מל' יורדת לברר בירורים, אלא שגם הארת יסוד ז\"א בחי' יוסף הוא ג\"כ בכלא עד שמעט מעט יוצא בכל שנה, והיינו שגם עכשיו יש ענין יציאתו מבית האסורים, וזהו בר\"ה יצא יוסף היינו בכל זמן שיש ר\"ה עדיין. משא\"כ בגמר הבירורי' יצא לגמרי, ועצמות יוסף העלו ביציאתם ממצרים, ונודע כי יש בשר גידין ועצמות<sup data-n=\"1443\">13</sup>, ונמצא יש מה שנשאר עדיין במצרים, וכל הגליות נק' ע\"ש מצרים כמ\"ש במד\"ר, ולכן בכל ר\"ה יצא יוסף מבית האסורים.\n<b>ושרש</b> ענין הבירורים הוא בחי' ז' מלכין קדמאין שנפלו בשבה\"כ, והוא מ\"ש בספד\"צ<sup data-n=\"1444\">14</sup> פ\"א ז' מלכין קדמאין דמיתו וארעא אתבטלת, פי' וארעא אתבטלת פי' בזהר\"ק<sup data-n=\"1445\">15</sup> אם אין נחלים אין ים, ולכן ארעא אתבטלת, גם כי בנין המל' מהגבורות וצריכה לחסדים דדכורא להמתיק גבורות דנוק' וכשנפלו ז' מלכין קדמאין ומתו, וז' מלכין קדמאין הם מדעת עד יסוד, בלע הוא סוד הדעת לכן ארעא אתבטלת מפעולתה ומ\"מ לא נפלה בשבירה, וזהו סוד והארץ לעולם עומדת",[["1440","10","<b>שנת' בד\"ה ויברך יעקב את פרעה</b>: הוספות לביאוה\"ז לאדהאמ\"צ קלז, ב. ולהצ\"צ (כרך ב) ע' תשכז. תשלא. וראה גם אוה\"ת ויגש (כרך ו) תתשיג, א."],["1441","11","<b>וע' בד\"ה מי יתנך (ל\"א)</b>: לעיל ס\"ע קיח-ט. וש\"נ."],["1442","12","<b>וביאור הענין. . בר\"ה יצא יוסף מבית האסורים</b>: בהבא לקמן ראה יהל אור שם ע' רפו. אוה\"ת וארא ע' קפט. רלט."],["1443","13","<b>ונודע כי יש בשר גידין ועצמות</b>: ראה סה\"מ תרכ\"ט ע' נג ואילך. וש\"נ. תרל\"ג ח\"ב ע' שנ."],["1444","14","<b>בספד\"צ</b>: בספרא דצניעותא."],["1445","15","<b>בזהר\"ק</b>: בזהר הרקיע."]]],[2000510436,"כו'. אמנם רבינו ז\"ל פי' בלק\"ת בד\"ה כי תבואו וגו' ושבתה<sup data-n=\"1446\">16</sup> הארץ, שענין ארעא אתבטלת היינו בחי' מס\"נ בתפלה, ובמ\"א בת\"א בד\"ה קחו מאתכם תרומה<sup data-n=\"1447\">17</sup> פי' שזהו ענין קבלת עומ\"ש, א\"כ פי' אתבטלת הוא בחי' ביטול כו'.\n<b>והענין</b> יובן בהקדם ענין מיתת ז' מלכין קדמאין וסיבתם לזה, והוא לפי דכתי' והחיות רצוא ושוב, ויש בזה ב' פי'<sup data-n=\"1448\">18</sup>, הא' שחיות הקדש הם בבחי' רצוא ושוב, והב' שהחיות אלקי המחי' ומהוה נבראים הוא בבחי' רצו\"ש, ושני הפי' אמת ויציב, והיינו כי החיות רצו\"ש היינו בחי' חיות הקדש לפי שא\"א להיות תמיד בבחי' רצוא כ\"א כשרץ לבך שוב לאחד כמ\"ש בס\"י, וגם החיות שמחי' נבראי' הוא ג\"כ בבחי' רצו\"ש רק שמפני שזהו מלמעלמ\"ט הנה רצו\"ש זה הוא בחי' מטי ולא מטי התפשטות והסתלקות כמ\"ש ביאור ד\"ז במ\"א<sup data-n=\"1449\">19</sup>.\n[ע)] <b>ולהבין</b> בעבודה בנפש האדם ענין בחי' רצו\"ש דחיות, צ\"ל מה שאומרים בק\"ש שמע וגו' ואהבת והיו הדברים האלה, ששמע ואהבת הנה הם שייכים זל\"ז, אמנם מה\"ע והיו הדברים האלה לענין שמע ואהבת, וגם איך יוכל להיות כל היום בהתבוננות ובאהבה, אך הענין כך הוא, דהנה פי' שמע הוא שם עי\"ן<sup data-n=\"1450\">20</sup>, עי\"ן הוא בחי' ז' מדות וכל א' כלול מיו\"ד זהו ע', ושמע הוא שם עי\"ן היינו הארה מבחי' עי\"ן, ה' אלקינו חו\"ב, ה' אחד זו\"נ כמו שהוא בבחי' יחו\"ע דכולא קמי' כלא, וזהו פי' אחד הגם כי נתהוה ז' רקיעים וארץ [וד' רוחות] שע\"ז רומז חי\"ת דלי\"ת דאחד, מ\"מ ה\"ה בטלים לאל\"ף בחי' אוא\"ס ב\"ה אלופו של עולם. ומי שאין דעתו והשגתו נושאת לבחי' התבוננות זו דיחו\"ע לזה אומרים ברוך שם כבוד מלכותו לעולם ועד, פי' מלכותו הוא שם והארה, וכמו מלך שמו לבד נקרא עליהם, וכל ההתפשטות הוא רק מבחי' שמו לבד, אבל עצמות המלך אינו מתפשט כלל, וגם כל עיקר ענין המלוכה הוא קריאת שם ועי\"ז מקבלים אותו למלך לציית לרצונו כו', ולא נתחדש דבר כ\"א בקריאת השם, שהרי עצם האיש המולך הי' גם קודם שנעשה מלך ולא נשתנה בו דבר כ\"א בקריאת השם לבד, א\"כ מאחר שבו עצמו לא נתחדש דבר במלכו כ\"א קריאת שמו, כ\"ש שבהתפשטות על בני המדינה אינו שייך כ\"א התפשטות שמו לבד. ופי' כבוד מלכותו הנה כבוד הוא בחי' זיו כמ\"ש הת\"י ע\"פ מלא כל הארץ כבודו זיו יקרי', ונמצא לפ\"ז פי' כבוד מלכותו הוא בחי' הארת מל'",[["1446","16","<b>אמנם רבינו ז\"ל פי' בלק\"ת בד\"ה כי תבואו וגו' ושבתה</b>: פ' בהר מ, ד. וראה גם שם מ, ג."],["1447","17","<b>ובמ\"א בת\"א בד\"ה קחו מאתכם תרומה</b>: פ' ויקהל פט, א-ב."],["1448","18","<b>והחיות רצוא ושוב ויש בזה ב' פי'</b>: מהפטורת יום א' דחג השבועות (יחזקאל א, יד). וראה בהבא לקמן אוה\"ת תרומה ס\"ע א'שנז-ח. א'שסח. דרושים לחה\"ש ס\"ע קלט-מ. סה\"מ תרכ\"ט ע' רג ואילך. וראה גם מאמרי אדהאמ\"צ שמות ח\"א ע' רעט ואילך."],["1449","19","<b>מטי ולא מטי התפשטות והסתלקות כמ\"ש ביאור ד\"ז במ\"א</b>: ראה תו\"א בראשית ב, ד. הוספות לתו\"א קכג, א. לקו\"ת מסעי צה, ג. מאמרי אדה\"ז תקס\"ז ע' לא-ב. וע' לח. המשך תרס\"ו ע' מג ואילך."],["1450","20","<b>פי' שמע הוא שם עי\"ן</b>: ראה לקו\"ת בחקותי מז, ד. סה\"מ תרכ\"ו ע' צה. תר\"ל ע' קמ. קמט."]]],[2000510437,"לבד, וה\"ז הוא הארה דהארה לבד. ושם כבוד מלכותו הנה שם הוא הארה, וא\"כ זהו הארה דהארה דהארה, וכמשנת\"ל בדרך קצרה<sup data-n=\"1451\">21</sup>, וג' בחי' אלו י\"ל שזהו נגד ג' בחי' בי\"ע. ופי' לעולם ועד שכל העליות שיהיו לעולם ועד הכל הוא בבחי' שם לבד שז\"ע מ\"ש מלכותך מלכות כל עולמים, פי' כל הוא מספר נו\"ן והיינו נו\"ן אלפי' יובלות, ששית אלפי שני דעכשיו הם שבוע א', ויש שנה ושמיטה וז' שמיטות<sup data-n=\"1452\">22</sup> ויובל ונו\"ן יובלות, וכל עליות אלו הם רק בבחי' שמך לבד, וזהו אשר שם שמות בארץ א\"ת שמת אלא שמות, כמשנ\"ת באורך בלק\"ת בד\"ה את שבתותי<sup data-n=\"1453\">23</sup> תשמרו, ואי לזאת ואהבת פי' אהבה הוא מל' אבה שפי' רצון<sup data-n=\"1454\">24</sup>, שלא יהי' לו רצון אחר כ\"א שיהי' את היינו בחי' את הטפל לבחי' ה' אלקיך<sup data-n=\"1455\">25</sup>, היינו להיות בבחי' ועמך לא חפצתי שזהו מצד התבוננות דיחו\"ע, ושיהי' בכל לבבך בשני יצריך שגם היצה\"ר ישוב לאהבת ה', והיינו ע\"י בחי' השכל דיצה\"ר, דאילו מצד המדות דיצה\"ר לא הי' יכול לו, רק מצד השכל שמחייב לו שיחפוץ לילך בשרירות לבו, הנה כאשר יראה לו ע\"פ השכל שגם בשארי ענינים טוב יותר שיחפוץ בקרבת אלקות, אז הנה גם הוא יסכים לזה, להיות כי ע\"פ שכלו יהולל איש היינו גם מלך זקן וכסיל שה\"ה יצה\"ר שבאדם, ולכן ע\"פ השכל שלו עצמו יהולל פי' יומשך ויונהג המדות שלו, ובדרך זה יוכל לפעול גם אצלו בחי' הביטול או הסכם עכ\"פ שלא ינגד לזה, והוא ע\"י אריכות ההתבוננו' בשתים לפניה איך שהאופנים וחיות הקודש הם ברעש גדול וכשרואה ששורש שרשו בטל<sup data-n=\"1456\">26</sup> פועל גם בו הביטול להיות בבחי' הסכם עכ\"פ וממילא לא ינגד, או שגם הוא יהי' בבחי' ביטול, שזהו הפי' בשני יצריך שגם היצה\"ר ישוב לאהבת ה', וזה תלוי לפ\"ע תקפו ולפ\"ע ההתבוננו' אם רב או מעט, ואם מעט לו ההתבוננו' שלכן אינו בטל כ\"א מסכים שזהו רק הזזה ממקומו לבד, אזי יוסיף לו התבוננו' כהנה וכהנה עד שיעורר אותו עצמו להיות בבחי' בטל רצונך כו' כאשר פועל בעצמו להיות בכל לבבך בשני יצריך. אבל איך יגיע לזה וימצא בחי' אוא\"ס ב\"ה שיוכל להשיג שזהו אינו בחיק הנבראים שיוכלו להשיג אוא\"ס ב\"ה, לזה אומר אח\"כ והיו הדברים האלה וארז\"ל בדברי תורה הכתוב מדבר, והיינו כי אורייתא מחכ' נפקת והשראת א\"ס הוא בחכ', כי החכ' נק' אחד האמת כמ\"ש בסש\"ב פל\"ה בהג\"ה, ולכן אמרו אורייתא וקוב\"ה כולא חד שיחוד אוא\"ס ב\"ה בתורה<sup data-n=\"1457\">27</sup> הוא בחי' יחוד דאיהו וחיוהי, כי התורה",[["1451","21","<b>וכמשנת\"ל בדרך קצרה</b>: בד\"ה ויאמר גו' מחר חודש פס\"ד. וראה לקו\"ת אמור לא, סע\"ג-ד."],["1452","22","<b>ששית אלפי שני דעכשיו הם שבוע א' ויש שנה ושמיטה וז' שמיטות</b>: ראה תו\"א שמות נא, ד. מאמרי אדהאמ\"צ דברים ח\"א ע' רסח. וש\"נ. סה\"מ תרס\"ח ע' מז."],["1453","23","<b>כמשנ\"ת באורך בלק\"ת בד\"ה את שבתותי</b>: פ' בהר מא, ד."],["1454","24","<b>פי' אהבה הוא מל' אבה שפי' רצון</b>: ראה תו\"א מקץ לב, א. נשא כו, ב. בלק עא, ב. מסעי פח, ד. ואתחנן ב, ג. ט, ב. שה\"ש יז, א. ספר החקירה להצ\"צ צב, רע\"א."],["1455","25","<b>היינו בחי' את הטפל לבחי' ה' אלקיך</b>: ראה לקו\"ת ואתחנן ז, ד. לעיל ד\"ה וישב יעקב. ועוד."],["1456","26","<b>ההתבוננו' בשתים לפניה. . וכשרואה ששורש שרשו בטל</b>: ראה תו\"א וישב ל, ב. לקו\"ת ויקרא ב, ב. תצא לד, ד. סה\"מ תרכ\"ט ס\"ע רפג ואילך."],["1457","27","<b>שיחוד אוא\"ס ב\"ה בתורה. . יחוד דאיהו וחיוהי. ֿ. אור. . לפי' חיוהי מוחין</b>: ראה בכ\"ז סה\"מ תרל\"ג ח\"ב ס\"ע שמז ואילך. וש\"נ."]]],[2000510438,"היא אור וכמ\"ש ותורה אור לכן היחוד ע\"ד איהו וחיוהי, וכשלומד תורה אזי הוא מדבר דבר ה' וכמ\"ש ודברי אשר שמתי בפיך, תען לשוני אמרתיך כעונה אחר הקורא, וכמ\"ש המגיד להב\"י אני המשנה המדברת בפיך, וכח זה הוא ממ\"ת שזהו תיבת לאמר שבפסוק וידבר כמ\"ש ביאור ד\"ז במ\"א<sup data-n=\"1458\">28</sup>.\n<b>וזהו</b> ענין רצוא ושוב, רצוא הוא בחי' התשוקה ליכלל וליבטל באוא\"ס ב\"ה הוא בחי' ועמך לא חפצתי כו', אך אם רץ לבך שוב לאחד הוא בחי' והיו הדברים האלה בדברי תורה הכתוב מדבר, שזהו בחי' אחד עצמו דיחו\"ע, כי אורייתא וקוב\"ה כולא חד בחי' איהו וחיוהי כנ\"ל, גם לפי' חיוהי מוחין ג\"כ זהו בחי' איהו וחיוהי כי אורייתא מחכמה נפקת.\n<b></b>[עא)] אמנם כ\"ז הוא בבחי' התיקון שיש בהם בחי' ההתכללות בבחי' רצו\"ש, אבל בתהו לא הי' בהם בחי' ההתכללות כ\"א נקודות זה תחת זה, והאור הי' בהם בריבוי כמ\"ש במ\"א<sup data-n=\"1459\">29</sup>, ע' בד\"ה אם בחוקתי והביאור (ך\"ו<sup data-n=\"1460\">30</sup>), לכן הי' בהם שבירה שנשברו הכלים ונפלו רפ\"ח ניצוצין בשבה\"כ, והאורות נסתלקו, עד\"מ תיבת ברוך שיש בו השכלה בל\"א גילובט, וכאשר מפרידין הבי\"ת בפ\"ע ורי\"ש בפ\"ע וא\"ו בפ\"ע כ\"ף בפ\"ע הלא לא יש בהם השכלה כלל, ועד\"ז יובן בענין שבה\"כ דתהו. אמנם בחי' המל' לא נשברה להיות כי מדת המל' בעצמה ה\"ה סובלת ב' הפכים יחד, שהיא היא עצמה היא בחי' רוממות והתנשאות, ומ\"מ ה\"ה בחי' יראה בחי' ירושלים שלימות היראה, והרי זהו שני הפכים, ועכצ\"ל שיש בה בחי' הביטול ביותר עד שיכולה לסבול שני ההפכי' יחד, ולכן מצד הביטול ומה גם שאינה דומה לשארי המדות כמו חסד שהוא חסד ולא גבורה, וכן במדת הגבורה שהיא רק גבורה ולא חסד, משא\"כ בחי' מדת המל' ה\"ה סובלת ב' הפכים כנ\"ל, לכן לא הי' בה שבירה כ\"א ביטול, שזהו שא' וארעא אתבטלת לפי' הזהר\"ק זהו מחמת כי אם אין נחלים אין ים, וכמשנת\"ל באריכות בענין נחלים וים, וכן מ\"ש שהנוק' צריכה לקבל שפע החסדים בכדי להמתיק הגבו' שלה, ונמצא כי ז\"ע היחוד דזו\"נ. אמנם לפי' רבינו ז\"ל ארעא אתבטלת היינו בחי' מס\"נ דתפלה או קבלת עומ\"ש. ובאמת י\"ל דלא פליגי כלל, והיינו כי מ\"ש בזהר\"ק אם אין נחלים אין ים, צ\"ל הלא כתי' יקוו המים ונמצא כי יש בריאת הים גם בלתי שפע הנחלים ג\"כ, ועכצ\"ל שעצם בריאתה זהו בחי' עצם נקודת המל', ומה שמקבלת מהנחלים זהו ע\"ד כמו בתיקון שממל' דט\"ס נעשו ע\"ס במל', כן הי' עד\"ז בתהו גם כשלא הי' בהם בחי' התכללות, וכן בענין היחוד כנ\"ל ז\"ע כמו",[["1458","28","<b>שזהו תיבת לאמר שבפסוק וידבר כמ\"ש ביאור ד\"ז במ\"א</b>: ראה תו\"א יתרו סז, ב. ובהוספות קט, א. לקו\"ת שה\"ש מב, סע\"א. סה\"מ תרל\"ג ח\"א ע' רצז."],["1459","29","<b>בתהו לא הי'. . התכללות כ\"א נקודות זת\"ז והאור. . בריבוי כמ\"ש במ\"א</b>: ראה תו\"א שמות נא, סע\"ד ואילך. סה\"מ תרכ\"ח ע' קסג. תרל\"ג ח\"א ע' קיד. וש\"נ."],["1460","30","<b>ע' בד\"ה אם בחוקתי והביאור (ך\"ו)</b>: סה\"מ תרכ\"ו ע' צו. והביאור ע\"ז נדפס בתוך ד\"ה ואהי' אצלו אמון בסה\"מ תר\"ל ע' קנ. [ראה סה\"מ תרכ\"ו שם ע' ]."]]],[2000510439,"ויבן ה' אלקי' את הצלע בבחי' התיקון עד\"ז צ\"ל מעין זה בתהו, אבל עצם הנקודה דים לא נתבטל כלל גם לפי' הזהר\"ק שהרי ביאר רק ענין שלא יש פעולה ממה שנשארה. ומה שפי' רבינו ז\"ל בחי' מס\"נ דתפלה או קבעומ\"ש זהו עצם נקודת פנימי' המל' כו', ומ\"מ י\"ל גם לדברי רבינו ז\"ל ג\"כ לא יש תועלת כ\"כ ממה שנשארה המל', אם כי פי' אתבטלת זהו דוקא כשיש אח\"כ בחי' שש שנים, והיינו שפי' ושבתה הארץ זהו בחי' מס\"נ דתפלה ארעא אתבטלת, וצ\"ל תחלה ושבתה בחי' אתבטלת ואח\"כ שש שנים זהו שיתא סדרי משנה, אמנם בתהו שז\"ת נפלו בשבירה, א\"כ לא יש בחי' השש שנים וממילא אין תועלת מבחי' ביטול המל', וז\"ע בחי' התיקון לברר הניצוצות דתהו שנפלו בשבירה, וזהו ויוסף יסוד ז\"א ששורשו ביסוד דא\"ק, הורד מצרימה לעשות הכנה להבירור דשם שיבררו ישראל ע\"י השעבוד ע\"ד מצרף לכסף כמ\"ש במ\"א<sup data-n=\"1461\">31</sup>, עד שהוסיפו לו ה' עילאה משמו של הקב\"ה שעי\"ז גמר העי\"ן לשון כמשרז\"ל בסוטה די\"ג ב', והיינו שזהו הוראה על הבירור, וכ\"ז בא לו ע\"י שעמד בנסיון באשת פוטיפר והיינו כמ\"ש הרמ\"ז שס\"ם ונוק' נתלבשו בפוטיפר ואשתו, ואם היו מנצחים את יוסף ח\"ו הי' מאבד העולם לגמרי, וכמארז\"ל נטל הקב\"ה אבן שתי' (שממנה הושתת העולם) בידו וא\"ל אם אתה נוגע בה הריני משליכה ומחריב את העולם, וי\"ל שעיקר קיום העולם הוא בג' דברים שהעולם עומד עליהם, ולהיפך ח\"ו מוטב שיאבד העולם ע\"ד ששבר משה הלוחות בכדי שלא ידונו בחמורה כידוע מארז\"ל בזה, או י\"ל ע\"ד שבה\"כ דתהו שהי' בכוונה סותר ע\"מ לבנות התיקון כמשנ\"ת לעיל מזה. אמנם ע\"י שעמד בנסיון הנה עי\"ז נתדבק בשכינתי' כמ\"ש בזהר ורמ\"ז, עי\"ז ולאום מלאום יאמץ, ולכן עי\"ז זכה למלוך ולידע ע' לשון היינו לברר את בחי' ע' לשון הוא בחי' ע' שרים כו', וכן כל איש אשר רוח ה' בקרבו יוכל לבוא לבחי' זו ע\"י שמירת הברית שלא יפגום ח\"ו, והעיקר בזה הוא לאו דלא תנאף, ועי\"ז אתדביק בשכינתי' וזוכה להאי עדות, ומאי איהו ה\"א עדות ביהוסף כו' כמ\"ש בזהר.",[["1461","31","<b>ויוסף. . הורד מצרימה לעשות הכנה. . שיבררו ישראל. . ע\"ד מצרף לכסף כמ\"ש במ\"א</b>: ראה לעיל ד\"ה מי יתנך ס\"ע קיח-ט. וש\"נ."]]],[2000510440,"<h3>ומעתה יובן כו' בעטרה שעטרה]</h3><h3>ומעתה יובן כו' בעטרה שעטרה]</h3>\n[עב)] ומעתה יובן ענין דוד ויהונתן<sup data-n=\"1462\">1</sup>, שכ' בתה\"ד סי' רל\"ג הנ\"ל שעד שכרת ברית עם דוד נק' יונתן ואחר הכריתות ברית נק' ברוב המקומות יהונתן. ויובן [בהקדם] ענין מ\"ש בעטרה שעטרה לו אמו ביום חתונתו וארז\"ל במשנה סוף תענית ביום חתונתו זו מ\"ת, והגם ששם הכוונה על יוהכ\"פ שבו ניתנו לוחות אחרונות, שהרי מביא זה לראי' שלא היו יו\"ט לישראל כו' וכיוהכ\"פ, מ\"מ מ\"ת הוא בחגה\"ש שלא הי' יום מ\"ת שנית בנתינת לוחות האחרונות כ\"א מה שירד ה' על ה\"ס בחג השבועות זמן מתן תורתינו.",[["1462","1","<b>ומעתה יובן ענין דוד. . ענין מ\"ש בעטרה</b>: בגוכי\"ק נסמן בצידי הגליון שכאן מתחיל מאמר חדש. אך לא נרשם ברשימת מאמרי דא\"ח (שבעריכת כ\"ק אדמו\"ר)."]]],[2000510441,"<b>ויובן</b> בהקדם הבנת ענין מה שמ\"ת הי' ביום החמישים<sup data-n=\"1463\">2</sup> לצאת בנ\"י מאמ\"צ כמ\"ש וספרתם לכם וגו' תספרו חמשים יום והקרבתם וגו', ואין סופרים כ\"א מ\"ט יום ולמחרת יום המ\"ט הוא חגה\"ש, וכמשנ\"ת בלק\"ת שיום החמשים בא ממילא<sup data-n=\"1464\">3</sup> אחר ספירת מ\"ט יום, וע\"י ספירה א\"א להגיע, כ\"א אחר ספירת מ\"ט הוא יום החמשים והוא בחי' שער החמשים דבינה, וצ\"ל ביאור ענין שער החמשים מהו. והענין הוא דאיתא בס\"י בשלשים ושתים נתיבות פליאות חכ' חקק כו', וכתיב נתיב לא ידעו עיט<sup data-n=\"1465\">4</sup> ולא שזפתו עין איה, והיינו שבל\"ב נתיבות אלו יש נתיב אחד שלא ידעו כלל, וגם עין איה היינו המלאכי'<sup data-n=\"1466\">5</sup> שאומרים איה מקום כבודו, וזהו דכתי' ויקרא לו אל אלקי ישראל, וארז\"ל במד\"ר הקב\"ה קרא ליעקב אל, היינו שנגלו לו בחי' ל\"א נתיבות חכ'<sup data-n=\"1467\">6</sup>, וזהו אל אלקי, אל הוא ל\"א נתיבות הנ\"ל, וכמו שהוא בחכ' כן משארז\"ל עתיד הקב\"ה להנחיל לכל צדיק וצדיק ש\"י עולמות שנא' להנחיל אוהבי יש הוא ג\"כ כנ\"ל, כי ל\"א כשהם כלולים מיו\"ד הם ש\"י, והיינו שזהו מהארת החכ' שמאיר בבינה אז נעשה מן ל\"א ש\"י, וכמו שבחכ' יש נתיב אחד שלא ידעו עיט כן בבינה יש שער אחד שאינו מושג, והוא בחי' שער החמשים דבינה שהוא המחבר בחי' האין דחכ' עם היש דבינה, וכנודע שהמחבר צ\"ל שורשו גבוה משניהם בכדי שיוכל לחבר<sup data-n=\"e71\">יד</sup>, כמ\"ש מזה במ\"א<sup data-n=\"1468\">7</sup>.\n<b></b>[עג)] והנה משה בעת הסתלקותו השיג בחי' שער הנו\"ן דבינה, ועפ\"ז יובן מה שארז\"ל במשנה פ\"ה דאבות בענין עשרה דברים נבראו בערב שבת בין השמשות<sup data-n=\"1469\">8</sup>, וי\"א אף קבורתו של משה, דלכאו' יפלא הלא כתיב בראשית ברא אלקים את השמים ואת הארץ, וקבורתו של משה הוא ג\"כ בארץ, וא\"כ מהו\"ע שנברא",[["1463","2","<b>ויובן בהקדם הבנת ענין מה שמ\"ת הי' ביום החמישים</b>: בהבא לקמן (עד ס\"פ עג) ראה בהרחבת הביאור לקמן ד\"ה וביום הביכורים (פרקים עו-פא)."],["1464","3","<b>וכמשנ\"ת בלק\"ת שיום החמשים בא ממילא</b>: לקו\"ת במדבר יב, א ואילך."],["1465","4","<b>בשלושים ושתים נתיבות. . נתיב לא ידעו עיט</b>: ראה לקו\"ת בהעלותך לו, ג. אוה\"ת בראשית (כרך ג) תקסח, סע\"ב. לך לך (כרך ד) תשז, א. נ\"ך ס\"ע תצא. סה\"מ תרל\"ב ח\"א ע' לח."],["1466","5","<b>עין איה היינו המלאכים שאומרים איה מקום כבודו</b>: ראה תקו\"ז ת\"ל (עו, א): נתיב קדמאה עלי' אתמר נתיב לא ידעו עיט ולא שזפתו עין איה, מאן עין איה, אלא אינון מלאכין דאמרין איה מקום כבודו. הובא ונת' באוה\"ת לך לך (כרך ד) שם תשז, א. סה\"מ תרנ\"ח ע' כ-כא."],["1467","6","<b>וזהו דכתי' ויקרא לו אל אלקי ישראל. . הקב\"ה קרא ליעקב אל. . ל\"א נתיבות חכ'</b>: ראה סה\"מ תרל\"ב ח\"א שם ע' לח. וש\"נ. וע' קצט."],["1468","7","<b>וכנודע שהמחבר צ\"ל שורשו גבוה משניהם. . כמ\"ש מזה במ\"א</b>: ראה אוה\"ת וירא ק, סע\"ב ואילך. ביאוה\"ז להצ\"צ ח\"ב ע' תשעה. [ובהנסמן לקמן הערה ד\"ה: ענין הקרן זוית]."],["1469","8","<b>והנה משה בעת הסתלקותו. . עשרה דברים נבראו בערב שבת בין השמשות</b>: בהבא לקמן בפיסקא זו ראה אוה\"ת נח (כרך ג) תרנג, א. וירא שם ק, סע\"ב ואילך. ביאוה\"ז להצ\"צ ח\"ב שם ע' תשעה-ו. [ובהנסמן בהערות שלאח\"ז]. וראה גם אוה\"ת ואתחנן ע' קנג.\n\n<b>יד</b>  <b>בכדי שיוכל לחבר</b>: בגוכי\"ק נוסף כאן [ואח\"כ נרשם ע\"ז שא\"צ להעתיקו]: וי\"ל שכמו\"כ צ\"ל באין דחכ' ג\"כ, וזהו נתיב הל\"ב עם השער הנו\"ן דבינה."]]],[2000510442,"קבורתו של משה בערב שבת בין השמשות. והענין הוא דהנה ענין בין השמשות הוא לא יום ולא לילה, כ\"א שהוא מחבר יום ולילה, והוא בעצמו אינו מהות כלל<sup data-n=\"1470\">9</sup>, וכמו ענין הקרן זוית שהוא עצמו אינו מהות בפ\"ע<sup data-n=\"1471\">10</sup>, כי כל מה שנמשך בכותל מזרח עד\"מ ה\"ה מזרח, וכל כמה שנמשך בכותל דרום הוא דרום, וא\"כ מהו הקרן, הנה הוא אינו מהות בפ\"ע כלל כ\"א שהוא מחבר, ועד\"ז יובן בענין בין השמשות שהוא אינו לא יום ולא לילה כ\"א המחבר, וא\"כ כשהוא אינו מהות בפ\"ע ה\"ה בבחי' ביטול ואין, שאינו תופס בעצמו שיהי' דבר בפ\"ע כ\"א אין וביטול. ולכן בית קבורתו של משה שארז\"ל ע\"ז לעליונים נדמה להם למטה ולתחתונים נדמה להם למעלה<sup data-n=\"1472\">11</sup>, פי' לעליונים נדמה להם למטה היינו בבחי' חכ'<sup data-n=\"1473\">12</sup>, ולמעלה נדמה להם שזהו למטה, ופי' נדמה שזהו רק דמיון, אבל באמת הנה הוא למעלה, וכנ\"ל בענין המחבר כו', ולתחתונים היינו מבינה ולמטה נדמה להם למעלה. וכשהי' צריך לבוא בחי' זו בבחי' בריאה, הגם כי הארץ נבראת ביום ראשון אמנם זהו בד\"כ, אבל בפרטיות בכדי לבוא לבחי' בריאה דבר פלא וגבוה כזו דקבורתו של משה שלעליונים נדמה כו', א\"א הי' שיברא ביום פרטי כ\"א בבין השמשות שהוא אין, וגם איזה בין השמשות, בין השמשות דערב שבת, ונודע כי אותו ערב שבת הי' ר\"ה כי בך\"ה באלול נברא העולם, ואדה\"ר נברא ביום וא\"ו למע\"ב שהוא ר\"ה, ובר\"ה הוא תקיעת שופר שנודע ששופר הוא בחי' בינה, ושבת הוא בחי' קדש כמ\"ש ושמרתם את השבת כי קדש היא, וא\"כ הבין השמשות דערב שבת הנ\"ל שהוא ר\"ה שופר בינה, ויום השבת הוא קדש, הנה הממוצע ביניהם הוא בחי' שער הנו\"ן וכנ\"ל, ולכן נברא אז בית קבורתו של משה כמדרגתו שבעת הסתלקותו השיג בחי' שער הנו\"ן דבינה, לכן בערב שבת בין השמשות דברה\"ע שהיא ג\"כ בחי' שער הנו\"ן נברא אז בית קבורתו, והיינו שאז נתגלה בחי' זו בארץ שבכללה נברא ביום ראשון כו'.\n<b>ועפ\"ז</b> יובן ענין מ\"ת שהי' ג\"כ ביום החמשים, דהנה ארז\"ל ע\"פ אמרות ה'<sup data-n=\"1474\">13</sup> וגו' מזוקק שבעתים א\"ר ינאי לא ניתנו דברי תורה חתוכין למשה אלא מ\"ט",[["1470","9","<b>בין השמשות הוא לא יום ולא לילה. . בעצמו אינו מהות כלל</b>: ראה בכ\"ז [נוסף להנסמן בהע' שלפנ\"ז] סידור עם דא\"ח נא, ד. מאמרי אדהאמ\"צ נ\"ך ע' קעו. לקו\"ש ח\"ד ע' 1223. שיחת ש\"פ נצו\"י תשמ\"ב (התוועדויות תשמ\"ב ח\"ד ע' 2242. 2250). שיחת ש\"פ בהו\"ב תשמ\"ה (התוועדויות תשמ\"ה ח\"ד ע' 2079). וראה גם לקו\"ש חי\"ב ע' 81 (בשוה\"ג). ס' מפענח צפונות ע' קעז-ח."],["1471","10","<b>ענין הקרן זוית. . אינו מהות בפ\"ע</b>: ראה בארוכה ביאוה\"ז לאדהאמ\"צ קמד, ג ואילך. ולהצ\"צ ח\"א ע' תסד ואילך. אוה\"ת נ\"ך ע' קלו ואילך. סה\"מ תרכ\"ז ע' קעו. תרכ\"ט ע' לח. רפט. ועוד."],["1472","11","<b>שארז\"ל ע\"ז לעליונים נדמה להם למטה ולתחתונים נדמה להם למעלה</b>: בהבא לקמן ראה [בשם הה\"מ]: מאמרי אדה\"ז תקס\"ה ח\"א ע' קפד. לקו\"ת במדבר יב, א. אוה\"ת ברכה (כרך ה) ע' ב'קסג ואילך. ועוד."],["1473","12","<b>פי' לעליונים נדמה להם למטה היינו בבחי' חכ'</b>: ראה לקו\"ת במדבר שם יב, סע\"א [ועד\"ז במקומות שנסמנו בהע' שלפנ\"ז]: כי שער החמשים דבינה הוא הממוצע בין חכמה לבינה כו', ולכן לעליונים היינו לגבי אין ממש נדמה למטה כו', ולגבי תחתונים בחי' יש והשגה נדמה שהוא למעלה דהיינו שהוא בחי' אין ממש."],["1474","13","<b>ועפ\"ז יובן ענין מ\"ת. . ארז\"ל ע\"פ אמרות ה'</b>: הבא לקמן בפיסקא זו מיוסד על אוה\"ת יתרו ע' תתצא-ב [ד\"ה וידבר גו' לאמר]. וראה גם סה\"מ תרכ\"ז ס\"ע שב ואילך. וע' שיג. סה\"מ תרנ\"ח ע' מד. עת\"ר ע' קיז-ח. עטר\"ת ס\"ע תג-ד. תרפ\"ח ע' קלא-ב."]]],[2000510443,"פנים טהור ומ\"ט פנים טמא, והיינו נגד ז' מדות וכ\"א כלול מז' ה\"ה מ\"ט, וענין מ\"ט פנים טהור ומ\"ט פנים טמא זהו נגד חו\"ג<sup data-n=\"1475\">14</sup> בכלל, וז\"ש דודי צח ואדום, צח עולה ב' פעמים מ\"ט, וגם צ\"ח ואדום הם חו\"ג, וי\"ל שבתיבת צח מרומז גם מ\"ט פנים טמא ג\"כ להורות על הגברת החסדי' על הגבורות דגבורה, לכן בתיבת צח שרומז על חסדים נכללים בו במספר גם מ\"ט פנים דגבורה ג\"כ, וזהו בחי' תורה שמבררת בירורים. אמנם יש בתורה בחי' הגבוה יותר וכמשי\"ת לקמן אי\"ה, לכן הי' מ\"ת ביום החמשים דוקא להורות על בחי' שער הנו\"ן דתורה שדרך בו ניתנה התורה גם בחי' טל תורה וכמשי\"ת, ועל התורה נאמר לא בשמים, כ\"א ניתנה למטה בארץ דוקא בכדי לברר הניצוצות שנפלו ולעשות מבחי' הפירוד שבארץ דוקא בחי' אחד, וזהו ע\"י התורה וישראל וכמ\"ש ומי כעמך כישראל גוי אחד בארץ, שעושים גם בארץ שיהי' בחי' אחד בחי' אחדות כו'.\n<b></b>[עד)] וכ\"ז הוא הקדמה להבין ענין דוד ויהונתן<sup data-n=\"1476\">15</sup>, דהנה דוד הוא ב' דלתי\"ן והוא\"ו מחבר ב' הדלתי\"ן, והענין דהנה דל\"ת הוא מלשון דל, והיינו ענין העוני והדלות, וגם דל\"ת הוא מלשון דלו עיני למרום, ולכאורה ענינם אחד שמהיותו דל ה\"ה מגביה עיניו למרום, וכענין שאמרו יאה עניותא כו'. אך באמת י\"ל דפי' דלו עיני למרום הוא כי מרום הוא בחי' כתר כמ\"ש ואתה מרום לעולם ה', וארז\"ל במד\"ר רוממות אתה נוהג<sup data-n=\"1477\">16</sup> בעולמך, כהונה לעולם, מלכות בית דוד לעולם, שזהו מבחי' כתר ונמצא כי ענין דלו עיני למרום הוא בחי' חו\"ב שהם בבחי' הבטה למרום כתר.\n<b>ולהבין</b> ביאור הענין, הנה ארז\"ל לעולם יכנס אדם שיעור שני פתחים ואח\"כ יתפלל<sup data-n=\"1478\">17</sup>, שנא' אשרי אדם שומע לי לשקוד על דלתותי ב' דלתות והיינו ב' פתחים, והם הם ב' דלתי\"ן שבדוד. והענין הוא דלת הוא הפתח שיש בה ב' מזוזות ומשקוף, וענין ב' המזוזות הם נו\"ה והמשקוף הוא ת\"ת, ובעבודה הוא ענין מה שמתחילי' בתפלה בהודאה הודו לה' קראו בשמו, ועוד קודם לזה בברכת השחר",[["1475","14","<b>וענין מ\"ט פנים טהור. . טמא זהו נגד חו\"ג</b>: באוה\"ת יתרו וסה\"מ תרכ\"ז שם הובא זה בשם המגלה עמוקות אופן רמ\"ה."],["1476","15","<b>וכ\"ז הוא הקדמה להבין ענין דוד ויהונתן</b>: בהבא לקמן בפיסקא זו ראה אוה\"ת בראשית שם יז, א."],["1477","16","<b>מרום הוא בחי' כתר כמ\"ש ואתה מרום. . רוממות אתה נוהג</b>: ראה אוה\"ת קדושים ס\"ע קח-ט. ואתחנן ע' עג. סה\"מ תרכ\"ז ע' רצב. שפט. תרל\"ב ח\"א ע' קסח. וראה גם פיה\"מ לאדהאמ\"צ פו, ג."],["1478","17","<b>ולהבין ביאור הענין. . שיעור שני פתחים ואח\"כ יתפלל</b>: בהבא לקמן בפיסקא זו ראה אוה\"ת חנוכה שכה, א ואילך. שלה, סע\"ב. ויגש (כרך ה) תתקפו, ב. בא ע' שי ואילך. קרח ע' תרסג ואילך. תשג ואילך. ואתחנן ע' שנג. שם (כרך ו) ע' ב'רפה ואילך. נ\"ך ע' תכ. תקצ. סה\"מ תרכ\"ו ע' קמז ואילך. תרכ\"ט ע' שח. תרע\"ח ע' רמד ואילך. ובארוכה סה\"מ תרל\"ב ח\"א ע' רצט ואילך. [וראה לקו\"א להה\"מ סי' רכא (נד, א): סוד ב' פתחים. . ר\"ל אהבה ויראה. עיי\"ש]."]]],[2000510444,"מתחילי' מודה אני, וזהו בחי' המזוזה דהוד. וצריך לנצח בהודאה זו כי ענין ההודאה הוא לפי שאינו משיג זה כ\"א מודה כמ\"ש ענין זה במ\"א באריכות<sup data-n=\"1479\">18</sup>, ולכן צ\"ל בבחי' נצח לנצח א\"ע להיות בבחי' הודאה, עד שמגיע ע\"י התעוררות רחמים לבחי' העבודה דלאסתכלא ביקרא דמלכא, וזהו פתח א'. והפתח השני שתי המזוזות הם חו\"ג, והמשקוף הוא הדעת שנחלק לחו\"ג, והיינו בעבודה דואהבת וגו' בכל לבבך בשני יצריך שהם חו\"ג, עד שמגיע לבחי' הדעת להיות בבחי' דע את אלקי אביך ועבדהו בלב שלם, פי' לב שלם היינו בשני יצריך ואז העבודה היא בשלימות, וזהו הפתח השני. ועוד יש שני פתחים היינו הפתח האחד [שתי המזוזות] הוא חו\"ב והמשקוף כתר, וגם ג' ראשי ראשים הם ג\"כ משקוף ושתי המזוזות. אך מה שאמרו לעולם יכנס אדם שיעור שני פתחים היינו שהעבודה שיוכל האדם להגיע מלמטלמ\"ע הוא רק שני הפתחים [התחתונים], ושני הפתחים העליונים נותנים לו בבחי' מתנה מלמעלמ\"ט, אמנם כמו שהנותן מתנה אינו נותן כ\"א למי דעביד לי' נייחא, כן אין נותנים מלמעלה בחי' שני הפתחים העליונים כ\"א למי שהגיע בעבודתו ונכנס שיעור שני פתחים שמלמטלמ\"ע, ואז נותנים לו בחי' שני פתחים שמלמעלמ\"ט.\n<b>ועפ\"ז</b> יובן ענין דוד ויהונתן, שדוד הוא בחי' הב' דלת\"ן שמלמטלמ\"ע, ויהונתן הי' לו מס\"נ על דוד שקראו שאול בן נעות המרדות והכלימו והוא עמד במס\"נ על בחי' השני פתחים הנ\"ל ניתוסף לו ה\"א שהוא מהפתחים העליונים, וכמו יוסף שע\"י הבירור זכה לה\"א עילאה כן יהונתן ע\"י המס\"נ דדוד זכה ג\"כ לה\"א, ולכן עד הכריתות ברית דדוד הי' נק' יונתן ואח\"כ ע\"י דוד ניתוסף לו ה\"א, כענין בעטרה שעטרה לו אמו ביום חתונתו דוקא, כן ע\"י חיבורו בשכינתי' בחי' דוד שהי' מרכבה לבחי' המל' זכה לתוס' ה\"א, וכמו יוסף יהוסף.\n<b></b>[עה)] ומעתה יובן ג\"כ ענין הסימן שמסר לדוד שיורה בקשת<sup data-n=\"1480\">19</sup> אם החצים ממך והנה קחנה ובואה כי שלום לך אין דבר, פי' הקשת הוא ג' בני נח שהם ג' גווני הקשת<sup data-n=\"1481\">20</sup>, והחצים שמורים בקשת זהו בחי' הבירורים שמבררים מבחי' התהו, שהם ז' מלכין קדמאי' ושבעים לשון שכל אלו הם מבני נח, ולכן אמר לו אם יאמר הנה החצים ממך והנה היינו שגמר כל הבירורים, קחנה ובואה כי שלום לך שכבר נגמר הבירורים, אין דבר, פי' שאין דבר עוד הצריך בירור, ואם יאמר הנה החצים ממך והלאה לך כי שלחך ה', פי' שלחך לברר בירורים עוד שעדיין לא נשלמו הבירורים. והי' צריך לידע זאת משאול להיות כי שאול הי' מלך הראשון על",[["1479","18","<b>ענין ההודאה. . שאינו משיג זה כ\"א מודה כמ\"ש. . במ\"א באריכות</b>: ראה סידור עם דא\"ח שג, ג ואילך. שו, ב ואילך."],["1480","19","<b>ומעתה יובן ג\"כ ענין הסימן. . שיורה בקשת</b>: בהבא לקמן עד סוף המאמר ראה אוה\"ת בראשית שם כא, ב ואילך."],["1481","20","<b>הקשת הוא ג' בני נח שהם ג' גווני הקשת</b>: ראה תו\"א וישב כו, ג. אוה\"ת וישב רנב, א. שם (כרך ה) תתפח, ב ואילך. אוה\"ת נצבים ע' א'רא. וראה גם אוה\"ת בראשית שם כא, רע\"ב."]]],[2000510445,"ישראל, וארז\"ל ג' מצות נצטוו ישראל בכניסתן לארץ למנות להם מלך ולהכרית זרעו כו', ואם הי' שאול מחרים את עמלק בשלימות אז הי' גמר הבירורים, כי מלחמה לה' בעמלק מדור דור, ומפני כי מחל על מיטב הצאן והבקר והביא את אגג חי, הגם כי שיסף אותו שמואל אח\"כ, אך נודע מארז\"ל שנשאר בינתיים זכר ממנו, לכן הי' צריך יהונתן לידע משאול אביו איך מחזיק ענין הבירורי' דעמלק, ולכן א\"ל מחר חדש ונפקדת ואז אדע איך הענין עומד ואודיע לך ע\"י שאורה בקשת ומסר לו סימן הנ\"ל.\n<b>וביאור</b> הענין, דהנה ענין הקשת אשר בענן הוא אור חוזר מהכאת השמש בעננים נעשה אור חוזר מזיו השמש, ונעשה ג' גווני הקשת בענן. והקשו החוקרים איזהו אות ברית הוא ה\"ה טבעית<sup data-n=\"1482\">21</sup>, אך הלא קודם המבול לא הי' נראה. והענין הוא דשורש ענין הקשת זה כענין אור חוזר, והיינו כמו ג' אוירים אויר העליון חם והתחתון ג\"כ חם והאמצעי קר<sup data-n=\"1483\">22</sup>, והיינו כי אויר העליון חם והולך ומתקרר אח\"כ עד שמגיע לארץ וע\"י הכאת השמש בארץ נעשה אור חוזר ונעשה אויר התחתון ג\"כ חם. ועד\"ז יובן מגווני הקשת שיהי' בענן ביום הגשם הוא מהכאת השמש על העננים והי' בענני ענן ונראתה הקשת שהוא בחי' אור חוזר מהשמש כו'. ובעבודה ענין העלאות הניצוצות ז\"ע בחי' אור חוזר היינו להחזיר הניצוצות שנפלו בשבה\"כ, ולכן הקשת אשר יהי' בענן הוא סימן שלא יהי' עוד מבול לשחת כל בשר הגם כי לא אכשיר דרא, ומ\"מ הוא סימן שמבררים ניצוצות שמזה הוא האור חוזר כו', ולכן כשיהי' הקשת בגוונין נהירין זהו אות שכבר ביררו כל הניצוצות ואז יצפה לרגלי משיח, ונמצא פי' מחר חדש ע\"ד היום לעשותם ולמחר לקבל שכרם. ושלשת הוא בחי' סגול היינו בחי' והייתם לי סגולה<sup data-n=\"1484\">23</sup> מכל העמים, וזהו תרד מאד הוא בחי' הירידה לברר בירורים ולירד במקום המתברר וכמ\"ש במ\"א בד\"ה ולאחותו הבתולה<sup data-n=\"1485\">24</sup> בענין ויז נצחם על בגדי, וזהו תרד מאד. גם סגול הוא ג' נקודות ב' בשוה והשלישית תחתיהם, וזהו ע\"י תרד מאד ואז מצד ההסתר בא לבחי' בכל מאדך בלי גבול, וזהו ע\"י שמשפיל א\"ע לבחי' קצה התחתון כו', ושם מתחת זרועות עולם בחי' סוכ\"ע כו'.\n<b>וזהו</b> כמראה הקשת אשר יהי' בענן ביום הגשם הוא בחי' העלאת הניצוצות שבזה\"ג, כן מראה הנוגה סביב הוא מראה דמות כבוד ה', שראה יחזקאל",[["1482","21","<b>הקשת. . הוא אור חוזר מהכאת השמש. . והקשו החוקרים. . ה\"ה טבעית</b>: ראה בארוכה אוה\"ת נח (כרך ג) תרמח, א ואילך. סה\"מ תרנ\"ד ס\"ע מז-ח. לקו\"ש חט\"ו ע' 52. וראה גם פלח הרמון בראשית צז, סע\"א."],["1483","22","<b>ג' אוירים אויר העליון חם והתחתון ג\"כ חם והאמצעי קר</b>: ראה לקו\"ת ואתחנן ה, ג. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשמא. אוה\"ת בחוקותי ע' תרצב. נ\"ך ע' שמט. סה\"מ תר\"ל ע' רלט. וראה גם אוה\"ת נח (כרך ג) שם תרנא, א."],["1484","23","<b>ושלשת הוא בחי' סגול. . והייתם לי סגולה</b>: בהבא לקמן עד סוף הפיסקא ראה בארוכה מאמרי אדה\"ז תקס\"ז ע' סב ואילך. אוה\"ת בראשית יב, סע\"א ואילך. וראה גם תקס\"ז שם ע' נו. מאמרי אדהאמ\"צ במדבר ח\"א ע' קנב ואילך."],["1485","24","<b>וכמ\"ש במ\"א בד\"ה ולאחותו הבתולה</b>: סה\"מ תרכ\"ז ע' רעז ואילך. תרכ\"ט ע' קצ ואילך."]]],[2000510446,"בזה\"ג כמ\"ש ואני בתוך הגולה על נהר כבר שכבר הי' בה כמ\"ש במ\"א<sup data-n=\"1486\">25</sup>, ולכן ראה כמראה הקשת כו' ואראה ואפול על פני כו' כי לא הי' בו כח לקבל הגילוי הלזה בהיותו עומד על עמדו, אבל לע\"ל יהי' ונגלה כבוד ה' וראו כל בשר כי פי ה' דיבר ויוכלו לקבל זה, והיינו ע\"י העבודה דעכשיו שארז\"ל על ג' דברים העולם עומד, פי' עומד בבחי' קיום שיוכל לקבל בחי' דבר ה' בגילוי כו'.",[["1486","25","<b>מראה דמות כבוד ה' שראה יחזקאל בזה\"ג. . על נהר כבר שכבר הי' בה כמ\"ש במ\"א</b>: אוה\"ת נ\"ך ע' שצ ואילך וע' תרלב. שה\"ש (כרך א) ע' קל. שם (כרך ג) ע' תתנ."]]],[2000510447,"<h3>[וביום הביכורים]</h3>\n<b></b><b>[ד\"ה וביום הביכורים<sup data-n=\"1487\">1</sup>] </b>\nועפ\"ז כו' וביום הבכורים\nחה\"ש\nבס\"ד. (חג השבועות תרל\"א).\n<b></b>[עו)] ועפ\"ז יובן מה שנק' חג השבועות בשם יום הביכורים, כמ\"ש בפ' פנחס וביום הביכורים בהקריבכם מנחה חדשה לה', ופי' רש\"י שנק' יום הביכורים ע\"ש הקרבת שתי הלחם, והיינו דכתיב ממושבותיכם תביאו לחם תנופה וגו' סולת תהיינה חמץ תאפינה. ולכאו' מפני מה בחגה\"ש מקריבים לחם חמץ, משא\"כ בכל השנה דכתי' כל שאור וכל דבש לא תקטירו. וצריך לומר שמפני עוצם הגילוי דחגה\"ש יוכל גם חמץ להתקרב, וכענין שנת\"ל<sup data-n=\"1488\">2</sup> בענין גילוי דקרי\"ס שכל איש זר יוכל להתקרב, שהגם שנת' שם שאין הפי' איש זר לגמרי רק כענין הישראל שנק' זר לגבי הכהן, מ\"מ לאו בכל יומא זמנו שהזר כמו ישראל לגבי הכהן יוכל להתקרב אל הקדש פנימה, וכמו\"כ יובן שמחמת עוצם הגילוי דחגה\"ש יוכל גם חמץ להתקרב ולהתעלות. והגם שגם בחגה\"ש לא הקריבו את החמץ ע\"ג המזבח, כ\"א אכילה לכהנים<sup data-n=\"e72\">טו</sup> לבד, מ\"מ בכל השנה לא הקריבו חמץ גם לפני אכילת כהנים ג\"כ, כ\"א בחגה\"ש דוקא, וצ\"ל ענין הגילוי דחגה\"ש.",[["1487","1","<b>ועפ\"ז יובן. . וביום הביכורים</b>: מאמר זה הוא סיום המשך המאמרים והחרים תרל\"א\". תוכן המאמר (עד פיסקא: וזהו שאמר לע\"ל והחרים) נמצא בקיצור ובשינויים בהמאמר שלפנ\"ז (ד\"ה כמראה הקשת), וכאן הוא בהרחבה ובתוספת ביאור.\nלכללות המאמר ראה לקמן ע' שעד ד\"ה בענין והניף ידו על הנהר שהוא רישומי דברים ממאמר זה.\nהנחת הרה\"ח ר' אהרן זעליגסאן ממאמר זה כפי שנאמר ע\"י כ\"ק אדמו\"ר מהר\"ש, נדפסה לקמן בהוספות ע' שפג ואילך."],["1488","2","<b>וכענין שנת\"ל. . שכל איש זר יוכל להתקרב</b>: לעיל בסוף ד\"ה והחרים (ע' רסו).\n\n<b>טו</b>  <b>לא הקריבו את החמץ. . כ\"א אכילה לכהנים</b>: בשולי הגליון נרשם בגוכי\"ק: הגם כי לא למזבח כי אם לכהנים."]]],[2000510448,"<b>והענין</b> דחגה\"ש הוא יום החמשים<sup data-n=\"1489\">3</sup> מיצ\"מ וכמ\"ש תספרו חמשים יום, ואין סופרים כ\"א מ\"ט יום, והיינו כי יום הנו\"ן א\"א לספור אותו היינו להמשיכו ע\"י בחי' אתעדל\"ת דספה\"ע, כ\"א כאשר סופרים מ\"ט יום אז ממילא מתגלה אח\"כ בחי' שער החמשים כמ\"ש בלק\"ת<sup data-n=\"1490\">4</sup>.\n<b></b>[עז)] דהנה ארז\"ל במשנה דאבות עשרה דברים נבראו<sup data-n=\"1491\">5</sup> בערב שבת בין השמשות, וי\"א אף קבורתו של משה, ופי' הה\"מ בס' או\"ת<sup data-n=\"1492\">6</sup> כי יום ולילה זהו חו\"ג והמחברם הוא מבחי' האין דחכ', ע' בד\"ה לך לך<sup data-n=\"1493\">7</sup> בענין דאיברו שמיא מאש ומיא ולא הוי גלדא ואתגלידו בההוא רוחא עילאה, ובחי' אין זה הוא בחי' בין השמשות וכמשנת\"ל ענין בין השמשות, וזהו שאר\"י בין השמשות כהרף עין, י\"ל בחי' בריקת וסקירת אין דחכ'. אמנם עדיין צ\"ל מדוע המספר עשרה דברים דוקא שנבראו בערב שבת בין השמשות. והענין הוא דהנה מה שנברא העולם בעשרה מאמרות זהו מבחי' ע\"ס אך הם בחי' ע\"ס שבמל'<sup data-n=\"1494\">8</sup>, אמנם עשרה דברים שנבראו בערב שבת בין השמשות הם ג\"כ נגד ע\"ס אך [הם] בחי' ע\"ס דאצי' או עוד גבוה יותר בחי' ע\"ס הגנוזות, וכדי שיוכלו לבוא לבחי' בריאה להיות נבראי' גשמי' כו' לא נמצא לפניהם זמן כ\"א בין השמשות שהוא אינו זמן שנוכל לאמר כי הוא זה יום או לילה, כ\"א או יום ולילה או לא יום ולא לילה, וכל זמנו הוא הרף עין זה נכנס וזה יוצא, ומקוצר זמנו מובן ענין ביטולו כו', ולכן בחי' זמן זה מוכשר שבו יבואו לידי גילוי דברים אלו שנבראו בערב שבת בין השמשות שהם רובם ככולם יוצאים מדרכי הטבע, וכמו פי האתון והבאר והמן כו', ולכן ג\"כ הם עשרה דברים נגד ע\"ס. ולפ\"ז צ\"ל מהו וי\"א אף קבורתו של משה. והענין דהנה ארז\"ל אלמלא מקרא כתוב אי אפשר לאומרו, היכן מת משה בחלקו של ראובן דכתיב ויעל משה מערבות מואב אל הר נבו, ונבו בחלקו של ראובן, והיכן משה קבור בחלקו של גד דכתי' וירא כו' חלקת מחוקק ספון<sup data-n=\"1495\">9</sup>, מחלקו של ראובן עד חלקו של גד כמה הוי ד' מילין, מי הוליכו מלמד שהי' משה מוטל בכנפי שכינה, ומלאכי השרת אומרים צדקת כו', ושם י\"א לא מת משה כתיב הכא וימת שם, וכתיב התם ויהי שם, א\"ר חמא בר\"ח אף משה רבינו אינו יודע היכן קבור",[["1489","3","<b>והענין דחגה\"ש הוא יום החמשים</b>: בהבא לקמן (עד פיסקא: וזהו שאמר לע\"ל והחרים) ראה בקיצור (ובשינויים) לעיל בהמאמר שלפנ\"ז (ד\"ה כמראה הקשת)."],["1490","4","<b>יום הנו\"ן א\"א לספור. . ממילא מתגלה. . כמ\"ש בלק\"ת</b>: לקו\"ת במדבר יב, א ואילך."],["1491","5","<b>דהנה ארז\"ל במשנה. . עשרה דברים נבראו</b>: בהבא לקמן בפיסקא זו ראה אוה\"ת וירא ק, סע\"ב ואילך. ביאוה\"ז להצ\"צ (כרך ב) ע' תשעה-ו. וראה גם אוה\"ת ואתחנן ע' קנג."],["1492","6","<b>ופי' הה\"מ בס' או\"ת</b>: אור תורה ט, ד. שם יו\"ד, סע\"א. לקוטי אמרים להה\"מ סי' ז (ו, א). וסי' רג (נא, א). הובא ונת' באוה\"ת וירא שם ק, סע\"ב ואילך. ביאוה\"ז להצ\"צ שם ע' תשעה. וראה גם אוה\"ת יתרו ע' תתס. חקת ע' תתכ (בהוצאת תשנ\"ח)."],["1493","7","<b>ע' בד\"ה לך לך</b>: תרל\"א (לעיל ע' כג ואילך. וע' לז ואילך)."],["1494","8","<b>בעשרה מאמרות. . הם בחי' ע\"ס שבמל'</b>: ראה (באו\"א) אוה\"ת נ\"ך (כרך ב) ע' תתמא. סה\"מ תרנ\"ט ע' קמז. תש\"ד ע' 74."],["1495","9","<b>והיכן משה קבור. . דכתי' וירא חלקת מחוקק ספון</b>: כ\"ה הגירסא בעין יעקב לסוטה יג, ב. אך בדפוסי הש\"ס שלפנינו נדפס: דכתיב וירא ראשית לו וגו'."]]],[2000510449,"כתיב הכא ולא ידע איש את קבורתו וכתיב וזאת כו' איש האלקי'. פי' איש האלקים היינו שהי' מושל ושולט על בחי' ומדריגת שם אלקים, כי איש הוא מלשון מושל, וכענין שאה\"כ ואל אישך תשוקתך והוא ימשל בך, והגם כי מהלשון להיות כל איש שורר בביתו שהי' צריך ציווי המלך ע\"ז, משמע לכאו' שלפי שבאמת אינו כן לכן הי' צריך ציווי המלך ע\"ז, אמנם באמת אינו כן שזה הי' רק לצוות ולהזהיר לעשות כמו שהוא בעצם, וכנודע מדרז\"ל שזה הי' עצת מי שהי' צריך לזה, וכן מהראוי שיהי' כן וכמו איברי האדם נשמעים לרצונו, כן האשה שהיא אחת מצלעותיו היא צריכה להיות ציית להאיש שהוא מקורה כו'. ונמצא כי פי' איש האלקי' הוא כנ\"ל ל' מושל ושולט על בחי' ומדריגת אלקי' כענין צדיק מושל ביראת אלקי', ומ\"מ לא ידע את קבורתו.\n<b></b>[עח)] ולהבין כ\"ז צ\"ל ענין מ\"ת<sup data-n=\"1496\">10</sup> שארז\"ל לא ניתנו דברי תורה חתוכין למשה, אלא על כל דיבור ודיבור נאמר לו מ\"ט פנים טמא ומ\"ט פנים טהור כמ\"ש אמרות ה' אמרות טהורות מזוקק שבעתיים. וזהו דודי צח ואדום, צח הוא ב\"פ מ\"ט, גם צח ואדום הוא חו\"ג. וי\"ל שבתיבת צח שמורה על החסדים יש ברמז גם מ\"ט פנים טמא ג\"כ להורות התכללות הגבורה בחסד כענין לאכללא שמאלא בימינא. ובעבודה ב' בחי' אלו הם יצ\"ט ויצה\"ר ששרשם הוא מחו\"ג, וכדי להפוך ולהכניע היצה\"ר זהו ע\"י התורה שנק' עוז ותושי'<sup data-n=\"1497\">11</sup>, עוז שנותנת כח ביצ\"ט, ותושי' שמתשת כח היצה\"ר. והענין הוא דהנה כתי' כי שם חלקת מחוקק ספון<sup data-n=\"1498\">12</sup>, מחקק בגימט' רמ\"ח הוא בחי' רמ\"ח מ\"ע, וספון הוא מל' ספינה, והיינו שע\"י רמ\"ח הולכים על הים כמו בספינה, והיינו כי כמו ע\"י הספינה גם ברואים שביבשה יכולים לילך בים<sup data-n=\"1499\">13</sup>, ובלא הספינה א\"א לברואים שביבשה לילך בתוך הים, וענין השיטה במים זהו רק משך [זמן] קטן ושטח קטן, שאינו שייך לקרותו בשם הילוך כלל, אבל ע\"י הספינה יכולים לילך בים כמה וכמה ימים, כן יובן שע\"י מעשה המצות שנתלבשו בדברים גשמי' יכולה הנה\"א שהיא חלק אלק' ממעל רק שירדה ונתלבשה בגוף הגשמי ובנה\"ב המעלמת ומסתרת אורה, אמנם ע\"י מעשה המצות הגם שהנשמה נתלבשה בגוף גשמי, וגם מעשה המצות הם בדברים גשמי' מ\"מ בהם וע\"י יכולים הנשמות להשיג כמו בעלמא דאתכסיא ויתר ע\"ז, והרי מכוונת המצוה נעשה לבוש לנשמה בג\"ע העליון, והמצוה היא יתר ע\"ז הרבה כו'.\n<b>ועפ\"ז</b> יובן ג\"כ מה שהיו צריכים לקרי\"ס, דהנה כל האותות והמופתים שהיו במצרים הי' בכדי שיהי' יצ\"מ שיצאו מגלות עול פרעה, אבל קרי\"ס לכאו'",[["1496","10","<b>ולהבין כ\"ז צ\"ל ענין מ\"ת</b>: בהבא לקמן ראה אוה\"ת יתרו ע' תתצא-ב. סה\"מ תרכ\"ז ס\"ע שב ואילך. שיג. סה\"מ תרנ\"ח ע' מד. עת\"ר ע' קיז-ח. עטר\"ת ס\"ע תג-ד. תרפ\"ח ע' קלא-ב."],["1497","11","<b>התורה שנק' עוז ותושי'</b>: ראה תו\"א יתרו סז, סע\"א-ב. ועוד."],["1498","12","<b>דהנה כתי' כי שם חלקת מחוקק ספון</b>: בהבא לקמן עד סוף הפיסקא ראה ביאוה\"ז להצ\"צ (כרך ב) שם ע' תשעה-ו."],["1499","13","<b>כמו ע\"י הספינה. . יכולים לילך בים</b>: בכ\"ז ראה ביאוה\"ז לאדהאמ\"צ מא, סע\"ג ואילך."]]],[2000510450,"אינו צריך כלל, ולמה הי' לו ית' לחזק לב פרעה לרדוף אחר בנ\"י ושבני ישראל ילכו ביבשה בתוך הים. אלא שזה הי' הקדמה למ\"ת, דהנה במ\"ת ניתן תומ\"צ שהם בחי' ספינה שבהם וע\"י ילכו ישראל בעשיית המצות בעלמא דאתכסיא, ואיך ילכו בדרך התומ\"צ והם אינם יודעי' עדיין כלל סדר וענין עלמא דאתכסיא, לזה קרע לנו את הים שהוא בחי' עלמא דאתכסיא ונעשה יבשה, שזהו אם עליית הבריאה באצי' או המשכת אצי' בבי\"ע לפי ב' הפי' הנ\"ל, ואיך שיהי' הרי נעשה מים יבשה וראו הגילוי מעלמא דאתכסי', ואח\"כ ניתן התומ\"צ שבהם וע\"י נמשך מבחי' עלמא דאתכסיא בעלמא דאתגליא. ולכן מברכין על כל מצוה ברוך אתה ה' אלקינו מלך העולם שהוא ההמשכה להיות ברוך ה' מהעולם ועד העולם מעדאת\"כ לעלמא דאתגליא כמ\"ש במ\"א<sup data-n=\"1500\">14</sup>. ושורש ההפרש שבין קרי\"ס למ\"ת, שבקרי\"ס הי' בדרך אתעדל\"ע לבד וכמ\"ש מה תצעק אלי בעתיקא תליא כו', וע\"י מ\"ת שניתן לנו התומ\"צ ה\"ז בדרך אתעדל\"ת אתעדל\"ע. וי\"ל שקרי\"ס הי' ע\"ד אתעדל\"ע שמעורר אתעדל\"ת, להיות כי ראו והשיגו בעת הילוכם אור הגדול שבעלמא דאתכסי', ה\"ז הי' להם לאתעדל\"ע שאחר שניתן התומ\"צ שימשיכו בחי' זו וביתר שאת ע\"י אתעדל\"ת דקיום התומ\"צ (וגם כי בקרי\"ס הי' גילוי אור האצי' רק בבריאה לפי ב' הפי', ומזה נעשה למטה הפך ים ליבשה, וע\"י עשיית התומ\"צ ממשיכי' זה בעשי' הגשמי', שכשעושה המצוה הרי בעת עשייתה הוא בעלמא דאתכסיא, והגם כי אינו משיג זה מ\"מ הרי נפשו נלבשת בלבוש זה וגם אבריו נעשו מרכבה לגילוי זה כמ\"ש בסש\"ב פך\"ג בענין היד הנותנת הצדקה כו'). ועוד זאת שבקרי\"ס הי' רק לפי שעה, אבל ע\"י קיום התומ\"צ ה\"ז בכל עת ובכל זמן שעושה המצוה שהיא נוהגת בכל עת.\n<b></b>[עט)] ועפ\"ז יובן שרש ענין ההתחדשות דמ\"ת<sup data-n=\"1501\">15</sup>, דלכאו' הלא גם האבות קיימו כל התורה כולה עד שלא ניתנה. אך הענין דהנה האבות קיימו כל התורה ע\"י עובדות שלהם בכח מס\"נ לאלקות וכמ\"ש בס' הבהיר הובא בפרד\"ס שאמרה מדת החסד כל ימי היות אברם בארץ לא הוצרכתי לעשות מלאכתי, שהרי אברהם עומד ומשמש במקומי, וישמור משמרתי ששמר משמרת מדת החסד כו', וזהו ע\"י שהי' נדיב בנפשו ובגופו ובממונו כמ\"ש באו\"צ<sup data-n=\"1502\">16</sup> שער י\"ז הוא שער הנדיבות, שכ\"ז הי' בכח עצמו במס\"נ עצומה. אבל כשניתן לנו התומ\"צ הרי ע\"י עשיית המצוה שעושה ה\"ה ממשיך כל המשכות עליונות עוד ביתר שאת מכמו המשכת האבות, שהרי ארז\"ל כל המצות שעשו האבות ריחות היו, אבל אנו שמן תורק דבר שמריקין כו', פי' ריח הוא הארה בעלמא להיות כי הי' זה בכח עצמן, והגם שהיו במס\"נ מ\"מ כח הנברא מצ\"ע אינו יכול להגיע במעלות כ\"כ כמו מי שמצווה ועושה שזהו מכח",[["1500","14","<b>מהעולם ועד העולם מעדאת\"כ לעלמא דאתגליא כמ\"ש במ\"א</b>: ראה סה\"מ תרכ\"ו ע' קלג. תרכ\"ז ע' שצה. תרכ\"ט ע' ב. תרל\"ב ח\"ב ע' תמו. וע' תקנה."],["1501","15","<b>ועפ\"ז יובן שורש ענין ההתחדשות דמ\"ת</b>: בהבא לקמן ראה בארוכה לעיל ד\"ה וכל העם. וש\"נ."],["1502","16","<b>שהי' נדיב בנפשו ובגופו ובממונו כמ\"ש באו\"צ</b>: בס' אורחות צדיקים. הובא ונת' בסה\"מ תרפ\"ט ע' 90 ואילך. תרח\"צ ע' קכט ואילך."]]],[2000510451,"הציווי דא\"ס כל יכול כו'. ולכן גם כשעושין המצוה בלא מס\"נ כ\"א שעושה בכוונה בכדי לקיים מצות בוראו, הרי עי\"ז הוא ממשיך המשכות עליונות מא\"ס ב\"ה רצה\"ע שתרי\"ג מצות דאורייתא וז' דרבנן הם תר\"ך עמודי אור כו', ועי\"ז מאיר על נפשו להלבישה בלבוש המצות כמ\"ש במ\"א<sup data-n=\"1503\">17</sup>. ומ\"מ צריך שיקיים המצות בדרך עבודת עבד ולקשר א\"ע לעשיית המצוה שלא יעשנה בקרירות כדרך מצות אנשים מלומדה, וכמ\"ש בטוש\"ע שבהנחת תפילין צריך לשעבד הלב והמוח, וע\"י הכוונה זו הפשוטה מלובש בה כל פרטי כוונת המצוה שבה וע\"י תתעלה נפש האדם. וזהו מ\"ש אני כברוש רענן<sup data-n=\"1504\">18</sup>, שכמו הברוש שהוא עץ גבוה מאד כשכופפין אותו ומניחי' עליו איזהו דבר הנה כשנזקף מכפיפותו מגביה דבר המונח עליו, כן נמשל בחי' אני שהוא מ\"ש אני ה' בהרבה מצות ה\"ה כברוש רענן, שהמצות נשפלו למטה בעשי' וע\"י שהאדם עושה ומקיים מעשה המצות עי\"ז הם מגביהים את האדם למעלה ממקור חוצבו, שלכן הם הם המלאכי אלקי' שעולים ויורדי' בסולם כמ\"ש במד\"ת, והיינו שירדו להתלבש בדברים גשמי' בכדי שבהם וע\"י יתעלו הדברים הגשמי' ג\"כ לאלקות והאדם העושה אותם, ויש בהם פרטי' רבים, כמו שבת הוא בחי' מוחי' דאבא, וסוכה הוא מקיפי' דבינה, ובכלל ג' רגלים הם בתי אחותי אמי כו', ותפילין ד' מוחין, וציצית הם ל\"ב נתיבות חכ', וכדומה בכל פרטי המצות שבהם וע\"י מתעלה נפש האדם כמו העולה בסולם כו'. וזהו שנא' חלקת מחקק ספון, מחקק רמ\"ח מ\"ע שנק' בשם ספון לשון ספינה, והיינו שכמו הספינה היא אמצעי' שבה וע\"י הולך האדם בים, כן מעשה המצות הם בחי' ספינה שבהם וע\"י ילך האדם העושה אותם בעלמא דאתכסיא גם בעודו חי בחיי הגשמי' כשהוא מקשר א\"ע למעשה המצות בעת עשיית המצוה עכ\"פ כו'.\n[פ)] <b>ומעתה</b> יובן ג\"כ מה שבחגה\"ש הי' יכול גם החמץ להתעלות, דהנה חמץ הוא בחי' יצה\"ר שנק' חמץ כמ\"ש מכף מעול וחומץ והיינו שיכול להתחמץ לגמרי, אמנם ע\"י הקרבת שתי הלחם מהפכין אותו מן הקצה אל הקצה, וזהו בחגה\"ש דוקא כי ע\"פ סדר השתלשלו' א\"א להעלות את החמץ כ\"א בדרך דחי' ע\"ד כל מל\"ת שהם ע\"ד דחי' שא\"א להתעלות, וכענין כלי חרס שבירתן זהו תקנתן, אמנם בחגה\"ש לעוצם מעלת הגילוי אז גם החמץ יוכל להתעלות, וע\"ד שארז\"ל עתיד חזיר ליטהר<sup data-n=\"1505\">19</sup>, וכמו הפגימה בשחיטה שיהי' מותר לע\"ל כמ\"ש ביאור ד\"ז באורך בלק\"ת<sup data-n=\"1506\">20</sup>, כן הארה מעין זה מחמת עוצם הגילוי דחגה\"ש גם החמץ יוכל להתעלות להיות עכ\"פ אכילה לכהנים. והיינו לפי שבחה\"ש כתי' והניף כו' על שני כבשים, פי'",[["1503","17","<b>שתרי\"ג מצות. . הם תר\"ך עמודי אור. . מאיר על נפשו להלבישה בלבוש המצות כמ\"ש במ\"א</b>: ראה אגה\"ק סכ\"ט (קמט, סע\"ב ואילך). ובארוכה סה\"מ מלוקט ח\"א ע' סה ואילך. ועוד."],["1504","18","<b>וזהו מ\"ש אני כברוש רענן</b>: בהבא לקמן ראה לקו\"ת אחרי כו, ב. דרושים ליוהכ\"פ סט, ג."],["1505","19","<b>וע\"ד שאמרז\"ל עתיד חזיר ליטהר</b>: נת' בסד\"ה והחרים תשמ\"ה. עיי\"ש. וראה בהנסמן ע\"ז בהערת כ\"ק אדמו\"ר בהמשך מים רבים תרל\"ו ע' פז."],["1506","20","<b>וכמו הפגימה בשחיטה. . כמ\"ש. . באורך בלק\"ת</b>: פ' שמיני יח, א ואילך. ובארוכה ספר השיחות תנש\"א ח\"ב ע' 566 ואילך."]]]]});
